/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Henri David */
/* The headphone jack's switch: PB5, an input (as the boot leaves it: enabled, no pull set here), 0 with headphones in,
 * 1 with nothing plugged (measured on an FM-1 2026-10-29 with a probe of the input registers). Read only: its
 * direction, pull and function are never written. The debounce is the caller's (fm1-base: plat_headphones).
 *
 *   fm1_hp_in()   1: headphones in (the pin's raw state, bouncing ~150 ms a plug) */
#pragma once
#include <stdint.h>
#include "fm1_gpio.h"

#define FM1_HP_PIN 5u                   /* PB5 */
static inline uint32_t fm1_hp_in(void) { return !(FM1_PR(FM1_PB, FM1_IN) >> FM1_HP_PIN & 1u); }

text.fm1-base/bsp/boards/fm1/fm1_lcd.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments
 * Copyright (C) 2026 Kerem Kilic (Ellic Studio) */
/* FM-1 ST7789 panel: blocking, top-left origin, native RGB565 colours.
 * No framebuffer required; a 480-byte static row buffer stages each pixel row
 * (a header static: each compilation unit that includes this gets its own).
 * Calls must be serialized (including against users of fm1_lcd_hw.h).
 * 0 = success (also empty rectangles), -1 = SPI timeout, -2 = bad bounds/buffer.
 * A timeout deselects and switches SPI1 off (fm1_lcd_spi_off; fm1_lcd_hw.h's own
 * fm1_lcd_wait leaves it on); call fm1_lcd_init() before retrying.
 * See docs/BOARD_IO.md for ownership, lifetime and backlight details. */
#pragma once
#include <stdint.h>
#include "fm1_time.h"
#include "fm1_lcd_hw.h"

#define FM1_LCD_WIDTH 240u
#define FM1_LCD_HEIGHT 240u
static uint8_t fm1_lcd_row[FM1_LCD_WIDTH * 2u];

/* the end of a transfer: wait, deselect; after a timeout, the SPI off until fm1_lcd_init */
static int fm1_lcd_done(void)
{
    int rc = fm1_lcd_wait();
    fm1_lcd_deselect();
    if (rc)
        fm1_lcd_spi_off();
    return rc;
}

static int fm1_lcd_command(uint8_t cmd, const uint8_t *data, uint32_t n)
{
    static uint8_t args[4];                    /* DMA reads RAM, not XIP constants */
    uint32_t i;
    int rc;
    if (n > sizeof args || (n && !data))
        return -2;
    fm1_lcd_send_cmd(cmd);
    rc = fm1_lcd_done();
    if (rc || !n)
        return rc;
    for (i = 0; i < n; i++)
        args[i] = data[i];
    fm1_lcd_send_data(args, n);
    return fm1_lcd_done();
}

static int fm1_lcd_init(void)
{
    static const uint8_t colmod = 0x55, madctl = 0;
    fm1_lcd_hw_init();
    fm1_delay_ms(50);
    if (fm1_lcd_command(0x01, 0, 0)) return -1; /* SWRESET */
    fm1_delay_ms(150);
    if (fm1_lcd_command(0x11, 0, 0)) return -1; /* SLPOUT */
    fm1_delay_ms(120);
    if (fm1_lcd_command(0x3A, &colmod, 1) ||    /* RGB565 */
        fm1_lcd_command(0x36, &madctl, 1) ||    /* top-left, RGB */
        fm1_lcd_command(0x21, 0, 0) ||         /* IPS inversion */
        fm1_lcd_command(0x13, 0, 0) ||         /* normal mode */
        fm1_lcd_command(0x29, 0, 0))           /* display on */
        return -1;
    fm1_lcd_baud(4);
    return 0;
}

FM1_INLINE int fm1_lcd_bounds(uint32_t x, uint32_t y, uint32_t w, uint32_t h)
{
    return x < FM1_LCD_WIDTH && y < FM1_LCD_HEIGHT &&
           w <= FM1_LCD_WIDTH - x && h <= FM1_LCD_HEIGHT - y;
}

static int fm1_lcd_window(uint32_t x, uint32_t y, uint32_t w, uint32_t h)
{
    uint8_t a[4] = { 0, (uint8_t)x, 0, (uint8_t)(x + w - 1u) };
    if (fm1_lcd_command(0x2A, a, 4)) return -1;
    a[1] = (uint8_t)y;
    a[3] = (uint8_t)(y + h - 1u);
    if (fm1_lcd_command(0x2B, a, 4)) return -1;
    return fm1_lcd_command(0x2C, 0, 0);
}

static int fm1_lcd_row_send(uint32_t w)
{
    fm1_lcd_send_data(fm1_lcd_row, w * 2u);
    return fm1_lcd_done();
}

static int fm1_lcd_fill_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t rgb)
{
    uint32_t i;
    if (!w || !h) return 0;
    if (!fm1_lcd_bounds(x, y, w, h)) return -2;
    if (fm1_lcd_window(x, y, w, h)) return -1;
    for (i = 0; i < w; i++) {
        fm1_lcd_row[2u * i] = (uint8_t)(rgb >> 8);
        fm1_lcd_row[2u * i + 1u] = (uint8_t)rgb;
    }
    for (i = 0; i < h; i++)
        if (fm1_lcd_row_send(w)) return -1;
    return 0;
}

/* Contiguous row-major native uint16_t RGB565, in RAM or XIP; pixel_count
 * is the caller's available element count. Source may be reused on return. */
static int fm1_lcd_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h,
                        const uint16_t *pixels, uint32_t pixel_count)
{
    uint32_t row, col;
    if (!w || !h) return 0;
    if (!fm1_lcd_bounds(x, y, w, h) || !pixels || pixel_count < w * h)
        return -2;
    if (fm1_lcd_window(x, y, w, h)) return -1;
    for (row = 0; row < h; row++) {
        for (col = 0; col < w; col++) {
            uint16_t rgb = pixels[row * w + col];
            fm1_lcd_row[2u * col] = (uint8_t)(rgb >> 8);
            fm1_lcd_row[2u * col + 1u] = (uint8_t)rgb;
        }
        if (fm1_lcd_row_send(w)) return -1;
    }
    return 0;
}

text.fm1-base/bsp/boards/fm1/fm1_lcd_hw.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments
 * Copyright (C) 2026 Kerem Kilic (Ellic Studio): the transport's status, register hook */
/* FM-1 LCD wiring: SPI1 on PC9 CLK, PC10 DO, PC7 CS,
 * PC8 D/C; backlight PA2, active low. Panel protocol: fm1_lcd.h.
 *
 *   fm1_lcd_hw_init()          pins, backlight on, SPI1 master at BAUD 4
 *   fm1_lcd_baud(b)            SPI1 clock = lsb / (b + 1)
 *   fm1_lcd_send_cmd(c)        D/C low, CS low, one byte (then fm1_lcd_wait)
 *   fm1_lcd_send_data(p, n)    D/C high, CS low, DMA n bytes from RAM p
 *   fm1_lcd_wait()             0 done, -1 timeout (counted); pending cleared, the SPI left on either way
 *   fm1_lcd_spi_off()          SPI1 off (fm1_lcd.h after a timeout; fm1_lcd_hw_init turns it on again)
 *   fm1_lcd_deselect()         CS high
 *   fm1_lcd_backlight(on)      PA2 low (on) / high (off); the TIMER5 scan writes port A too: IRQs off around it
 */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"

#ifndef FM1_LCD_REG
#define FM1_LCD_REG(addr) (*(volatile uint32_t *)(addr))
#endif
#define FM1_LCD_PC_OUT FM1_LCD_REG(0x50080u)
#define FM1_LCD_PC_DIR FM1_LCD_REG(0x50088u)
#define FM1_LCD_IOMAP_CON1 FM1_LCD_REG(0x51020u)
#define FM1_LCD_SPI_CON FM1_LCD_REG(0x11D00u)
#define FM1_LCD_SPI_BAUD FM1_LCD_REG(0x11D04u)
#define FM1_LCD_SPI_BUF FM1_LCD_REG(0x11D08u)
#define FM1_LCD_SPI_ADR FM1_LCD_REG(0x11D0Cu)
#define FM1_LCD_SPI_CNT FM1_LCD_REG(0x11D10u)
#define FM1_LCD_PA_OUT FM1_LCD_REG(0x50000u)
#define FM1_LCD_PA_DIR FM1_LCD_REG(0x50008u)
#define FM1_LCD_BL (1u << 2)
#define FM1_LCD_CS (1u << 7)
#define FM1_LCD_DC (1u << 8)
#define FM1_LCD_CLK (1u << 9)
#define FM1_LCD_DO (1u << 10)

static uint32_t fm1_lcd_timeouts;

FM1_INLINE void fm1_lcd_hw_init(void)
{
    FM1_LCD_PA_OUT &= ~FM1_LCD_BL;
    FM1_LCD_PA_DIR &= ~FM1_LCD_BL;
    FM1_LCD_IOMAP_CON1 |= 0x10u;
    FM1_LCD_PC_OUT |= FM1_LCD_CS;
    FM1_LCD_PC_OUT &= ~(FM1_LCD_DC | FM1_LCD_CLK | FM1_LCD_DO);
    FM1_LCD_PC_DIR &= ~(FM1_LCD_CS | FM1_LCD_DC | FM1_LCD_CLK | FM1_LCD_DO);
    FM1_LCD_SPI_CON = 0x4021u;
    FM1_LCD_SPI_BAUD = 4u;
}

FM1_INLINE void fm1_lcd_backlight(uint32_t on)
{
    if (on)
        FM1_LCD_PA_OUT &= ~FM1_LCD_BL;
    else
        FM1_LCD_PA_OUT |= FM1_LCD_BL;
}

FM1_INLINE void fm1_lcd_baud(uint32_t b) { FM1_LCD_SPI_BAUD = b; }

/* A timeout is counted and reported, and the SPI stays on: callers that init once and ignore the result (fm1-base's
 * device/lcd.c, loader/ldr_screen.c) go on drawing, as before. Switching it off is fm1_lcd.h's, which re-inits. */
static int fm1_lcd_wait(void)
{
    uint32_t n;
    int rc = 0;
    for (n = 0; n < 4000000u && !(FM1_LCD_SPI_CON & 0x8000u); n++)
        ;
    if (n == 4000000u) {
        fm1_lcd_timeouts++;
        rc = -1;
    }
    FM1_LCD_SPI_CON |= 0x4000u;
    return rc;
}

FM1_INLINE void fm1_lcd_spi_off(void) { FM1_LCD_SPI_CON &= ~1u; }

FM1_INLINE void fm1_lcd_deselect(void) { FM1_LCD_PC_OUT |= FM1_LCD_CS; }

FM1_INLINE void fm1_lcd_send_cmd(uint8_t c)
{
    FM1_LCD_PC_OUT &= ~FM1_LCD_DC;
    FM1_LCD_PC_OUT &= ~FM1_LCD_CS;
    FM1_LCD_SPI_CON |= 0x4000u;
    FM1_LCD_SPI_BUF = c;
}

FM1_INLINE void fm1_lcd_send_data(const void *p, uint32_t n)
{
    FM1_LCD_PC_OUT |= FM1_LCD_DC;
    FM1_LCD_PC_OUT &= ~FM1_LCD_CS;
    FM1_LCD_SPI_CON |= 0x4000u;
    FM1_LCD_SPI_ADR = (uint32_t)(uintptr_t)p;
    FM1_LCD_SPI_CNT = n;
}

text.fm1-base/bsp/boards/fm1/fm1_led_anim.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* The power-on LED sweep (Felucca 1.1, Discussion #135): its picture, frame by frame. Pure (no hardware): the
 * driver (hal/fm1_input.h fm1_led_anim_start, from the TIMER5 scan) and the browser emulator (web/emu) show it.
 *
 * A soft light runs over the keys from left to right, a bright head with a fading tail, then the buttons swell up
 * and settle. In frames of the scan (11 ticks of 100 us, 1.1 ms; ~909 a second), FM1_ANIM_FRAMES in all (~0.70 s):
 *   keys      frames 0..FM1_ANIM_SWEEP (~0.56 s): the head from 1.5 half white keys left of F3 to 8 right of G5,
 *             at a steady ~75 half white keys a second (F3 to G5, 30 of them, in ~0.43 s). The keys in the order of
 *             their place on the keyboard (FM1_ANIM_X, in half white keys: a black key between its two whites);
 *   buttons   frames FM1_ANIM_BTN0..FM1_ANIM_FRAMES (~0.39 .. 0.70 s): together, from dark up to a quarter of lit
 *             (FM1_ANIM_BTN_PK, ~0.55 s) and down to the glow, a level the eye sees fall evenly (an exponential).
 * A key's brightness is 2^-e of lit, e = 0.75 per half white key behind the head (the tail: ~59 % of lit one key
 * back, ~35 % two, ~21, ~12, ~7 %, then the glow: 4..6 keys), 2.5 ahead (a soft front over ~2 keys). Levels, /64
 * of lit (FM1_ANIM_FULL): from 4 /64 up (~6 %) lit frames, fewer down to the glow (the glow under them as well);
 * below that the glow (hal/fm1_input.h fm1_led_dim, ~1/30 of lit) down to ~2 % of lit, dark under it. With `glow`
 * (MENU > LEDS DIM HI / DIM LO: the idle glow) the keys the head has passed keep the glow, the buttons settle on it:
 * the last frame is the idle picture's glow; without (LEDS OFF / INV) all goes dark. A frame at or past
 * FM1_ANIM_FRAMES is that last picture. */
#pragma once
#include <stdint.h>

#define FM1_ANIM_FRAMES 640u      /* the whole sweep, frames (~0.70 s) */
#define FM1_ANIM_SWEEP 512u       /* the head's run (a power of 2) */
#define FM1_ANIM_H0 (-24)         /* the head at frame 0 and from FM1_ANIM_SWEEP: 1/16 half white key from F3 */
#define FM1_ANIM_H1 608
#define FM1_ANIM_BTN0 352u        /* the buttons: up from here, the peak, down until FM1_ANIM_FRAMES */
#define FM1_ANIM_BTN_PK 496u
#define FM1_ANIM_FULL 64u         /* a level: lit frames /64 */
#define FM1_ANIM_GLOW 0x80u       /* a level's flag: the glow under it */
#define FM1_ANIM_NBTN 14u         /* stock ids 0..13 buttons, 14..40 the keys F3..G5 */
#define FM1_ANIM_NKEY 27u

/* the 27 keys from F3: their place left to right, in half white keys (a black key half way between its whites) */
static const uint8_t FM1_ANIM_X[FM1_ANIM_NKEY] = {0, 1, 2, 3, 4, 5, 6, 8, 9, 10, 11, 12, 14, 15, 16, 17, 18, 19,
                                                  20, 22, 23, 24, 25, 26, 28, 29, 30};
static const uint16_t FM1_ANIM_POW[16] = {1024, 981, 939, 899, 861, 825, 790, 756,   /* 2^(-i/16) x 1024 */
                                          724, 693, 664, 636, 609, 583, 558, 535};

/* 2^(-e/16) of lit, /1024 (e >= 0) */
static uint32_t fm1_anim_bright(int32_t e)
{
    return e >= 176 ? 0u : (uint32_t)FM1_ANIM_POW[e & 15] >> (e >> 4);
}
/* a brightness /1024 as a level: lit frames /64 with the glow under them; under 4 /64 the glow (from ~2 %, or
 * always with `floor`), else dark */
static uint32_t fm1_anim_q(uint32_t b, uint32_t floor)
{
    uint32_t l = (b + 8u) >> 4;
    if (l >= 4u)
        return (l > FM1_ANIM_FULL ? FM1_ANIM_FULL : l) | FM1_ANIM_GLOW;
    return b >= 20u || floor ? FM1_ANIM_GLOW : 0u;
}
/* LED `id` (stock id: 0..13 a button, 14..40 a key) at frame f: its level (0..64 | FM1_ANIM_GLOW) */
static uint32_t fm1_anim_level(uint32_t f, uint32_t id, uint32_t glow)
{
    int32_t e, d;
    if (f >= FM1_ANIM_FRAMES)
        return glow ? FM1_ANIM_GLOW : 0u;
    if (id < FM1_ANIM_NBTN) {
        if (f < FM1_ANIM_BTN0)
            return 0;
        e = f < FM1_ANIM_BTN_PK ? 96 - (int32_t)(f - FM1_ANIM_BTN0) * 64 / (int32_t)(FM1_ANIM_BTN_PK - FM1_ANIM_BTN0)
                                : 32 + (int32_t)(f - FM1_ANIM_BTN_PK) * 48 / (int32_t)(FM1_ANIM_FRAMES - FM1_ANIM_BTN_PK);
        return fm1_anim_q(fm1_anim_bright(e), glow && f >= FM1_ANIM_BTN_PK);   /* 1/64 .. 1/4 .. 1/32 */
    }
    if (id >= FM1_ANIM_NBTN + FM1_ANIM_NKEY)
        return 0;
    d = FM1_ANIM_H0 + (int32_t)((uint32_t)(FM1_ANIM_H1 - FM1_ANIM_H0) * (f < FM1_ANIM_SWEEP ? f : FM1_ANIM_SWEEP) /
                                FM1_ANIM_SWEEP) - 16 * (int32_t)FM1_ANIM_X[id - FM1_ANIM_NBTN];   /* behind the head */
    e = d >= 0 ? (d * 3) >> 2 : (-d * 5) >> 1;    /* (no division: shifts) */
    return fm1_anim_q(fm1_anim_bright(e), glow && d > 0);
}

/* The idle animation (1.2, Discussion #135; MENU > ANIM IDLE, src/ui_input.c idle_leds): while the FM-1 sits idle a
 * soft light drifts over the keys from F3 to G5 and back, and the buttons breathe with it. Endless, in cycles of
 * FM1_IDLE_FRAMES frames (~9.0 s): the light's place eases from 0 to 30 half white keys in the first half and back in
 * the second (a smoothstep of a triangle, as the breath: it slows down at either end, ~4.5 s a way); a key's
 * brightness 2^-(e / 16) of lit, e = 24 + 16 per half white key from the light (~35 % of lit on it, half that a half
 * white key away: two or three keys softly lit, never a bright one). The buttons, all together, from 1/64 of lit (the
 * light at F3) up to 1/8 (at G5) and down again. With `glow` (MENU > LEDS DIM HI / DIM LO) every LED keeps the glow
 * under it; without (OFF / INV) the rest is dark. The same levels as the power-on sweep (fm1_anim_q: lit frames /64,
 * FM1_ANIM_GLOW): the scan draws them the same way. No division: shifts */
#define FM1_IDLE_FRAMES 8192u    /* a cycle (a power of 2), frames (~9.0 s) */
#define FM1_IDLE_E0 24           /* the light: 2^-1.5 of lit at its place */
static uint32_t fm1_idle_level(uint32_t f, uint32_t id, uint32_t glow)
{
    uint32_t x = f & (FM1_IDLE_FRAMES - 1u);
    int32_t d;
    x = (x & (FM1_IDLE_FRAMES / 2u) ? FM1_IDLE_FRAMES - 1u - x : x) >> 4;   /* a triangle 0..255 */
    x = x * x * (768u - 2u * x) >> 16;                 /* smoothstep, 0..255 */
    if (id < FM1_ANIM_NBTN)
        return fm1_anim_q(fm1_anim_bright(96 - (int32_t)(x * 48u >> 8)), glow);   /* 1/64 .. 1/8 */
    if (id >= FM1_ANIM_NBTN + FM1_ANIM_NKEY)
        return 0;
    d = (int32_t)(x * 480u >> 8) - 16 * (int32_t)FM1_ANIM_X[id - FM1_ANIM_NBTN];   /* 1/16 half white keys */
    return fm1_anim_q(fm1_anim_bright(FM1_IDLE_E0 + (d < 0 ? -d : d)), glow);
}

text.fm1-base/bsp/chip/fm1_ble.h:
/* SPDX-License-Identifier: GPL-3.0-only OR MPL-2.0 */
/* FM-1 (AC791N / WL82) BLE baseband: the registers, the link-column port, the interrupt lines and the radio
 * bring-up, for the route C driver (src/ble/ble_hw_wl82.c, FELUCCA_BLE). Written only from the clean-room fact
 * sheet docs/BLE-HW-FACTS.md (branch feat/ble-facts, 41b7374; §14-§17 from d907ce3): every register access names its
 * section there as "HW §n". Nothing in this file ran on a real FM-1; the emulator models only the baseband engine
 * (fm1-emulator feat/ble-engine), not the radio analog side.
 *
 *   fm1_ble_rf_init(trims)      the radio in stock's second-boot order (HW §16): the captured Wi-Fi front end with
 *                               the stored trims (hal/fm1_ble_rf.h), clocks and power, the BT analog block (HW §5.1,
 *                               §5.4); what stays TODO(hardware) is listed in fm1_ble_rf.h
 *   fm1_ble_bb_init(base, size) the BLE baseband (HW §5.5): enable, timing words, the baseband RAM window
 *   fm1_ble_col_wr / _rd        the per-link column port (HW §2.1 0x2801C/20/24, §2.3)
 *   fm1_ble_irq_attach(prio)    IRQ 45 (event) and IRQ 29 (RX) to the driver's bodies (HW §10)
 *   fm1_ble_rng32()             the random-number source (HW §1 0x13B00/04) */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"
#include "fm1_irq.h"
#include "fm1_time.h"
#include "fm1_ble_rf.h"   /* the captured start-up program (build/gen/ble_rf_tables.h) */

/* ---- BLE baseband registers (HW §2.1), all 32-bit accesses */
#define FM1_BLE_CON      (*(volatile uint32_t *)0x28000u)   /* bit0 enable, 13/14 init, 4 cleared */
#define FM1_BLE_T08      (*(volatile uint32_t *)0x28008u)   /* [9:0] 70, [15:12] 0xF */
#define FM1_BLE_T0C      (*(volatile uint32_t *)0x2800Cu)   /* [9:0] 70: a path delay in us [I] */
#define FM1_BLE_T10      (*(volatile uint32_t *)0x28010u)   /* 62 | 62 << 8 */
#define FM1_BLE_T14      (*(volatile uint32_t *)0x28014u)   /* 30 */
#define FM1_BLE_T18      (*(volatile uint32_t *)0x28018u)   /* 20 | 20 << 8 */
#define FM1_BLE_COLCMD   (*(volatile uint32_t *)0x2801Cu)   /* column << 10 | link << 4 | op (5 write, 2 read) */
#define FM1_BLE_COLDATA  (*(volatile uint32_t *)0x28020u)   /* the data word for op 5 */
#define FM1_BLE_COLRES   (*(volatile uint32_t *)0x28024u)   /* the result of op 2 */
#define FM1_BLE_IEN      (*(volatile uint32_t *)0x28028u)   /* bit n event (IRQ 45), bit 8+n RX (IRQ 29) */
#define FM1_BLE_IACK     (*(volatile uint32_t *)0x2802Cu)   /* write 1 to acknowledge */
#define FM1_BLE_IPND     (*(volatile uint32_t *)0x28030u)   /* pending, the same bits */
#define FM1_BLE_T34      (*(volatile uint32_t *)0x28034u)   /* bit0 1, [15:8] a parameter (stock 0x0A) */
#define FM1_BLE_STAT     (*(volatile uint32_t *)0x28038u)   /* bit1 busy; bit7 flag, acknowledged by bit6 */
#define FM1_BLE_G2EN     (*(volatile uint32_t *)0x2804Cu)   /* second group: bit n enable, bit 8+n acknowledge */
#define FM1_BLE_G2PND    (*(volatile uint32_t *)0x28050u)   /* second group pending */

/* ---- BT analog / configuration block (HW §2.2) */
#define FM1_BT_C00       (*(volatile uint32_t *)0x2FC00u)
#define FM1_BT_C04       (*(volatile uint32_t *)0x2FC04u)
#define FM1_BT_C08       (*(volatile uint32_t *)0x2FC08u)   /* [9:0], [19:10] stored I / Q trims */
#define FM1_BT_C0C       (*(volatile uint32_t *)0x2FC0Cu)
#define FM1_BT_C10       (*(volatile uint32_t *)0x2FC10u)   /* bytes 0..2 stored trims */
#define FM1_BT_C14       (*(volatile uint32_t *)0x2FC14u)
#define FM1_BT_C18       (*(volatile uint32_t *)0x2FC18u)
#define FM1_BT_C1C       (*(volatile uint32_t *)0x2FC1Cu)
#define FM1_BT_C20       (*(volatile uint32_t *)0x2FC20u)
#define FM1_BT_C24       (*(volatile uint32_t *)0x2FC24u)
#define FM1_BT_C28       (*(volatile uint32_t *)0x2FC28u)
#define FM1_BT_C40       (*(volatile uint32_t *)0x2FC40u)   /* BT block enable / config [I] */
#define FM1_BT_C48       (*(volatile uint32_t *)0x2FC48u)
#define FM1_BT_C78       (*(volatile uint32_t *)0x2FC78u)
#define FM1_BT_C7C       (*(volatile uint32_t *)0x2FC7Cu)
#define FM1_BT_BLE_EN    (*(volatile uint32_t *)0x2FC80u)   /* bit0 BLE block enable [I] */
#define FM1_BT_BB_BASE   (*(volatile uint32_t *)0x2FC84u)   /* baseband RAM base (an SRAM address) */
#define FM1_BT_PLL_TBL   (*(volatile uint32_t *)0x2FC88u)   /* the PLL channel table (an SRAM address) */
#define FM1_BT_C98       (*(volatile uint32_t *)0x2FC98u)
#define FM1_BT_C9C       (*(volatile uint32_t *)0x2FC9Cu)
#define FM1_BT_CA0       (*(volatile uint32_t *)0x2FCA0u)
#define FM1_BT_BB_END    (*(volatile uint32_t *)0x2FCBCu)   /* baseband RAM end = base + size */
#define FM1_BT_AGC0      (*(volatile uint32_t *)0x2FD80u)
#define FM1_BT_AGC(i)    (*(volatile uint32_t *)(0x2FD84u + 4u * (i)))   /* 0x2FD84 .. 0x2FD94 */
#define FM1_BT_BRCON     (*(volatile uint32_t *)0x20000u)   /* BR/EDR baseband control (HW §5.1 step 4) */
#define FM1_WL_BTEN      (*(volatile uint32_t *)0x14000u)   /* BT / RF enable (HW §5.1 step 3) */
#define FM1_CLK_CON1_BT  (*(volatile uint32_t *)0x10010u)   /* bits 14-15: BT domain power / reset (HW §5.1) */
#define FM1_RNG_LO       (*(volatile uint32_t *)0x13B00u)   /* random source (HW §1) */
#define FM1_RNG_HI       (*(volatile uint32_t *)0x13B04u)

enum { FM1_IRQ_BLE_RX = 29, FM1_IRQ_BLE_EVENT = 45 };       /* HW §10 */

/* Values the fact sheet does not settle, named so nobody mistakes them for measurements. */
#define FM1_BLE_STEP_DELAY_US 100u      /* HW §5.1 step 3: "a 240-unit delay" and "delays between steps", unit and
                                         * length unknown [M:s]; 100 us is a guess, generous for a power switch */
#define FM1_BLE_T34_VALUE 0x0A01u       /* HW §5.5 step 3: stock V15 0x0A01, demo_ble 0x0901; [15:8] unknown (U5) */

FM1_INLINE void fm1_ble_sync(void) { __asm__ volatile("csync" ::: "memory"); }

/* the column port (HW §2.1 0x2801C/20, §2.3): data first, csync, then the command */
FM1_INLINE void fm1_ble_col_wr(uint32_t link, uint32_t col, uint32_t data)
{
    FM1_BLE_COLDATA = data & 0xFFFFu;
    fm1_ble_sync();
    FM1_BLE_COLCMD = col << 10 | link << 4 | 5u;
}
FM1_INLINE uint32_t fm1_ble_col_rd(uint32_t link, uint32_t col)   /* HW §2.1 0x28024: op 2 */
{
    FM1_BLE_COLCMD = col << 10 | link << 4 | 2u;
    fm1_ble_sync();
    return FM1_BLE_COLRES & 0xFFFFu;
}

/* the 24-bit running slot count of link n (HW §2.3: column 0 low 16 bits, column 14 [7:0] bits 23:16) */
static uint32_t fm1_ble_clock(uint32_t link)
{
    uint32_t hi = fm1_ble_col_rd(link, 14) & 0xFFu, lo = fm1_ble_col_rd(link, 0), hi2 = fm1_ble_col_rd(link, 14) & 0xFFu;
    if (hi2 != hi)                          /* the low half wrapped between the reads */
        lo = fm1_ble_col_rd(link, 0);
    return hi2 << 16 | lo;
}

/* stop link n: column 14 = 0 (HW §2.3), its interrupts off (HW §5.5 end), then wait until the engine is idle (HW §2.1
 * 0x28038 bit1 [M:s]) for at most max_us, and acknowledge what was raised meanwhile (the window that was open when the
 * link stopped ends with its event interrupt: none is left pending for the next link) -> the microseconds it waited
 * (>= max_us: still busy when the wait gave up; console 'blell' busy_*, stop_*). The FM-1 (blell-dev3 / dev4,
 * 2026-10-09): bit1 still set 2,000 polls (~0.75 ms) after a scanning link stopped, every time.
 * The wait is bounded twice: by TIMER4 (max_us), and by a count of reads that no CPU clock gets through in max_us
 * (FM1_BLE_STOP_POLLS_PER_US: one read of 0x28038 and of TIMER4 per pass, each a bus access), so a TIMER4 that does
 * not count (stopped, or its source gated) cannot hold the caller: boot, the main loop or a BLE interrupt. */
#define FM1_BLE_STOP_POLLS_PER_US 64u
static uint32_t fm1_ble_link_stop(uint32_t link, uint32_t max_us)
{
    uint32_t t0, d = 0, span = max_us * FM1_TICKS_PER_US, polls = max_us * FM1_BLE_STOP_POLLS_PER_US + 1u;
    fm1_ble_col_wr(link, 14, 0);
    FM1_BLE_IEN &= ~(0x101u << link);                       /* HW §5.5: enables cleared when a link is opened */
    FM1_BLE_G2EN &= ~(0x101u << link);
    FM1_BLE_IACK = 0x101u << link;                         /* HW §2.1: write 1 to acknowledge */
    t0 = fm1_ticks();
    while ((FM1_BLE_STAT & 2u) && (d = fm1_ticks() - t0) < span && --polls)
        ;
    if (!polls)
        d = span;                                          /* (the reads ran out first: counted as a timeout) */
    FM1_BLE_IACK = 0x101u << link;                         /* (raised while the engine finished) */
    return d / FM1_TICKS_PER_US;
}

/* link n's interrupts on, in stock's order (HW §6 step 11 [M:t]) */
static void fm1_ble_link_irqs_on(uint32_t link)
{
    FM1_BLE_IACK = 0x001u << link;
    FM1_BLE_IACK = 0x101u << link;
    FM1_BLE_G2EN = 0x100u << link;
    FM1_BLE_IEN = FM1_BLE_IEN | 0x001u << link;
    FM1_BLE_IEN = FM1_BLE_IEN | 0x101u << link;
    FM1_BLE_G2EN = 0x101u << link;
}

/* acknowledge and test the pending bits (HW §8: serviced when enable AND pending) */
FM1_INLINE int fm1_ble_rx_pending(uint32_t link) { return (FM1_BLE_IEN & FM1_BLE_IPND & (0x100u << link)) != 0; }
FM1_INLINE void fm1_ble_rx_ack(uint32_t link) { FM1_BLE_IACK = 0x100u << link; }      /* HW §8 IRQ 29 step 1 */
FM1_INLINE int fm1_ble_event_pending(uint32_t link) { return (FM1_BLE_IEN & FM1_BLE_IPND & (1u << link)) != 0; }
FM1_INLINE void fm1_ble_event_ack(uint32_t link) { FM1_BLE_IACK = 1u << link; }       /* HW §8 IRQ 45 step 1 */
/* the end of the event ISR (HW §8 IRQ 45 steps 4, 5): the second group and the 0x28038 flag */
static void fm1_ble_event_tail(uint32_t link)
{
    if (FM1_BLE_G2EN & FM1_BLE_G2PND & (1u << link))
        FM1_BLE_G2EN |= 0x100u << link;                     /* acknowledge; its "link timeout" is ours (ble_ll.c) */
    if (FM1_BLE_STAT & 0x80u)
        FM1_BLE_STAT = 0x40u;
}

/* the interrupt and status registers as they read now, for the console (HW §2.1): enables, pending, the second group's
 * enables and pending, 0x28038 */
static void fm1_ble_irq_regs(uint32_t r[5])
{
    r[0] = FM1_BLE_IEN;
    r[1] = FM1_BLE_IPND;
    r[2] = FM1_BLE_G2EN;
    r[3] = FM1_BLE_G2PND;
    r[4] = FM1_BLE_STAT;
}

FM1_INLINE uint32_t fm1_ble_rng32(void) { return FM1_RNG_LO ^ (FM1_RNG_HI * 0x9E3779B9u); }   /* HW §1 */

/* ---- radio bring-up (HW §5.1 - §5.4, §16). Unverified on hardware in every step. */

/* HW §2.4: 81 entries x 3 words, one per 1 MHz channel; stock V15's form {i | i << 8, 0, 0} [M:d], meaning [I] */
static uint32_t fm1_ble_pll_tbl[81 * 3] __attribute__((aligned(4)));

#define FM1_BT_AGC_IDX   (*(volatile uint32_t *)0x2FD98u)   /* HW §2.2: the AGC table's write index (0) */
#define FM1_BT_AGC_DATA  (*(volatile uint32_t *)0x2FD9Cu)   /* HW §2.2: its data port, 128 words */

/* The radio in stock's second-boot order (HW §16.1), with the stored trims (the data of VM 106, 107, 108, 187:
 * src/ble/ble_vm.c found them in the VM or in Optimist's copy; without them the caller never gets here, §15.4):
 *   HW §16.1 groups 2-13   the Wi-Fi front end the BT RF init runs first (HW §5.2), from the captured program
 *                          (hal/fm1_ble_rf.h, build/gen/ble_rf_tables.h), the trim fields byte by byte (§16.4),
 *                          our own VCO scan (group 7);
 *   HW §5.1 steps 3, 4     the BT domain;
 *   HW §5.4 / §16.1 g. 14  the PLL channel table, the AGC table (captured) and configuration, the BT analog words.
 * The clock words of HW §16.1 group 1 (0x10010 bit 10 = our UART's clock, hal/fm1_uart.h; 0x10008 bit 3 = the
 * second core's start, hal/fm1_dual.h) are not the radio's: left as the firmware set them. */
static void fm1_ble_rf_init(const uint8_t *x106, const uint8_t *x107, const uint8_t *x108, const uint8_t *x187)
{
    uint32_t i;
    fm1_ble_rf_run(x106, x107, x108, x187);                /* HW §16.1 groups 2-13 */
    fm1_ble_rf_section(FM1_RF_SECT_BT);                    /* HW §16.1 group 14 */
    /* HW §5.1 step 3: BT domain power / reset, then the BT / RF enable */
    FM1_CLK_CON1_BT &= ~(3u << 14);                        /* bits 14-15 cleared [M:s] */
    fm1_delay_us(FM1_BLE_STEP_DELAY_US);
    FM1_WL_BTEN |= 1u << 7;                                /* -> 0x000C0081 in three steps [M:t] */
    fm1_delay_us(FM1_BLE_STEP_DELAY_US);
    FM1_WL_BTEN = (FM1_WL_BTEN & ~(0x1Fu << 16)) | 0x0Cu << 16;
    fm1_delay_us(FM1_BLE_STEP_DELAY_US);
    FM1_WL_BTEN |= 1u;
    fm1_delay_us(FM1_BLE_STEP_DELAY_US);
    /* HW §5.1 step 4 [M:t] */
    FM1_BT_C40 |= 1u << 10;
    FM1_BT_BRCON = 0xC0000000u;
    FM1_BT_C40 = 0xFFFFu;
    FM1_BT_C40 = 0xFCFDu;
    FM1_BT_C78 = 0x0Fu;
    FM1_BT_C78 = 0x3FFu;
    /* (VM 110, the carrier offset -> PLL_COMP: V15 writes no 110 and a hand-made one changed nothing in the
     * emulator, HW §14.5; U14) */
    /* HW §5.4: the PLL channel table, then the AGC */
    for (i = 0; i < 81u; i++) {
        fm1_ble_pll_tbl[3u * i] = i | i << 8;
        fm1_ble_pll_tbl[3u * i + 1u] = 0;
        fm1_ble_pll_tbl[3u * i + 2u] = 0;
    }
    FM1_BT_PLL_TBL = (uint32_t)(uintptr_t)fm1_ble_pll_tbl;
    FM1_BT_AGC_IDX = 0;                                    /* HW §2.2, §5.4: the AGC table (captured, §17) */
    for (i = 0; i < 128u; i++)
        FM1_BT_AGC_DATA = ble_rf_agc[i];
    FM1_BT_C20 = 0;                                        /* HW §5.4 AGC config [M:t] */
    FM1_BT_AGC0 = 0x000F0000u;
    FM1_BT_AGC(0) = 0x1872BF14u;
    FM1_BT_AGC(1) = 0x1872BF55u;
    FM1_BT_AGC(2) = 0x1872BF00u;
    FM1_BT_AGC(3) = 0;
    FM1_BT_AGC(4) = 0;
    FM1_BT_AGC0 = 0x000F0001u;
    FM1_BT_C7C |= 1u;
    FM1_BT_C48 = 0xB9u;                                    /* HW §2.2 (0xAD after the BR/EDR init, not done here) */
    FM1_BT_C00 = 0x00FFD144u;                              /* HW §2.2, §5.4: 0x2FC00 - 0x2FC28 [M:t] */
    FM1_BT_C04 = 0x4E143CDFu;
    {   /* the BT TX IQ / DC trims: bt_rf_analog_init's base values, with our calibration the compensation from the
         * measured record (fm1_rf_cal.h, RF-CALIBRATION.md §5) */
        uint32_t c08 = 0x03100000u, c10 = 0x80008080u;
        if (fm1_rf_cal_on && fm1_rfc_trimmed)
            fm1_rf_cal_bt_trims(fm1_rfc_x187, &c08, &c10);
        FM1_BT_C08 = c08;
        FM1_BT_C0C = 0x80808080u;
        FM1_BT_C10 = c10;
    }
    FM1_BT_C14 = 0x80u;
    FM1_BT_C18 = 0;
    FM1_BT_C1C = 0;
    FM1_BT_C20 = 0x36555537u;
    FM1_BT_C24 = 0x00034041u;
    FM1_BT_C28 = 0x0005C000u;
    FM1_BT_C98 = 0x02360236u;                              /* HW §2.2: constants [M:s] */
    FM1_BT_C9C = 0x36360008u;
    FM1_BT_CA0 = 0x00003636u;
    /* HW §5.4 then initialises the BR/EDR baseband (0x2FC44, 0x2000C ... 0x20168) and the slot timer. Not done: a
     * BLE-only link layer probably needs neither (HW §10), but whether the engine needs the BT clock running is U12 */
    fm1_ble_rf_section(FM1_RF_SECT_DONE);
}

/* HW §5.5: the BLE baseband, steps 1-4 and 6-7 (step 5, the interrupts, is fm1_ble_irq_attach) */
static void fm1_ble_bb_init(uint32_t base, uint32_t size)
{
    FM1_BT_BLE_EN |= 1u;                                   /* step 1 */
    FM1_BLE_CON = 1u;                                      /* step 2 */
    FM1_BLE_T34 = FM1_BLE_T34_VALUE;                       /* step 3 */
    FM1_BT_BB_BASE = base;                                 /* step 4 (the block is zeroed by the caller) */
    FM1_BT_BB_END = base + size;
    FM1_BLE_CON |= 0x2000u;                                /* step 6 -> 0x6001 */
    FM1_BLE_CON |= 0x4000u;
    FM1_BLE_CON &= ~0x10u;
    FM1_BLE_T08 = (FM1_BLE_T08 & ~0x3FFu) | 70u;           /* step 7 */
    FM1_BLE_T08 |= 0xF000u;
    FM1_BLE_T0C = 70u;
    FM1_BLE_T10 = 62u | 62u << 8;
    FM1_BLE_T14 = 30u;
    FM1_BLE_T18 = 20u | 20u << 8;
    FM1_BLE_IEN = 0;                                       /* HW §5.5 end: enables cleared */
    FM1_BLE_G2EN = 0;
}

/* The interrupt entries (as fm1_isr.S), here so a build without BLE carries none of it. The C bodies are the
 * driver's (src/ble/ble_hw_wl82.c). */
void ble_wl82_event_irq(void);
void ble_wl82_rx_irq(void);
__asm__(".section .text.isr_ble_event,\"ax\",@progbits\n"
        "\t.globl isr_ble_event\n"
        "isr_ble_event:\n"
        "\t[--sp] = {psr, rets, reti}\n"
        "\t[--sp] = {r3-r0}\n"
        "\tcall ble_wl82_event_irq\n"
        "\t{r3-r0} = [sp++]\n"
        "\t{psr, rets, reti} = [sp++]\n"
        "\tcsync\n"
        "\trti\n"
        "\t.previous\n");
__asm__(".section .text.isr_ble_rx,\"ax\",@progbits\n"
        "\t.globl isr_ble_rx\n"
        "isr_ble_rx:\n"
        "\t[--sp] = {psr, rets, reti}\n"
        "\t[--sp] = {r3-r0}\n"
        "\tcall ble_wl82_rx_irq\n"
        "\t{r3-r0} = [sp++]\n"
        "\t{psr, rets, reti} = [sp++]\n"
        "\tcsync\n"
        "\trti\n"
        "\t.previous\n");
extern void isr_ble_event(void);
extern void isr_ble_rx(void);

/* the two BLE interrupts masked (hold 1) or let go (0) in the interrupt controller, their priority kept: the main loop
 * holds them while it changes the link layer's state (a pending one is taken when they are let go) */
static void fm1_ble_irqs_hold(int hold)
{
    static const uint8_t irq[2] = {FM1_IRQ_BLE_EVENT, FM1_IRQ_BLE_RX};
    uint32_t i;
    for (i = 0; i < 2u; i++) {
        uint32_t bit = 1u << ((irq[i] & 7u) * 4u);
        if (hold)
            FM1_ICFG(irq[i]) &= ~bit;
        else
            FM1_ICFG(irq[i]) |= bit;
    }
}

/* HW §5.5 step 5, §10: stock registers both at priority 2 on CPU 0. IRQs off. */
static void fm1_ble_irq_attach(uint32_t prio)
{
    fm1_irq_attach(FM1_IRQ_BLE_EVENT, isr_ble_event, prio);
    fm1_irq_attach(FM1_IRQ_BLE_RX, isr_ble_rx, prio);
}

text.fm1-base/bsp/chip/fm1_ble_rf.h:
/* SPDX-License-Identifier: GPL-3.0-only OR MPL-2.0 */
/* FM-1 (AC791N / WL82) radio start-up, the part before the BT block: the shared Wi-Fi front end that the BT RF
 * init runs first (docs/BLE-HW-FACTS.md §5.2, §16; branch feat/ble-facts d907ce3, "HW §n" below). Included by
 * hal/fm1_ble.h in a BLE build with the real driver.
 *
 * The long constant parts (§16.1 groups 2-6, 8-13: about 34,000 register words on a second boot) are a small program
 * in ble_rf_tables_v15.h, captured by tools/ble_rf_capture.py from the stock V15 firmware in the emulator and committed
 * (tools/build.py puts it, or a fresh capture, at build/gen/ble_rf_tables.h). This file runs it, in boot-2 order:
 *
 *   register write           §16.1 groups 2, 3, 5, 6, 8, 9, 12 (0x11900-0x11964, 0x14040-0x1405C, the MAC window);
 *                            bit 14 of 0x11900 kept as found (§16.2: a periodic routine's bit, not a trim)
 *   BBP window write / read  §16.3: entry address, data, commit 1 / address, commit 2, the read-back register;
 *                            direct BBP registers; the port 0x3101C (§5.2: bit 17 start, bit 16 read)
 *   RF-die LUT words         §5.2 SPI port 0x14028 / 0x1402C, the five-high five-low kick (§16.1 group 11)
 *   trim field               §14.5, §16.4: the next write takes a field from VM 106 / 107 / 108 / 187 (the bytes
 *                            given to fm1_ble_rf_run); a read-modify-write field goes into the last read-back
 *   delay                    the gaps of 20 us or more in stock's trace
 *   VCO scan                 §16.1 group 7: our own search (fm1_ble_vco_scan below), not stock's
 *   replay                   §16.1 group 10: the BBP reload, the same as the first load (group 4)
 *   skipped                  §16.2: the window-D read-back loop (DC / IQ [I]), TODO(hardware)
 *   section marker           where a §16.1 group starts (found by register pattern: ble_rf_capture.py sections()):
 *                            2 analog word, 3 radio config, 4 BBP first load, 5 crystal trim (VM 106), 6 analog init,
 *                            7 VCO scan, 8 post-scan set-up, 10 BBP second phase, 11 RF-die LUT, 13 VM 108; then
 *                            fm1_ble_rf_init marks 14 (the BT block, hal/fm1_ble.h) and 15 (done). The console's
 *                            'bletrim' prints the last one entered and the set: on a unit where the start-up stops,
 *                            the group it stopped in
 *
 * TODO(hardware), the unknowns in HW §12 and §16.2:
 *   - the window-D read-back loop (§16.2, 3,537 transactions in stock's boot 2): left out; its results depend on
 *     read-backs the emulator returns as 0 (U17). §18.3 step 3, the read-back build: write a window entry and read
 *     it back through 0xD3 (a read-back console command still to write, HW §18), then decide how to measure and
 *     write those entries;
 *   - the RF-die LUT words a stored trim changes (VM 107 -> entries 0xE0-0xFF of both words, VM 187 bytes 48-63, the
 *     scan -> word-1 entries 0x00-0x7F): written as captured (the emulator's calibration), their mapping unknown.
 *     §16.5 row 1: after the scan, read the LUT back (SPI command 0x6);
 *   - the VCO band and the final 0x11934-0x11940: the scan below finds an in-range band, but stock's final writes
 *     (constants of the capture) are kept; compare with the emulator's on hardware (§18.3 step 3);
 *   - the BT TX trims (0x2FC08, 0x2FC10: §16.2, live from BBP read-backs): hal/fm1_ble.h keeps stock's first values;
 *   - delays: stock's gaps in the emulator, not a datasheet's settle times. */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"
#include "fm1_irq.h"
#include "fm1_time.h"
#include "ble_rf_tables.h"   /* build/gen: tools/build.py copies firmware/hal/ble_rf_tables_v15.h or a fresh capture there */

#if !defined(BLE_RF_TABLES_FORMAT) || BLE_RF_TABLES_FORMAT != 3
#error "build/gen/ble_rf_tables.h is from another tools/ble_rf_capture.py: capture it again or update ble_rf_tables_v15.h"
#endif

#define FM1_RF_REG(a)     (*(volatile uint32_t *)(uintptr_t)(a))
#define FM1_BBP_PORT      (*(volatile uint32_t *)0x3101Cu)   /* HW §5.2: bit17 start, bit16 read, [15:8] reg, [7:0] data */
#define FM1_RFSPI_CTL     (*(volatile uint32_t *)0x14028u)   /* HW §5.2: [22:20] busy, 0x10000 | address << 8 | command */
#define FM1_RFSPI_DATA    (*(volatile uint32_t *)0x1402Cu)
#define FM1_RFSPI_WAIT    (*(volatile uint32_t *)0x14034u)   /* written 0 while waiting (HW §5.2) */
#define FM1_WL_A00        0x11900u                          /* HW §16.2: bit 14 kept */
#define FM1_WL_VCO_EN     (*(volatile uint32_t *)0x11934u)   /* HW §16.1 group 7: bit 24 pulsed per step */
#define FM1_WL_VCO_BAND   (*(volatile uint32_t *)0x11938u)   /* [25:19] the band; bits 16, 18 pulsed per step */
#define FM1_WL_VCO_FINE   (*(volatile uint32_t *)0x1193Cu)
#define FM1_WL_CAL_START  (*(volatile uint32_t *)0x11968u)   /* bit 28: start a comparator measurement */
#define FM1_WL_CAL_STROBE (*(volatile uint32_t *)0x11978u)   /* strobe 1 x 8 then 0; read: bit 17 low, bit 18 high */

/* values the sheet does not settle, named so nobody mistakes them for measurements */
#define FM1_BBP_POLLS 1000u               /* the BBP start bit polled to 0 (stock reads it once; the bound is ours) */
#define FM1_RFSPI_POLLS 1000u             /* HW §5.2 busy [22:20]; the bound is ours */
#define FM1_VCO_BANDS 64u                 /* stock's scan used bands 0..63 (§16.1 group 7, 0x11938 [25:19]) */
#define FM1_VCO_EDGE_US 2u                /* between the step's pulse edges (stock: ~2 us in the emulator) [I] */
#define FM1_VCO_SETTLE_US 50u             /* before a measurement (stock: ~45 us in the emulator) [I] */

/* §16.1 groups run as one burst: decoded first (trim fields applied), then written by fm1_rf_burst_run from RAM
 * with the interrupts off, so nothing reads flash between the group's first and last write. Group 5, the 0x11930
 * ramp (1, 3, 7, 0xF, 0x1F, 0x5F, 0x25F, then the VM 106 trims): on hardware, rf_init hung in group 5 in exactly the
 * builds where a flash data-cache line of ble_rf_prog began right after the write of 3 (ble_rf_prog at 8 mod 32:
 * 1f0ab85, 3a153c3), and ran in the builds where the first line began after 0x5F (24 mod 32: 1cc6e04, 510e616), the
 * code identical. [I] the ramp's first steps leave the flash path (XIP) unusable until it is complete, so a flash
 * access there never returns and the watchdog resets. A group that holds anything but register writes and trim
 * fields, or more than FM1_RF_BURST_MAX writes, runs op by op as before (rf_burst 0 in 'bletrim'). */
#define FM1_RF_BURST_GROUPS (1u << 5)
#define FM1_RF_BURST_MAX 32u              /* group 5 has 16 writes (§16.1: 14 + 2) */

struct fm1_ble_rf_stat {                  /* what the start-up did, for the console (io/console.c 'bletrim') */
    uint32_t ops, bbp_timeouts, spi_timeouts, lut_words, trims, skipped, delay_us;
    uint32_t sections;                    /* bit g: §16.1 group g entered (section markers) */
    uint32_t scan_result;                 /* the last comparator word */
    uint32_t group_op;                    /* ops when the last group was entered */
    uint8_t ran, scan_found, scan_band, scan_steps, bad_op;
    uint8_t burst;                        /* writes of the last burst group (FM1_RF_BURST_GROUPS); 0: none ran */
    volatile uint8_t section;             /* the last group entered (0: not started) */
};
#define FM1_RF_SECT_BT   14u              /* the BT block (hal/fm1_ble.h fm1_ble_rf_init, HW §16.1 group 14) */
#define FM1_RF_SECT_DONE 15u

/* The BLE breadcrumb: kept in .noinit, so it survives a watchdog reset (not a power cycle). main.c moves it to
 * prev / prev_irqs at boot (fm1_ble_crumb_boot) and the console's 'dbg' prints both. now: bits [31:24] 0xB1 (the word
 * is valid), [23:16] the step of the BLUETOOTH ON path (FM1_BLE_STEP_*), [15:8] rf_ops / 256 at the last rf_init
 * group, [7:0] that group (§16.1). irqs: the BLE interrupts taken since that ON (a storm shows as a huge count).
 * op: rf_init's op count (rf_ops) when the last op began; gop: that op's index within its group (the group's marker
 * is 0; in a burst group, FM1_RF_BURST_GROUPS: op is the group's first op, gop the write, 1..rf_burst); addr: the last access begun, so a hang names it: a register's address, 0xBB0000 | BBP register << 8 | data
 * for a BBP transaction (port 0x3101C), 0x5B0000 | command << 8 | address for an RF-die SPI command (port 0x14028).
 * stop: the last link stop (hal/fm1_ble.h fm1_ble_link_stop through ble_hw_wl82.c hw_stop): 0x5D000000 | path << 16
 * (BDS_*) while it waits for the engine, 0x5E000000 | path << 16 | the microseconds it waited (at most 0xFFFF) once
 * done: a hang in that wait names it.
 * (New words go last: a reflash moves none of the older ones.) */
enum {
    FM1_BLE_STEP_NONE, FM1_BLE_STEP_SET_ON, FM1_BLE_STEP_STACK_INIT, FM1_BLE_STEP_RF_INIT, FM1_BLE_STEP_BB_INIT,
    FM1_BLE_STEP_STARTED, FM1_BLE_STEP_ENABLE, FM1_BLE_STEP_LINK_STOP, FM1_BLE_STEP_LINK_OPEN, FM1_BLE_STEP_ADV_PROG,
    FM1_BLE_STEP_ADV_STARTED, FM1_BLE_STEP_IRQS_ON, FM1_BLE_STEP_RUNNING, FM1_BLE_STEP_SET_OFF
};
static volatile struct {
    uint32_t now, irqs, prev, prev_irqs;
    uint32_t op, gop, addr, prev_op, prev_gop, prev_addr;
    uint32_t stop, prev_stop;
} fm1_ble_bc __attribute__((section(".noinit.ble")));
#if defined(FELUCCA_DUAL) && FELUCCA_DUAL
/* hal/fm1_dual.h fm1_dual_snap: where the BLE start-up / link was when an exception came (2026-10-15: CPU1 faults only
 * in BLE builds) */
#define FM1_DUAL_SNAP_BLE 1
static void fm1_dual_snap_ble(fm1_c1_snap_t *s)
{
    s->ble[0] = fm1_ble_bc.now;
    s->ble[1] = fm1_ble_bc.irqs;
    s->ble[2] = fm1_ble_bc.op;
    s->ble[3] = fm1_ble_bc.gop;
    s->ble[4] = fm1_ble_bc.addr;
}
#endif
#define fm1_ble_crumb fm1_ble_bc.now
#define fm1_ble_crumb_irqs fm1_ble_bc.irqs
static uint32_t fm1_ble_step_at[16];         /* TIMER4 / 24000 (ms) when each step was first reached (0: not yet; the
                                              * console's boot: against CPU1's start, 2026-10-15) */
FM1_INLINE void fm1_ble_step(uint32_t step)
{
    fm1_ble_crumb = 0xB1000000u | (step & 0xFFu) << 16 | (fm1_ble_crumb & 0xFFFFu);
    if (!fm1_ble_step_at[step & 15u])
        fm1_ble_step_at[step & 15u] = 1u + fm1_ticks() / (1000u * FM1_TICKS_PER_US);
}
static void fm1_ble_crumb_boot(void)       /* at boot (main.c): what the last run left, then from zero */
{
    fm1_ble_bc.prev = fm1_ble_bc.now >> 24 == 0xB1u ? fm1_ble_bc.now : 0u;   /* (a power cycle: RAM noise -> 0) */
    fm1_ble_bc.prev_irqs = fm1_ble_bc.prev ? fm1_ble_bc.irqs : 0u;
    fm1_ble_bc.prev_op = fm1_ble_bc.prev ? fm1_ble_bc.op : 0u;
    fm1_ble_bc.prev_gop = fm1_ble_bc.prev ? fm1_ble_bc.gop : 0u;
    fm1_ble_bc.prev_addr = fm1_ble_bc.prev ? fm1_ble_bc.addr : 0u;
    fm1_ble_bc.prev_stop = fm1_ble_bc.prev ? fm1_ble_bc.stop : 0u;
    fm1_ble_bc.now = fm1_ble_bc.irqs = 0;
    fm1_ble_bc.op = fm1_ble_bc.gop = fm1_ble_bc.addr = fm1_ble_bc.stop = 0;
}

static struct fm1_ble_rf_stat fm1_ble_rf_stat;
static void fm1_ble_rf_section(uint32_t g)
{
    fm1_ble_rf_stat.section = (uint8_t)g;
    fm1_ble_rf_stat.group_op = fm1_ble_rf_stat.ops;
    fm1_ble_crumb = (fm1_ble_crumb & 0xFFFF0000u) | (fm1_ble_rf_stat.ops >> 8 & 0xFFu) << 8 | (g & 0xFFu);
    fm1_ble_rf_stat.sections |= 1u << (g & 31u);
}

static uint32_t fm1_bbp(uint32_t reg, uint32_t data, uint32_t rd)   /* one BBP transaction -> the port's [7:0] */
{
    uint32_t c = BLE_RF_BBP_FLAGS | rd << 16 | reg << 8 | data, i;
    fm1_ble_bc.addr = 0xBB0000u | (reg & 0xFFu) << 8 | (data & 0xFFu);
    FM1_BBP_PORT = c;
    FM1_BBP_PORT = c | 1u << 17;                            /* HW §5.2: the command, then with the start bit */
    for (i = 0; i < FM1_BBP_POLLS && (FM1_BBP_PORT & 1u << 17); i++)
        ;
    if (i == FM1_BBP_POLLS)
        fm1_ble_rf_stat.bbp_timeouts++;
    return FM1_BBP_PORT & 0xFFu;
}

/* the BBP windows (HW §16.3): window w's commit, address, data, read-back = 0xC8 + 4w .. 0xCB + 4w */
static void fm1_bbp_win_wr(uint32_t w, uint32_t entry, uint32_t v)
{
    fm1_bbp(0xC9u + 4u * w, entry, 0);
    fm1_bbp(0xCAu + 4u * w, v & 0xFFu, 0);
    fm1_bbp(0xC8u + 4u * w, 1, 0);
}
static uint32_t fm1_bbp_win_rd(uint32_t w, uint32_t entry)   /* [I] that it returns the entry: U17 */
{
    fm1_bbp(0xC9u + 4u * w, entry, 0);
    fm1_bbp(0xC8u + 4u * w, 2, 0);
    return fm1_bbp(0xCBu + 4u * w, 0, 1);
}

static void fm1_rfspi(uint32_t addr, uint32_t cmd, uint32_t data)   /* HW §5.2: one RF-die SPI command */
{
    uint32_t i;
    fm1_ble_bc.addr = 0x5B0000u | (cmd & 0xFu) << 8 | (addr & 0xFFu);
    for (i = 0; i < FM1_RFSPI_POLLS && (FM1_RFSPI_CTL >> 20 & 7u); i++)
        FM1_RFSPI_WAIT = 0;
    if (i == FM1_RFSPI_POLLS)
        fm1_ble_rf_stat.spi_timeouts++;
    FM1_RFSPI_DATA = data;
    FM1_RFSPI_CTL = 0x10000u | (addr & 0xFFu) << 8 | (cmd & 0xFu);
    for (i = 0; i < 5u; i++)                                /* the kick: bit 4 five times high, five times low */
        FM1_RFSPI_CTL |= 0x10u;
    for (i = 0; i < 5u; i++)
        FM1_RFSPI_CTL &= ~0x10u;
}

/* Our own calibration (fm1_rf_cal.h, JieLi's, Apache-2.0): with fm1_rf_cal_on set before fm1_ble_rf_run, the replay
 * measures this unit's radio instead of taking a stored record 187: the stock VCO scan at group 7's scan op, the trim
 * before the first write that carries a 187 field (after group 8's PLL set-up), then every 187 field, the RF-die
 * table's banks (word 1, entries 0-127) and RX DC (word 0, 128-223) from what it measured. The x187 given to
 * fm1_ble_rf_run is ignored then. docs/bt/RF-CALIBRATION.md. */
#include "fm1_rf_cal.h"
static uint8_t fm1_rf_cal_on;                               /* set by the firmware: measure (1), or the stored 187 (0) */
static struct fm1_rf_cal fm1_rfc;                           /* what was measured (the log reads it) */
static uint8_t fm1_rfc_x187[68];                            /* the record built from it */
static uint8_t fm1_rfc_scanned, fm1_rfc_trimmed;
static int fm1_rfc_scan_rc, fm1_rfc_trim_rc;

/* the rest of the replay with measured values: a 187 field's write gets the record's true fields (the captured ones
 * are 1-2-bit slices found by perturbation) */
static int fm1_rfc_is187(const uint8_t *trim, uint32_t nt)
{
    uint32_t i;
    for (i = 0; i < nt; i++)
        if ((ble_rf_fields[4u * trim[i]] & 3u) == 3u)
            return 1;
    return 0;
}
static void fm1_rfc_before_187(void)                        /* the first 187 field: measure now */
{
    if (fm1_rf_cal_on && !fm1_rfc_trimmed) {
        fm1_rfc_trimmed = 1;
        fm1_rfc_trim_rc = fm1_rf_cal_trim(&fm1_rfc, fm1_rfc_x187);
    }
}
static uint32_t fm1_rfc_lut(uint32_t entry, uint32_t cmd, uint32_t w)   /* an RF-die word, patched */
{
    if (!fm1_rf_cal_on)
        return w;
    if (cmd == 0xDu && entry < 128u && fm1_rfc_scanned)
        return fm1_rf_cal_rfd_w1(&fm1_rfc, entry, w);
    if (cmd == 0xEu && entry >= 128u && entry < 224u && fm1_rfc_trimmed)
        return fm1_rf_cal_rfd_w0(entry, w, fm1_rfc_x187);
    return w;
}

/* §16.1 group 7, our own search (not stock's): with the fine code stock starts from, find a band whose comparator
 * reads neither low (bit 17) nor high (bit 18): bisection over FM1_VCO_BANDS, a higher band when low. The step:
 * the band into 0x11938 [25:19], 0x11938 bits 16 / 18 and 0x11934 bit 24 pulsed low then high, 0x11968 bit 28,
 * eight strobes of 0x11978 then 0, the comparator in 0x11978 (the registers and the order as stock's boot-2 trace
 * shows them: BLE-STACK.md §8.1). Its result is reported only: stock's final band and fine code follow as constants
 * (TODO(hardware) above). */
static void fm1_ble_vco_scan(uint32_t fine0)
{
    uint32_t lo = 0, hi = FM1_VCO_BANDS - 1u, b, r, i;
    FM1_WL_VCO_FINE = fine0;
    fm1_ble_rf_stat.scan_found = 0;
    fm1_ble_rf_stat.scan_steps = 0;
    while (lo <= hi) {
        b = (lo + hi) / 2u;
        FM1_WL_VCO_BAND = (FM1_WL_VCO_BAND & ~(0x7Fu << 19)) | b << 19;
        FM1_WL_VCO_BAND &= ~(1u << 16);
        FM1_WL_VCO_BAND &= ~(1u << 18);
        FM1_WL_VCO_EN &= ~(1u << 24);
        fm1_delay_us(FM1_VCO_EDGE_US);
        FM1_WL_VCO_BAND |= 1u << 16;
        fm1_delay_us(FM1_VCO_EDGE_US);
        FM1_WL_VCO_EN |= 1u << 24;
        FM1_WL_VCO_BAND |= 1u << 18;
        fm1_delay_us(FM1_VCO_SETTLE_US);
        FM1_WL_CAL_START |= 1u << 28;
        for (i = 0; i < 8u; i++)
            FM1_WL_CAL_STROBE = 1;
        FM1_WL_CAL_STROBE = 0;
        r = FM1_WL_CAL_STROBE;
        fm1_ble_rf_stat.scan_steps++;
        fm1_ble_rf_stat.scan_result = r;
        fm1_ble_rf_stat.scan_band = (uint8_t)b;
        if (r & 1u << 17)
            lo = b + 1u;                                    /* low: a higher band */
        else if (r & 1u << 18) {
            if (!b)
                break;
            hi = b - 1u;                                    /* high: a lower band */
        } else {
            fm1_ble_rf_stat.scan_found = 1;
            break;
        }
    }
}

static uint32_t fm1_rf_field(uint32_t v, uint32_t f, const uint8_t *const rec[4])   /* §14.5 / §16.4 */
{
    const uint8_t *d = &ble_rf_fields[4u * f];
    uint32_t x = rec[d[0] & 3u][d[1]], s = d[2], w = d[3] & 0x7Fu, m;
    if (d[3] & 0x80u)                                       /* VM 108: a non-zero byte replaces the default */
        return x ? x : v;
    m = ((1u << w) - 1u) << s;
    return (v & ~m) | (x << s & m);
}

static uint32_t fm1_rf_u32(const uint8_t *p) { return p[0] | p[1] << 8 | (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24; }

/* the burst's writes, from RAM: no flash fetch, no flash data (a and v are on the caller's stack, fm1_ble_bc is RAM)
 * between the first write and the last. tools/build.py checks it links into .ram_text. */
__attribute__((section(".ram_text"), noinline, used))
static void fm1_rf_burst_run(const uint32_t *a, const uint32_t *v, uint32_t n)
{
    uint32_t i;
    for (i = 0; i < n; i++) {
        fm1_ble_bc.gop = i + 1u;
        fm1_ble_bc.addr = a[i];
        FM1_RF_REG(a[i]) = v[i];
    }
}

/* a group of FM1_RF_BURST_GROUPS, from its first op at pc: decode its register writes and trim fields up to the next
 * section marker, then write them in one burst with the interrupts off (icfg bit 9 is the global enable that
 * cli / sti clear and set: the emulator's model [I]). -> the pc after the group, or pc itself when the group holds
 * anything else (the caller then runs it op by op) */
static uint32_t fm1_ble_rf_burst(uint32_t pc, uint32_t end, const uint8_t *const rec[4])
{
    const uint8_t *p = ble_rf_prog;
    uint32_t a[FM1_RF_BURST_MAX], v[FM1_RF_BURST_MAX], n = 0, ops = 0, trims = 0, q = pc, i, ie;
    void (*volatile run)(const uint32_t *, const uint32_t *, uint32_t) = fm1_rf_burst_run;   /* (XIP -> RAM: a
                                                         * direct call does not reach, hal/fm1_clock.h fm1_clk_far) */
    uint8_t trim[8], nt = 0;
    while (q < end && p[q] != 0x90u) {
        if (p[q] < 0x80u) {
            if (n == FM1_RF_BURST_MAX || q + 5u > end || ble_rf_addr[p[q]] == FM1_WL_A00)
                return pc;                                  /* (0x11900 needs a read: not in a burst) */
            a[n] = ble_rf_addr[p[q]];
            v[n] = fm1_rf_u32(p + q + 1);
            for (i = 0; i < nt; i++)
                v[n] = fm1_rf_field(v[n], trim[i], rec);
            n++;
            nt = 0;
            q += 5;
        } else if (p[q] == 0x8Bu && q + 3u <= end && nt < sizeof trim && p[q + 1] < BLE_RF_NFIELDS) {
            trim[nt++] = p[q + 1];                          /* (a read-back field: only window writes use it) */
            trims++;
            q += 3;
        } else
            return pc;
        ops++;
    }
    if (nt)
        return pc;                                          /* a trim field for an op outside the group */
    fm1_ble_bc.op = fm1_ble_rf_stat.ops + 1u;
    ie = fm1_icfg() & 0x200u;
    fm1_irq_off();
    run(a, v, n);
    if (ie)
        fm1_irq_on();
    fm1_ble_rf_stat.ops += ops;
    fm1_ble_rf_stat.trims += trims;
    fm1_ble_rf_stat.burst = (uint8_t)n;
    return q;
}

/* one op more for the console and the breadcrumb (each write of a packed op counts as the op it replaced) */
static void fm1_ble_rf_tick(void)
{
    fm1_ble_rf_stat.ops++;
    fm1_ble_bc.op = fm1_ble_rf_stat.ops;
    fm1_ble_bc.gop = fm1_ble_rf_stat.ops - fm1_ble_rf_stat.group_op;
}

/* the packed ops (capture format 3, tools/ble_rf_pack.py), write for write the format-2 ops they replace:
 * OP_LUT2 0x91: cmd A, cmd B, first entry, count - 1, nA, nB, the deltas (4 bytes each), then count pairs of delta
 * indices (A's word, then B's, for each entry; a word is its command's last + the delta, from 0) -> the bytes used */
static uint32_t fm1_ble_rf_lut2(const uint8_t *p)
{
    uint32_t n = p[4] + 1u, na = p[5], wa = 0, wb = 0, i;
    const uint8_t *da = p + 7, *db = da + 4u * na, *ix = db + 4u * p[6];
    for (i = 0; i < n; i++) {
        if (i)
            fm1_ble_rf_tick();
        wa += fm1_rf_u32(da + 4u * ix[2u * i]);
        fm1_rfspi(p[3] + i, p[1], fm1_rfc_lut(p[3] + i, p[1], wa));
        fm1_ble_rf_tick();
        wb += fm1_rf_u32(db + 4u * ix[2u * i + 1u]);
        fm1_rfspi(p[3] + i, p[2], fm1_rfc_lut(p[3] + i, p[2], wb));
    }
    fm1_ble_rf_stat.lut_words += 2u * n;
    return (uint32_t)(ix + 2u * n - p);
}

/* OP_WWG 0x92: window, n, n entries, records r, then r x n values: the window writes of the n entries, r times */
static uint32_t fm1_ble_rf_wwg(const uint8_t *p)
{
    uint32_t n = p[2], r = p[3u + n], k, j;
    const uint8_t *v = p + 4u + n;
    for (k = 0; k < r; k++)
        for (j = 0; j < n; j++) {
            if (k | j)
                fm1_ble_rf_tick();
            fm1_bbp_win_wr(p[1] & 3u, p[3u + j], *v++);
        }
    return (uint32_t)(v - p);
}

/* run ble_rf_prog[pc, end) (one level of replay); rec = the data of VM 106, 107, 108, 187 */
static void fm1_ble_rf_exec(uint32_t pc, uint32_t end, const uint8_t *const rec[4], int depth)
{
    const uint8_t *p = ble_rf_prog;
    uint8_t trim[8], rmw = 0, nt = 0;
    uint32_t last = 0, v, a, i, n;
    while (pc < end) {
        uint32_t op = p[pc];
        fm1_ble_rf_tick();
        if (op < 0x80u) {                                   /* a register write */
            a = ble_rf_addr[op];
            v = fm1_rf_u32(p + pc + 1);
            fm1_ble_bc.addr = a;
            if (a == FM1_WL_A00)
                v = (v & ~(1u << 14)) | (FM1_RF_REG(a) & 1u << 14);
            if (fm1_rf_cal_on && fm1_rfc_is187(trim, nt)) {
                fm1_rfc_before_187();
                for (i = 0; i < nt; i++)
                    if ((ble_rf_fields[4u * trim[i]] & 3u) != 3u)
                        v = fm1_rf_field(v, trim[i], rec);
                v = fm1_rf_cal_reg(a, v, fm1_rfc_x187);
            } else
                for (i = 0; i < nt; i++)
                    v = fm1_rf_field(v, trim[i], rec);
            if (fm1_rf_cal_on && fm1_rfc_scanned && a == (uint32_t)(uintptr_t)&FM1_WL_VCO_BAND)
                v = (v & ~(0x7Fu << 19)) | (uint32_t)fm1_rfc.bank121 << 19;   /* our scan's bank, not the capture's */
            FM1_RF_REG(a) = v;
            nt = rmw = 0;
            pc += 5;
        } else if ((op & 0xFCu) == 0x80u) {                 /* a window write */
            v = rmw ? last : p[pc + 2];
            if (fm1_rf_cal_on && fm1_rfc_is187(trim, nt)) {
                fm1_rfc_before_187();
                for (i = 0; i < nt; i++)
                    if ((ble_rf_fields[4u * trim[i]] & 3u) != 3u)
                        v = fm1_rf_field(v, trim[i], rec);
                v = fm1_rf_cal_win(op & 3u, p[pc + 1], v, fm1_rfc_x187);
            } else
                for (i = 0; i < nt; i++)
                    v = fm1_rf_field(v, trim[i], rec);
            fm1_bbp_win_wr(op & 3u, p[pc + 1], v);
            nt = rmw = 0;
            pc += 3;
        } else if ((op & 0xFCu) == 0x84u) {                 /* a window read */
            last = fm1_bbp_win_rd(op & 3u, p[pc + 1]);
            pc += 2;
        } else if (op == 0x88u) {
            fm1_bbp(p[pc + 1], p[pc + 2], 0);
            pc += 3;
        } else if (op == 0x89u) {
            last = fm1_bbp(p[pc + 1], 0, 1);
            pc += 2;
        } else if (op == 0x8Au) {                           /* LUT words: command, first entry, count, words */
            n = p[pc + 3];
            for (i = 0; i < n; i++)
                fm1_rfspi(p[pc + 2] + i, p[pc + 1], fm1_rfc_lut(p[pc + 2] + i, p[pc + 1], fm1_rf_u32(p + pc + 4 + 4u * i)));
            fm1_ble_rf_stat.lut_words += n;
            pc += 4u + 4u * n;
        } else if (op == 0x8Bu) {                           /* a trim field for the next write */
            if (nt < sizeof trim && p[pc + 1] < BLE_RF_NFIELDS)
                trim[nt++] = p[pc + 1];
            else
                fm1_ble_rf_stat.bad_op = (uint8_t)op;
            rmw |= p[pc + 2] & 1u;
            fm1_ble_rf_stat.trims++;
            pc += 3;
        } else if (op == 0x8Cu) {
            n = p[pc + 1] | p[pc + 2] << 8;
            fm1_delay_us(n);
            fm1_ble_rf_stat.delay_us += n;
            pc += 3;
        } else if (op == 0x8Du) {
            if (fm1_rf_cal_on) {                            /* the stock scan (fm1_rf_cal.h) */
                fm1_rfc_scan_rc = fm1_rf_cal_scan(&fm1_rfc);
                fm1_rfc_scanned = 1;
            } else
                fm1_ble_vco_scan(fm1_rf_u32(p + pc + 1));
            pc += 5;
        } else if (op == 0x8Eu) {
            a = p[pc + 1] | p[pc + 2] << 8;
            n = p[pc + 3] | p[pc + 4] << 8;
            if (!depth && a + n <= sizeof ble_rf_prog)
                fm1_ble_rf_exec(a, a + n, rec, 1);
            else
                fm1_ble_rf_stat.bad_op = (uint8_t)op;
            pc += 5;
        } else if (op == 0x8Fu) {
            fm1_ble_rf_stat.skipped += p[pc + 1] | p[pc + 2] << 8;   /* TODO(hardware): the read-back loop */
            pc += 3;
        } else if (op == 0x91u) {                           /* the LUT words of two commands (packed) */
            pc += fm1_ble_rf_lut2(p + pc);
        } else if (op == 0x92u) {                           /* window writes repeating n entries (packed) */
            pc += fm1_ble_rf_wwg(p + pc);
            nt = rmw = 0;
        } else if (op == 0x90u) {                           /* a section marker (§16.1 group) */
            fm1_ble_rf_section(p[pc + 1]);
            pc += 2;
            if (p[pc - 1] < 32u && (FM1_RF_BURST_GROUPS >> p[pc - 1] & 1u))
                pc = fm1_ble_rf_burst(pc, end, rec);        /* (unchanged: run op by op below) */
        } else {                                            /* 0xFF: the end (anything else: stop there) */
            if (op != 0xFFu)
                fm1_ble_rf_stat.bad_op = (uint8_t)op;
            return;
        }
    }
}

/* HW §16.1 groups 2-13 with the stored trims (the data of VM 106, 107, 108, 187, in that order) */
static void fm1_ble_rf_run(const uint8_t *x106, const uint8_t *x107, const uint8_t *x108, const uint8_t *x187)
{
    const uint8_t *const rec[4] = {x106, x107, x108, x187};
    fm1_ble_rf_exec(0, sizeof ble_rf_prog, rec, 0);
    if (fm1_rf_cal_on && fm1_rfc_trimmed)
        fm1_rfc_cal_att(0);                                 /* the attenuators as JieLi's trim leaves them (its last
                                                             * rx_tx_cal_attenuation(0)); the replay's words are a
                                                             * start without a trim (measured against the SDK build) */
    fm1_ble_rf_stat.ran = 1;
}

