/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Henri David: from Optimist (github.com/w0ts/optimist, firmware/hal/fm1_cache.h, 9a1360ab), offered
 *   there under GPL-3.0-only OR MPL-2.0 (Optimist 3815869f, LICENSING.md "The cache RAM"); taken here
 *   under MPL-2.0
 * Written against the public JieLi AC79 SDK (Apache-2.0); see NOTICE. */
/* Data-cache ways as RAM: 1..7 of the 8 data-cache ways (4 KiB each) used as plain RAM at 0x01F28000 + way x 4 KiB,
 * as M-VAVE's FM-1 firmware (V15, 7 ways) and the AC79 SDK's flash-only builds do (cpu/wl82/sdk_ld_sfc.c
 * FREE_DACHE_WAY = 7, its cache_ram region; it keeps its system tables and lwIP's pools there). Ways 0..n-1 become
 * RAM, the top 8 - n stay a cache; all 8 instruction-cache ways (the flash's code) stay caches.
 *
 * The registers (corex2, the SDK's asm/csfr.h): CACHE_CON 0x01EEE008 (bit 14 idle, read only; bit 8 the cache on, bit
 * 9 on for SDRAM / PSRAM), DCACHE_WAY 0x01EEE00C, ICACHE_WAY 0x01EEE010; one set for the corex2 cluster (beside its
 * C0_CON and C1_CON), not one per core. A set bit is a way kept as a cache: DCACHE_WAY holds three 8-bit masks (bits
 * 0..7, 8..15, 16..23; which requester each serves is not known: all three get the same), ICACHE_WAY two. The
 * sequence (the SDK's cache_way_config, as V15 runs it from RAM): wait for idle; CACHE_CON bits 8-9 off; the masks;
 * every tag invalid (0x01F00000..0x01F04000, 0x01F08000..0x01F0A200, 0x01F0B000..0x01F0B200 zeroed); CACHE_CON back
 * as it was. With the cache off nothing may be fetched from the flash: fm1_cache_set is RAM code (.ram_text, copied
 * before it runs), calls nothing (its loops volatile: no memset), and runs with the interrupts off and the second
 * core stopped.
 *
 *   fm1_cache_ram_init(n)   once at the start, after .ram_text is copied, before the second core, the interrupts and
 *                           anything that uses the memory: n ways as RAM, tested (each word its address pattern, then
 *                           the complement, read back after each whole pass: an aliased way shows), zeroed. A cache
 *                           that never idles, masks that do not read back, or a failed test: the masks back as the
 *                           boot loader left them, the status says which, and fm1_cache_ram_bytes() is 0
 *   fm1_cache_ram_bytes()   the bytes usable from FM1_CR_LO (0: none: not asked for, or the test failed)
 *   fm1_cr                  the result and the registers before and after (a readout)
 *
 * Measured on one FM-1 (Optimist, 2026-10-18 .. 25): the test passes; the memory is as fast as main RAM (35 ns a read);
 * 2 ways in daily use for days, no fault; with 7 ways flash data reads over 16 KiB are 57x slower (1.7 us against
 * 32 ns: the flash's data goes through this cache, 4 KiB of it left), so fewer ways keep the flash's data fast. Not
 * measured: the second core's and DMA's access to it.
 *
 * The host (tests/cache_ram_test.c) builds the same code over a model: FM1_CR_P maps an address, FM1_CR_RD reads a
 * word of the test, FM1_CR_SET_DONE runs after the masks are written, FM1_CR_SYNC and FM1_CR_RAMFN as below. */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"

#define FM1_CR_LO 0x01F28000u                         /* data way 0 */
#define FM1_CR_WAY 4096u
#define FM1_CR_MAX 7u                                 /* (one way at least stays a cache) */
enum { FM1_CR_OFF, FM1_CR_OK, FM1_CR_BUSY, FM1_CR_REG, FM1_CR_BAD };   /* not asked / ready / never idle / masks not
                                                                        * taken / the test failed (all put back) */
typedef struct {
    uint32_t status, ways;                            /* the result; the ways asked for */
    uint32_t con, dway0, iway0;                       /* CACHE_CON and the masks as the boot loader left them */
    uint32_t dway, iway, bad_at;                      /* the masks read back after; the first failing address */
} fm1_cr_t;
static fm1_cr_t fm1_cr;

FM1_INLINE uint32_t fm1_cache_ram_bytes(void) { return fm1_cr.status == FM1_CR_OK ? fm1_cr.ways * FM1_CR_WAY : 0u; }

#ifndef FM1_CR_P
#define FM1_CR_P(a) ((volatile uint32_t *)(uintptr_t)(a))
#endif
#ifndef FM1_CR_RD
#define FM1_CR_RD(p) (*(p))
#endif
#ifndef FM1_CR_SET_DONE
#define FM1_CR_SET_DONE() ((void)0)
#endif
#ifndef FM1_CR_SYNC
#ifdef __PI32V2__
#define FM1_CR_SYNC() __asm__ volatile("csync\n\tssync" ::: "memory")
#else
#define FM1_CR_SYNC() __asm__ volatile("" ::: "memory")
#endif
#endif
#ifndef FM1_CR_RAMFN
#define FM1_CR_RAMFN __attribute__((section(".ram_text"), noinline, used))
#endif
#define FM1_CR_CON FM1_CR_P(0x01EEE008u)
#define FM1_CR_DWAY FM1_CR_P(0x01EEE00Cu)
#define FM1_CR_IWAY FM1_CR_P(0x01EEE010u)

FM1_INLINE void fm1_cr_zero(uint32_t lo, uint32_t hi)
{
    uint32_t a;
    for (a = lo; a < hi; a += 4u)
        *FM1_CR_P(a) = 0;
}

/* the masks set, every tag invalid; RAM only, interrupts off. 0: the cache never went idle (nothing changed) */
static FM1_CR_RAMFN uint32_t fm1_cache_set(uint32_t dway, uint32_t iway)
{
    uint32_t con, n = 2400000u;                       /* (~10 ms at 240 MHz: a fill never takes that long) */
    while (!(*FM1_CR_CON & 0x4000u))
        if (!--n)
            return 0;
    con = *FM1_CR_CON;
    *FM1_CR_CON = con & ~0x300u;
    FM1_CR_SYNC();
    *FM1_CR_DWAY = dway;
    *FM1_CR_IWAY = iway;
    FM1_CR_SET_DONE();
    fm1_cr_zero(0x01F00000u, 0x01F04000u);
    fm1_cr_zero(0x01F08000u, 0x01F0A200u);
    fm1_cr_zero(0x01F0B000u, 0x01F0B200u);
    FM1_CR_SYNC();
    *FM1_CR_CON = con;                                /* (bits 8-9 as they were) */
    FM1_CR_SYNC();
    return 1;
}

/* lo .. hi: each word its address pattern, then the complement, read back after the whole pass. 0 good, else the
 * first failing address. Ends zeroed */
static uint32_t fm1_cache_test(uint32_t lo, uint32_t hi)
{
    uint32_t pass, x, a;
    for (pass = 0; pass < 2u; pass++) {
        x = pass ? 0xFFFFFFFFu : 0u;
        for (a = lo; a < hi; a += 4u)
            *FM1_CR_P(a) = (a ^ 0x5AC3A53Cu) ^ x;
        FM1_CR_SYNC();
        for (a = lo; a < hi; a += 4u)
            if (FM1_CR_RD(FM1_CR_P(a)) != ((a ^ 0x5AC3A53Cu) ^ x))
                return a;
    }
    fm1_cr_zero(lo, hi);
    return 0;
}

/* once at the start (see the top): ways 0 does nothing (FM1_CR_OFF) */
static void fm1_cache_ram_init(uint32_t ways)
{
    uint32_t (*volatile set)(uint32_t, uint32_t) = fm1_cache_set;   /* (XIP -> RAM: past the 23-bit call range) */
    uint32_t keep, dw, iw;
    fm1_cr.ways = ways;
    if (!ways || ways > FM1_CR_MAX) {
        fm1_cr.status = FM1_CR_OFF;
        return;
    }
    keep = (0xFFu << ways) & 0xFFu;                   /* (a mask byte: the ways kept as a cache) */
    fm1_cr.con = *FM1_CR_CON;
    fm1_cr.dway0 = *FM1_CR_DWAY;
    fm1_cr.iway0 = *FM1_CR_IWAY;
    dw = (fm1_cr.dway0 & 0xFF000000u) | keep | keep << 8 | keep << 16;
    iw = (fm1_cr.iway0 & 0xFFFF0000u) | 0x0000FFFFu;
    if (!set(dw, iw)) {
        fm1_cr.status = FM1_CR_BUSY;
        return;
    }
    fm1_cr.dway = *FM1_CR_DWAY;
    fm1_cr.iway = *FM1_CR_IWAY;
    if (fm1_cr.dway != dw || fm1_cr.iway != iw)
        fm1_cr.status = FM1_CR_REG;
    else if ((fm1_cr.bad_at = fm1_cache_test(FM1_CR_LO, FM1_CR_LO + ways * FM1_CR_WAY)) != 0)
        fm1_cr.status = FM1_CR_BAD;
    else {
        fm1_cr.status = FM1_CR_OK;
        return;
    }
    set(fm1_cr.dway0, fm1_cr.iway0);                  /* back as the boot loader left them: nothing is placed there */
}

text.fm1-base/bsp/chip/fm1_clock.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal */
/* FM-1 system clock: as M-VAVE's bootloader leaves it, whichever bootloader started us.
 *
 * Read off FM-1s with fm1-x0x's debug build (tools/fm1_debug.py, 2026-10-23): under M-VAVE's bootloader the CPU
 * runs at 360 MHz (a one-instruction loop 51.43 per us): PLL1 = 24 MHz / 12 * 270 = 540 MHz (0x119A8 0x0940022B,
 * 0x119AC 0x0750310C), the system clock 2/3 of it (0x10014 [7:0] = 6), HSB /2 = 180, LSB /3 = 60 (0x10008
 * 0x00010200), 0x1000C 0x1C1. Under m-bootloader 1.2 the same FM-1 ran at 320 MHz (45.71 per us): 0x10014 = 2,
 * PLL1 off (0x119A8 = 0x119AC = 0); everything else the same, the flash's divider (0x40204 = 1) too. Every firmware
 * was 11 % slower, and the peripherals' clock (the LCD's SPI, the UARTs' dividers, set for 60 MHz) 53 MHz.
 *
 * So at the start: if the clock is not the stock one, PLL1 is started with M-VAVE's values and the system clock
 * moved onto it, the steps in m-bootloader's own clock setup (github.com/jvitkauskas/m-bootloader, MIT,
 * src/platform.c hal_clock_a): the system clock off the PLL mux (0x1000C bit 8: the crystal) while PLL1 starts,
 * the source picked, back onto the mux. From RAM with interrupts off (the flash's clock moves under it); the waits
 * on TIMER4 (the crystal, fm1_time.h), inline. The flash's divider stays as the bootloader set it: the same as
 * under M-VAVE's. Returns 0 nothing to do, 1 set (and reads back stock), -1 set but did not read back stock. */
#pragma once
#include <stdint.h>
#include "fm1_flash.h"                                  /* RAMFN, RAMINL, FL_FAR, REG32 */

#define CLK_HSB_CON   REG32(0x10008u)                   /* [17:16] HSB divider - 1, [10:8] LSB divider - 1 */
#define CLK_MUX_CON   REG32(0x1000Cu)                   /* bit 8: the system clock from the PLL mux */
#define CLK_SYS_CON   REG32(0x10014u)                   /* [7:0] the system clock's source: 6 = PLL1 * 2/3 */
#define CLK_PLL1_CON0 REG32(0x119A8u)                   /* [1:0] enable, run; [6:2] reference divider - 2 */
#define CLK_PLL1_CON1 REG32(0x119ACu)                   /* [11:0] multiplier - 2 */
#define CLK_T4_CNT    REG32(0x10804u)                   /* TIMER4, 24 MHz from the crystal (fm1_time.h) */
#define CLK_PLL0_CON0 REG32(0x119A0u)                   /* the PLL m-bootloader starts before PLL1 (0x45400200, */
#define CLK_PLL0_CON1 REG32(0x119A4u)                   /* 0x3F503026; running, 0x45400203, under M-VAVE's too) */
#define CLK_STOCK_SYS   6u
#define CLK_STOCK_PLL0  0x0940022Bu
#define CLK_STOCK_PLL1  0x0750310Cu
#define CLK_STOCK_HSB   0x00010200u

/* the clock's registers as they are (a report): the system clock's source, the mux, PLL1, the other PLL */
static inline void fm1_clock_read(uint32_t r[6])
{
    r[0] = CLK_SYS_CON & 0xFFu;
    r[1] = CLK_MUX_CON;
    r[2] = CLK_PLL1_CON0;
    r[3] = CLK_PLL1_CON1;
    r[4] = CLK_PLL0_CON0;
    r[5] = CLK_PLL0_CON1;
}

static inline int fm1_clock_is_stock(void)
{
    return (CLK_SYS_CON & 0xFFu) == CLK_STOCK_SYS && CLK_PLL1_CON0 == CLK_STOCK_PLL0 &&
           (CLK_PLL1_CON1 & 0x07FFFFFFu) == CLK_STOCK_PLL1 && (CLK_MUX_CON & (1u << 8));
}

RAMINL void fm1_clock_wait_us(uint32_t us)              /* (inline: RAM code calls nothing) */
{
    uint32_t t0 = CLK_T4_CNT;
    while ((uint32_t)(CLK_T4_CNT - t0) < us * 24u)
        ;
}

static RAMFN void fm1_clock_set_stock_ram(void)
{
    CLK_MUX_CON &= ~(1u << 8);                          /* the system clock on the crystal meanwhile */
    __asm__ volatile("csync" ::: "memory");
    fm1_clock_wait_us(20);
    CLK_PLL1_CON0 = CLK_STOCK_PLL0 & ~3u;               /* PLL1: 24 / 12 * 270 = 540 MHz, stopped */
    CLK_PLL1_CON1 = CLK_STOCK_PLL1;
    CLK_PLL1_CON0 |= 1u;                                /* on */
    fm1_clock_wait_us(100);
    CLK_PLL1_CON0 |= 2u;                                /* running */
    fm1_clock_wait_us(900);                                 /* (its lock, as m-bootloader waits) */
    CLK_SYS_CON = (CLK_SYS_CON & ~0xFFu) | CLK_STOCK_SYS;   /* 2/3 of it: 360 MHz */
    CLK_HSB_CON = (CLK_HSB_CON & ~0x30700u) | CLK_STOCK_HSB;  /* HSB /2, LSB /3 (as they were) */
    CLK_MUX_CON |= (1u << 6) | (1u << 7);
    CLK_MUX_CON |= (1u << 8);                           /* back onto the mux */
    __asm__ volatile("csync" ::: "memory");
    fm1_clock_wait_us(20);
}

/* (interrupts off around it: the caller's, as fm1_main's start has them) */
static inline int fm1_clock_stock(void)
{
    if (fm1_clock_is_stock())
        return 0;
    FL_FAR(fm1_clock_set_stock_ram)();
    return fm1_clock_is_stock() ? 1 : -1;
}

/* Another PLL1 multiplier, by the same steps: 24 / 12 * mul MHz, the system clock 2/3 of it (270: the stock 360 MHz;
 * 297: 396 MHz, JieLi's top, which its SDK marks not for mass production). HSB /2 and LSB /3 follow (198 / 66 MHz at
 * 297: the LCD's SPI and the UARTs' dividers 10 % faster), the flash's serial clock with HSB; the audio PLL (PLL0) is
 * not touched. Interrupts off around it, as fm1_clock_stock. A soft reset keeps the PLL: a firmware that raises it
 * calls fm1_clock_restore before its resets and its update loader (fm1-base does), so nothing starts above stock. Not
 * in fm1_sys.h: the update loader includes that, and fm1_flash.h here would change its flash checks */
static RAMFN void fm1_clock_pll1_ram(uint32_t mul)
{
    CLK_MUX_CON &= ~(1u << 8);
    __asm__ volatile("csync" ::: "memory");
    fm1_clock_wait_us(20);
    CLK_PLL1_CON0 = CLK_STOCK_PLL0 & ~3u;
    CLK_PLL1_CON1 = (CLK_STOCK_PLL1 & ~0xFFFu) | (mul - 2u);
    CLK_PLL1_CON0 |= 1u;
    fm1_clock_wait_us(100);
    CLK_PLL1_CON0 |= 2u;
    fm1_clock_wait_us(900);
    CLK_SYS_CON = (CLK_SYS_CON & ~0xFFu) | CLK_STOCK_SYS;
    CLK_HSB_CON = (CLK_HSB_CON & ~0x30700u) | CLK_STOCK_HSB;
    CLK_MUX_CON |= (1u << 6) | (1u << 7);
    CLK_MUX_CON |= (1u << 8);
    __asm__ volatile("csync" ::: "memory");
    fm1_clock_wait_us(20);
}
static inline void fm1_clock_pll1(uint32_t mul) { FL_FAR(fm1_clock_pll1_ram)(mul); }
/* (before a reset) PLL1 back to the stock multiplier if it was changed; nothing otherwise */
static inline void fm1_clock_restore(void)
{
    if ((CLK_PLL1_CON1 & 0xFFFu) != (CLK_STOCK_PLL1 & 0xFFFu) && (CLK_PLL1_CON0 & 3u) == 3u)
        fm1_clock_pll1((CLK_STOCK_PLL1 & 0xFFFu) + 2u);
}
/* the system clock in kHz when it runs on PLL1 * 2/3 as the stock setup does (any multiplier), else 0 (unknown) */
static inline uint32_t fm1_clock_khz(void)
{
    if ((CLK_SYS_CON & 0xFFu) != CLK_STOCK_SYS || !(CLK_MUX_CON & (1u << 8)) || (CLK_PLL1_CON0 & ~0x7Cu) != (CLK_STOCK_PLL0 & ~0x7Cu)
        || (((CLK_PLL1_CON0 >> 2) & 31u) + 2u) != 12u)
        return 0;
    return 24000u / 12u * ((CLK_PLL1_CON1 & 0xFFFu) + 2u) * 2u / 3u;
}

