/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Kerem Kilic (Ellic Studio) */
/* XIP-side wrappers. Included by fm1_flash.h after the RAM entry points;
 * kept separate so host tests exercise the same paging/locking code. */
#pragma once

static uint32_t fl_jedec(void)
{
    uint32_t f = irq_save(), id = FL_FAR(fl_jedec_ram)();
    irq_restore(f);
    return id;
}

static uint32_t fl_status(void)
{
    uint32_t f = irq_save(), v = FL_FAR(fl_status_ram)();
    irq_restore(f);
    return v;
}

#ifdef FL_UID
static int fl_uid(uint8_t *dst)
{
    uint32_t f = irq_save();
    int rc = FL_FAR(fl_uid_ram)(dst);
    irq_restore(f);
    return rc;
}
#endif

static int fl_erase4k(uint32_t off, uint32_t *took_us)
{
    uint32_t f = irq_save();
    int rc = FL_FAR(fl_erase4k_ram)(off, took_us);
    irq_restore(f);
    return rc;
}

static int fl_write(uint32_t off, const uint8_t *src_ram, uint32_t n)
{
    uint32_t took, o, left;
    if (!n) return 0;                           /* nothing to write: 0, whatever off and src_ram are */
    /* Validate the WHOLE request before the first page can change: inside the part, without wrapping, and every
     * page inside a write region, as fl_prog_ram checks it. A write may run across regions that touch (the
     * defaults' AUTO and XDATA1 at 0xE7000), as it could when each page was checked only as it was written. */
    if (!FL_READ_OK(off, n)) return FL_ERR_RANGE;
    for (o = off, left = n; left; ) {
        uint32_t chunk = 256u - (o & 0xFFu);
        if (chunk > left) chunk = left;
        if (!FL_WRITE_OK(o, chunk)) return FL_ERR_RANGE;
        o += chunk; left -= chunk;
    }
    if (!FL_RAM_OK(src_ram, n)) return FL_ERR_BUFFER;
    while (n) {
        uint32_t chunk = 256u - (off & 0xFFu), f;
        int rc;
        if (chunk > n) chunk = n;
        f = irq_save();
        rc = FL_FAR(fl_prog_ram)(off, src_ram, chunk, &took);
        irq_restore(f);
        if (rc) return rc;
        off += chunk; src_ram += chunk; n -= chunk;
    }
    return 0;
}

static int fl_read(uint32_t off, uint8_t *dst_ram, uint32_t n)
{
    if (!n) return 0;                           /* as fl_write */
    if (!FL_READ_OK(off, n)) return FL_ERR_RANGE;
    if (!FL_RAM_OK(dst_ram, n)) return FL_ERR_BUFFER;
    while (n) {
        uint32_t chunk = n > 256u ? 256u : n, f = irq_save();
        int rc = FL_FAR(fl_read_ram)(off, dst_ram, chunk);
        irq_restore(f);
        if (rc) return rc;
        off += chunk; dst_ram += chunk; n -= chunk;
    }
    return 0;
}

/* Plain-window XIP reads are only valid within the explicitly mapped area. */
static int fl_verify_xip(uint32_t off, const uint8_t *ref, uint32_t n)
{
    const volatile uint8_t *p;
    uint32_t i;
    if (!FL_PLAIN_OK(off, n)) return FL_ERR_RANGE;
    if (!FL_RAM_OK(ref, n)) return FL_ERR_BUFFER;
    p = (const volatile uint8_t *)(uintptr_t)FL_XIP(off);
    for (i = 0; i < n; i++) if (p[i] != ref[i]) return -(int)(i + 1);
    return 0;
}

text.fm1-base/bsp/chip/fm1_flash_ext.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* Expanded flash, EXPERIMENTAL: what to do when the FM-1's SOIC-8 flash (stock: a 1 MiB part, JEDEC 85 60 14) is
 * replaced by a larger one. Pure logic, no registers: it decides the size and where the extra room is. The
 * read/erase/program entry points stay those of fm1_flash.h: set FM1_FLASH_SIZE and
 * FM1_FLASH_WRITE_REGIONS before inclusion, then check the detected size before allowing writes.
 *
 * Standard SPI NOR (Winbond, GigaDevice, Puya, Macronix, ...) puts the capacity in the last JEDEC byte as
 * log2(bytes): 0x14 = 1 MiB, 0x15 = 2, 0x16 = 4, 0x17 = 8, 0x18 = 16 MiB, 0x19 = 32 MiB.
 *   - The 3-byte address of fm1_flash.h reaches 16 MiB. Above that a part needs 4-byte mode: not supported here.
 *   - The first 1 MiB keeps the stock layout (head, app slot, Felucca's regions): the mask-ROM and the SPL read it.
 *   - The extra room [1 MiB, size) is plain data: the application decides what goes there. It is not covered by
 *     the update loader's window.
 *   - Not known yet: how much of the flash the XIP window can map, and whether the quad-enable bit of the new part
 *     is where the stock part has it (the SR2 bit 1 of the common Winbond-style parts).
 * fm1_flash_ext_ok(off, n, size) is the range check of fm1_flash.h's FL_IN, with the size taken from the part. */
#pragma once
#include <stdint.h>

#define FM1_FLASH_STOCK_SIZE 0x100000u       /* 1 MiB: the region the stock layout lives in */
#define FM1_FLASH_MAX_3BYTE  0x1000000u      /* 16 MiB */

/* bytes for a JEDEC id (mfr << 16 | type << 8 | capacity code), 0 when it is not a standard NOR capacity code */
static inline uint32_t fm1_flash_size_from_jedec(uint32_t id)
{
    uint32_t c = id & 0xFFu;
    if (id == 0 || id == 0xFFFFFFu || c < 0x14u || c > 0x19u)       /* 1 MiB .. 32 MiB */
        return 0;
    return 1u << c;
}

/* usable with 3-byte addressing: the size, capped at 16 MiB */
static inline uint32_t fm1_flash_usable(uint32_t size)
{
    return size > FM1_FLASH_MAX_3BYTE ? FM1_FLASH_MAX_3BYTE : size;
}

/* [off, off+n) inside the extra room [1 MiB, usable), without wrapping */
static inline int fm1_flash_ext_ok(uint32_t off, uint32_t n, uint32_t size)
{
    uint32_t hi = fm1_flash_usable(size);
    return hi > FM1_FLASH_STOCK_SIZE && off >= FM1_FLASH_STOCK_SIZE && off <= hi && n <= hi - off;
}

text.fm1-base/bsp/chip/fm1_flash_wait.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (c) 2026 Julius Vitkauskas */
/* Completion of an issued erase / page program, for fm1_flash.h's RAM driver and its host model
 * (tests/flash_wait_test.c). The includer supplies RAMINL, fl_rdsr(cmd), T4_CNT (24 MHz, free-running) and
 * fl_reset_busy() (does not return: fm1_flash.h resets the part, then the chip).
 *
 * fl_wait_issued(issued, normal, extended, took): issued is T4_CNT read before the command went out, so the time
 * counts the command's SPI transfer and the cache invalidation too. It returns only once SR1.BUSY reads clear:
 *   - clear within `normal` us: 0;
 *   - clear later (but before `extended`): FL_ERR_LATE_READY (-4): the code a part
 *     still busy at the normal bound got from fl_wait_ready, so callers see the same codes for the same
 *     cases;
 *   - still busy at `extended` us: fl_reset_busy().
 * *took gets the microseconds to the status read that saw BUSY clear.
 * Before, a part busy at the normal bound made fl_wait_ready return -4 and the driver switched XIP back on while the
 * part was still erasing or programming. A NOR part does not answer reads while it erases or programs (no
 * read-while-write), so the next code or data fetched through XIP was whatever the bus returned. A slow part now
 * finishes first; a stuck one ends in a reset, never in a fetch from it.
 * fm1_flash.h's bounds are generic SPI NOR figures, not measurements of the FM-1's part: normal = the bounds
 * fl_wait_ready had (sector erase 500 ms, page program 10 ms, above the generic NOR maxima of 400 ms and 3 ms),
 * extended = 2 s and 50 ms. What the chip's boot does with a part that stays busy after the reset is not known.
 * The unsigned difference survives one TIMER4 wrap (178.9 s), far beyond either bound. */
#pragma once
#define FL_ERR_LATE_READY (-4)
RAMINL int fl_wait_issued(uint32_t issued, uint32_t normal, uint32_t extended, uint32_t *took_us)
{
    for (;;) {
        uint32_t status = fl_rdsr(0x05), dt = (T4_CNT - issued) / 24u;
        if (!(status & 1u)) { *took_us = dt; return dt <= normal ? 0 : FL_ERR_LATE_READY; }
        if (dt >= extended) fl_reset_busy();
    }
}
/* The fast install's erase while a sector comes in (fm1_flash.h fl_erase4k_end_ram): the caller did its own work (a
 * 4 KiB read from the host, from RAM, XIP off) between the command and this wait. A part seen idle at the first status
 * read is done: 0, however long that work took. One still busy is waited out as fl_wait_issued, counted from the
 * command: late past `normal`, a reset at `extended`. */
RAMINL int fl_wait_split(uint32_t issued, uint32_t normal, uint32_t extended, uint32_t *took_us)
{
    if (!(fl_rdsr(0x05) & 1u)) { *took_us = (T4_CNT - issued) / 24u; return 0; }
    return fl_wait_issued(issued, normal, extended, took_us);
}

