/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 time base: TIMER4 free-running from the 24 MHz crystal.
 * Measured on hardware: under mask-ROM UBOOT the crystal runs and TIMER4 counts
 * 24 MHz, matching the host's measurement of the same interval to 0.3 %.
 * TIMER4 is not used by the ROM or the SPL. No interrupts, no ROM calls.
 *
 * JL_TIMER4 = 0x10800: CON [1:0]=1 run, [3:2]=2 OSC source, [7:4]=0 /1,
 * bit14 = clear pending; CNT +4; PRD +8 (32-bit, set to 0xFFFFFFFF).
 * The counter wraps every 178.9 s; use differences (unsigned arithmetic).
 */
#pragma once
#include <stdint.h>

#define FM1_T4_CON (*(volatile uint32_t *)0x10800u)
#define FM1_T4_CNT (*(volatile uint32_t *)0x10804u)
#define FM1_T4_PRD (*(volatile uint32_t *)0x10808u)
#define FM1_TICKS_PER_US 24u

/* Start TIMER4 unless it already runs, so time stays continuous across
 * RAM-run jumps. */
static inline void fm1_time_init(void)
{
    if ((FM1_T4_CON & 0xFu) == ((2u << 2) | 1u))
        return;
    FM1_T4_CON = 0;
    FM1_T4_PRD = 0xFFFFFFFFu;
    FM1_T4_CNT = 0;
    FM1_T4_CON = (2u << 2) | 1u | (1u << 14);
}

static inline uint32_t fm1_ticks(void) { return FM1_T4_CNT; }

/* Microseconds, wrapping every ~178.9 s. */
static inline uint32_t fm1_micros(void) { return FM1_T4_CNT / FM1_TICKS_PER_US; }

static inline void fm1_delay_us(uint32_t us)
{
    uint32_t start = FM1_T4_CNT, span = us * FM1_TICKS_PER_US;
    while ((uint32_t)(FM1_T4_CNT - start) < span)
        ;
}

static inline void fm1_delay_ms(uint32_t ms)
{
    while (ms--)
        fm1_delay_us(1000u);
}

text.fm1-base/bsp/chip/fm1_timer.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 TIMER5: the 10 kHz system tick (input scan, USB poll, ms count).
 * TIMER4 is the free-running time base (fm1_time.h); both are unused by the
 * ROM and the SPL. JL_TIMER5 = 0x10900: CON, CNT +4, PRD +8.
 *
 *   fm1_timer5_start(isr, prio)   OSC /4 = 6 MHz, PRD 600 -> 10 kHz, IRQ 63
 *   fm1_timer5_ack()              first thing in the ISR
 * The period: FM1_T5_PERIOD (6 MHz ticks), or else 6 MHz / FM1_INPUT_HZ (the
 * input scan's rate, boards/fm1/fm1_input.h: 1200 at 5000, 3000 at 2000), else 600.
 */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"
#include "fm1_irq.h"

#define FM1_T5_CON (*(volatile uint32_t *)0x10900u)
#define FM1_T5_CNT (*(volatile uint32_t *)0x10904u)
#define FM1_T5_PRD (*(volatile uint32_t *)0x10908u)
#ifndef FM1_T5_PERIOD
#ifdef FM1_INPUT_HZ
#define FM1_T5_PERIOD (6000000u / (FM1_INPUT_HZ))
#else
#define FM1_T5_PERIOD 600u                 /* 6 MHz / 600: 10 kHz */
#endif
#endif

FM1_INLINE void fm1_timer5_start(void (*isr)(void), uint32_t prio)   /* IRQs off */
{
    FM1_T5_CON = 0x4000u;
    FM1_T5_CNT = 0;
    FM1_T5_PRD = FM1_T5_PERIOD;
    fm1_irq_attach(FM1_IRQ_TIMER5, isr, prio);
    FM1_T5_CON = 0x4019u;
}

FM1_INLINE void fm1_timer5_ack(void) { FM1_T5_CON |= 0x4000u; }

text.fm1-base/bsp/chip/fm1_uart.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 UART1 as MIDI IN: PH8 -> input
 * channel 1 -> UART1 RX, 31250 baud, RX DMA into a ring, polled (no IRQ).
 * The MIDI parser is midi_uart.c. RX verified on hardware.
 *
 *   fm1_uart1_midi_init(ring, len)   len a power of two, ring aligned 16;
 *                                    before TIMER5 starts (PORTH RMW)
 *   fm1_uart1_rx_take()              bytes DMA'd since the last call
 */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"

#define FM1_UT1_CON0   (*(volatile uint32_t *)0x12100u)
#define FM1_UT1_CON1   (*(volatile uint32_t *)0x12104u)
#define FM1_UT1_BAUD   (*(volatile uint32_t *)0x12108u)
#define FM1_UT1_OTCNT  (*(volatile uint32_t *)0x12110u)
#define FM1_UT1_RXSADR (*(volatile uint32_t *)0x1211Cu)
#define FM1_UT1_RXEADR (*(volatile uint32_t *)0x12120u)
#define FM1_UT1_RXCNT  (*(volatile uint32_t *)0x12124u)
#define FM1_UT1_HRXCNT (*(volatile uint32_t *)0x12128u)
#define FM1_UM_CLK_CON1  (*(volatile uint32_t *)0x10010u)   /* [11:10] UART clock: 1 = PLL48M */
#define FM1_UM_IOMAP2    (*(volatile uint32_t *)0x51024u)   /* input ch1 source [13:8] */
#define FM1_UM_IOMAP3    (*(volatile uint32_t *)0x51028u)   /* UT1: b7 fixed IO, [6:4] RX select */
#define FM1_UM_PH_DIR    (*(volatile uint32_t *)0x501C8u)
#define FM1_UM_PH_DIE    (*(volatile uint32_t *)0x501CCu)
#define FM1_UM_PH_PU     (*(volatile uint32_t *)0x501D0u)
#define FM1_UM_PH_PD     (*(volatile uint32_t *)0x501D4u)

FM1_INLINE void fm1_uart1_midi_init(volatile uint8_t *ring, uint32_t len)
{
    FM1_UT1_CON0 = 0x3400u;                            /* off, pendings cleared */
    FM1_UT1_CON1 = 0;
    FM1_UM_CLK_CON1 = (FM1_UM_CLK_CON1 & ~(3u << 10)) | (1u << 10);
    FM1_UM_IOMAP3 &= ~0x80u;
    FM1_UM_IOMAP3 = (FM1_UM_IOMAP3 & ~0x70u) | (5u << 4);   /* UT1 RX = input ch 1 */
    FM1_UM_IOMAP2 = (FM1_UM_IOMAP2 & ~0x3F00u) | (49u << 8);/* ch 1 = PH8 */
    FM1_UM_PH_PD &= ~(1u << 8);
    FM1_UM_PH_DIE |= 1u << 8;
    FM1_UM_PH_DIR |= 1u << 8;
    FM1_UM_PH_PU |= 1u << 8;
    FM1_UT1_RXSADR = (uint32_t)(uintptr_t)ring;
    FM1_UT1_RXEADR = (uint32_t)(uintptr_t)ring + len;
    FM1_UT1_RXCNT = len;
    FM1_UT1_BAUD = 48000000u / 31250u / 4u - 1u;       /* 383 */
    FM1_UT1_OTCNT = 60000u;
    __asm__ volatile("csync" ::: "memory");
    FM1_UT1_CON0 = 0x40u | 0x80u | 0x1000u | 0x400u;   /* RXDMA, RDC, clear R/OT; no IEs */
    __asm__ volatile("csync" ::: "memory");
    FM1_UT1_CON0 |= 1u;                                /* UTEN last */
}

FM1_INLINE uint32_t fm1_uart1_rx_take(void)
{
    FM1_UT1_CON0 |= 0x80u;                             /* RDC: latch the count */
    __asm__ volatile("csync" ::: "memory");
    FM1_UT1_CON0 |= 0x1400u;                           /* clear RPND / OTPND */
    return FM1_UT1_HRXCNT & 0xFFFFu;
}

text.fm1-base/bsp/chip/fm1_usb.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments
 * Host mode additions Copyright (C) 2026 Adrien Tibi (Recursive Field Instruments); see NOTICE.
 * Written against the public JieLi AC79 SDK (Apache-2.0); see NOTICE. */
/* FM-1 USB0 full-speed device controller, register level only
 * The protocol (descriptors, EP0 requests,
 * MIDI / CDC / SysEx) is the driver src/usb.c, shared with the update loader
 * and the host tests; this header is every USB register access it makes.
 *
 *   fm1_usb_reset()        CON0 = CON1 = 0, pads detached; wait >= 20 ms
 *   fm1_usb_attach(ep0)    clock, EP DMA defaults, PHY on, D+ pull-up
 *   fm1_usb_off()          detach: controller off, pads inputs
 *   SIE (MUSB byte map):   fm1_usb_sie_on, _wr_start / _rd_start, _done, _data
 *   EP DMA:                fm1_usb_ep0_buf, fm1_usb_ep_txbuf / _rxbuf,
 *                          fm1_usb_ep0_send / fm1_usb_ep_send (csync first),
 *                          fm1_usb_rx_sync (ssync before reading an RX buffer)
 *   EP4 (own slots): fm1_usb_ep4_txbuf, fm1_usb_ep4_send (csync first);
 *                          isochronous mode is TXCSR2 bit 6 through the SIE (usb.c)
 *   fm1_usb_ep_enable(m)   CON0 &= ~(m << 19), m = bit per endpoint
 *   fm1_usb_sof_take()     SOF pending -> clear, 1
 *   fm1_usb_host_attach(ep0) / fm1_usb_line()   host PHY setup / D+ and D- levels
 * No IRQ: everything is polled (usb_poll from the TIMER5 ISR). */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"

#define FM1_USB_CON0 (*(volatile uint32_t *)(uintptr_t)0x11800u)
#define FM1_USB_CON1 (*(volatile uint32_t *)(uintptr_t)0x11804u)
#define FM1_USB_EP_CNT(n) (*(volatile uint32_t *)(uintptr_t)(0x11808u + 4u * (n)))          /* EP0..3 */
#define FM1_USB_EP0_ADR (*(volatile uint32_t *)(uintptr_t)0x11818u)
#define FM1_USB_EP_TADR(n) (*(volatile uint32_t *)(uintptr_t)(0x1181Cu + 8u * ((n) - 1u)))  /* EP1..3 */
#define FM1_USB_EP_RADR(n) (*(volatile uint32_t *)(uintptr_t)(0x11820u + 8u * ((n) - 1u)))  /* EP1..3 */
#define FM1_USB_EP4_CNT (*(volatile uint32_t *)(uintptr_t)0x11834u)
#define FM1_USB_EP4_TADR (*(volatile uint32_t *)(uintptr_t)0x11838u)
#define FM1_USB_EP4_RADR (*(volatile uint32_t *)(uintptr_t)0x1183Cu)
#define FM1_USB_IO_CON0 (*(volatile uint32_t *)(uintptr_t)0x51000u)
#define FM1_CLK_CON1 (*(volatile uint32_t *)(uintptr_t)0x10010u)

FM1_INLINE void fm1_usb_reset(void)
{
    FM1_USB_CON0 = 0;
    FM1_USB_CON1 = 0;
    FM1_USB_IO_CON0 = 0x0Cu;
}

FM1_INLINE void fm1_usb_attach(void *ep0)
{
    uint32_t n;
    FM1_CLK_CON1 &= ~3u;                                /* USB clock = PLL48M */
    FM1_USB_EP0_ADR = (uint32_t)(uintptr_t)ep0;
    for (n = 1; n <= 3u; n++)
        FM1_USB_EP_RADR(n) = (uint32_t)(uintptr_t)ep0;
    FM1_USB_EP4_RADR = (uint32_t)(uintptr_t)ep0;
    FM1_USB_IO_CON0 |= (1u << 10) | (1u << 9);
    FM1_USB_IO_CON0 &= ~(1u << 11);
    FM1_USB_IO_CON0 |= 1u << 12;
    FM1_USB_CON0 &= ~0x4035u;
    FM1_USB_CON1 = 0;
    FM1_USB_CON0 |= 1u;
    FM1_USB_IO_CON0 &= ~0xF0u;
    FM1_USB_IO_CON0 |= 0x40u;                           /* D+ pull-up: attach */
    FM1_USB_CON0 |= 0x3Cu;
}

FM1_INLINE void fm1_usb_off(void)
{
    FM1_USB_CON0 = 0;
    FM1_USB_IO_CON0 = 0x0Cu;
}

/* Host (A-device) on USB0, the sequence of the AC79 SDK's usb_h_sie_init(0): D+ / D- digital inputs with their
 * pull-downs (USB_IO_CON0 DPDIE DMDIE DPPD DMPD, no pull-ups), PHY on, SIE out of reset, VBUS valid, CID 0
 * (A-device). The caller waits >= 20 ms after fm1_usb_reset and again after this before touching the SIE, then
 * writes DEVCTL = 3 (session + host request). Nothing here drives VBUS: the port needs power from outside. */
FM1_INLINE void fm1_usb_host_attach(void *ep0)
{
    uint32_t n;
    FM1_CLK_CON1 &= ~3u;                                /* USB clock = PLL48M */
    FM1_USB_EP0_ADR = (uint32_t)(uintptr_t)ep0;
    for (n = 1; n <= 3u; n++)
        FM1_USB_EP_RADR(n) = (uint32_t)(uintptr_t)ep0;
    FM1_USB_EP4_RADR = (uint32_t)(uintptr_t)ep0;
    FM1_USB_CON0 = 0;
    FM1_USB_CON1 = 0;
    FM1_USB_IO_CON0 = 0;
    FM1_USB_IO_CON0 |= (1u << 10) | (1u << 9) | (1u << 5) | (1u << 4);
    FM1_USB_IO_CON0 &= ~((1u << 11) | (1u << 8));
    FM1_USB_CON0 |= 0x25u;                              /* PHY_ON | USB_NRST | VBUS */
}

/* D+ / D- single-ended levels (CON0 bit 17 / 16): both 0 = nothing attached, else a device pulls one up */
FM1_INLINE uint32_t fm1_usb_line(void) { return (FM1_USB_CON0 >> 16) & 3u; }

/* SIE access through CON1: only while CON0.bit2 (USB_NRST) is set */
FM1_INLINE uint32_t fm1_usb_sie_on(void) { return FM1_USB_CON0 & 4u; }
FM1_INLINE void fm1_usb_sie_wr_start(uint32_t r, uint32_t v)
{
    FM1_USB_CON1 = ((r << 8) & 0xFFFF00u) | (v & 0xFFu);
    __asm__ volatile("csync" ::: "memory");
}
FM1_INLINE void fm1_usb_sie_rd_start(uint32_t r)
{
    FM1_USB_CON1 = ((r << 8) & 0xFFBF00u) | 0x4000u;
    __asm__ volatile("csync" ::: "memory");
}
FM1_INLINE uint32_t fm1_usb_sie_done(void) { return FM1_USB_CON1 & 0x8000u; }
FM1_INLINE uint32_t fm1_usb_sie_data(void) { return FM1_USB_CON1 & 0xFFu; }

FM1_INLINE void fm1_usb_ep0_buf(void *p) { FM1_USB_EP0_ADR = (uint32_t)(uintptr_t)p; }
FM1_INLINE void fm1_usb_ep_txbuf(uint32_t ep, void *p) { FM1_USB_EP_TADR(ep) = (uint32_t)(uintptr_t)p; }
FM1_INLINE void fm1_usb_ep_rxbuf(uint32_t ep, void *p) { FM1_USB_EP_RADR(ep) = (uint32_t)(uintptr_t)p; }
FM1_INLINE void fm1_usb_ep0_send(void *p, uint32_t n)
{
    __asm__ volatile("csync" ::: "memory");             /* the buffer is written before the DMA starts */
    FM1_USB_EP0_ADR = (uint32_t)(uintptr_t)p;
    FM1_USB_EP_CNT(0) = n;
}
FM1_INLINE void fm1_usb_ep_send(uint32_t ep, void *p, uint32_t n)
{
    __asm__ volatile("csync" ::: "memory");
    FM1_USB_EP_TADR(ep) = (uint32_t)(uintptr_t)p;
    FM1_USB_EP_CNT(ep) = n;
}
/* EP4 IN (the USB audio stream, isochronous): its DMA address and count have their own
 * registers (SDK usb_set_dma_taddr / usb_write_ep_cnt, id 0, ep 4) */
FM1_INLINE void fm1_usb_ep4_txbuf(void *p) { FM1_USB_EP4_TADR = (uint32_t)(uintptr_t)p; }
/* EP4 OUT (the USB audio output, isochronous): its DMA address (SDK usb_set_dma_raddr, ep 4) */
FM1_INLINE void fm1_usb_ep4_rxbuf(void *p) { FM1_USB_EP4_RADR = (uint32_t)(uintptr_t)p; }
FM1_INLINE void fm1_usb_ep4_send(void *p, uint32_t n)
{
    __asm__ volatile("csync" ::: "memory");
    FM1_USB_EP4_TADR = (uint32_t)(uintptr_t)p;
    FM1_USB_EP4_CNT = n;
    __asm__ volatile("csync" ::: "memory");
}
FM1_INLINE void fm1_usb_rx_sync(void) { __asm__ volatile("ssync" ::: "memory"); }

FM1_INLINE void fm1_usb_ep_enable(uint32_t eps) { FM1_USB_CON0 &= ~(eps << 19); }

FM1_INLINE uint32_t fm1_usb_sof_take(void)
{
    if (!(FM1_USB_CON0 & (1u << 13)))
        return 0;
    FM1_USB_CON0 |= 1u << 12;
    return 1;
}

