/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Kerem Kilic (Ellic Studio)
 * Copyright (C) 2026 Adrien Tibi (Recursive Field Instruments)
 * Ported from Melodee; source revisions and MPL permission: see NOTICE. */
/* USB MIDI host on USB0 (FELUCCA_USB_HOST), included by usb.c after the SIE helpers and ep1_take.
 *
 * The port is either the computer-facing device (usb.c) or, when usb_host_switch(1) is called, the host of a class
 * compliant USB-MIDI controller, alone or behind a hub. The initial state is always device mode, so
 * the update paths always work. Switching happens in the main loop (usb_host_task); usb.up is 0 while the port is a host.
 *
 *   main loop (usb_host_task)   waits for a device, resets the bus, and enumerates it with blocking EP0 transfers
 *                         (hub: powers the ports, resets those with something on them, and tries each device
 *                         until one has a USB-MIDI streaming interface). Failed direct probes wait for unplug;
 *                         idle hubs are polled for downstream connection changes. The ISR does nothing until uh.run.
 *   TIMER5 (uh_poll)      once uh.run is 1 the SIE is the ISR's alone: optional IN and OUT endpoints share host
 *                         EP1 in separate directions. IN is asked for a packet (ReqPkt), read when RxPktRdy, and its channel / clock events
 *                         go to the same ring as USB and TRS MIDI (source 1). A stall or a run of errors sets
 *                         uh.fault; the main loop then resets the bus and looks for a device again.
 *
 * Register sequences follow the AC79 SDK's USB0 host code (usb_h_sie_init, usb_h_chirp_and_reset, usb0_h_ep_read,
 * usb_ctlXfer): EP0 data moves through ep0buf / EP0_CNT as in the device driver, the target is FADDR (USB0 has no
 * per-endpoint function address), RXMAXP is 0xFF as everywhere in this firmware. Not driven: VBUS (the port
 * needs outside power, e.g. a powered hub), low-speed devices. OUT drains the existing MIDI output queue only
 * after the target ACKs; no SysEx/editor traffic is sent to attached devices.
 * Host OUT has SIE-model coverage; physical validation of this port is pending: see docs/USB_HOST.md. */
#if FELUCCA_USB_HOST
#include "usb_host_desc.h"

enum { S_DEVCTL = 15, S_TXTYPE = 24, S_TXINTERVAL = 25, S_RXTYPE = 26, S_RXINTERVAL = 27 };
enum { UH_MSG_NONE, UH_MSG_ON, UH_MSG_OFF, UH_MSG_MIDI, UH_MSG_NOMIDI, UH_MSG_LOW, UH_MSG_LOST };
#define UH_FIRST_ADDR 1u
#define UH_MAX_ERRORS 16u

static uint8_t uh_rx[64 + 4] __attribute__((aligned(4)));
static uint8_t uh_cfg[320];                                  /* a configuration, cut short if longer */
static struct {
    uint8_t want;                                       /* requested mode (main loop) */
    uint8_t on;                                         /* the port is a host */
    volatile uint8_t run;                               /* TIMER5 owns the active MIDI endpoints */
    volatile uint8_t fault;                             /* TIMER5 -> main loop: reset the bus and look again */
    uint8_t seen, next_addr, dev, tried;
    uint8_t hub_addr, hub_mps, hub_ports, hub_poll_port;
    uint8_t in_ep, out_mps, tx_count, tx_errors, line_idle;
    uint8_t msg;                                        /* one UH_MSG_* for the application */
    volatile uint8_t errors;
    uint32_t t_ms, retry_ms;
    uint32_t tx_ms, hub_poll_ms;
    volatile uint32_t pkts, events;
} uh;

/* Main-loop request only. usb_host_task performs the actual mode transition. */
static void usb_host_switch(uint32_t on) { if (!usb.detached) uh.want = on != 0; }
static uint32_t usb_host_active(void) { return uh.on; }
static uint32_t usb_host_connected(void) { return uh.run; }
static uint32_t usb_host_message(void)
{
    uint32_t msg = uh.msg;
    uh.msg = UH_MSG_NONE;
    return msg;
}

#if FELUCCA_USB_HOST_NAME
/* The connected device's product string (its iProduct, in the first language it lists), ASCII: other characters
 * become '?', control characters are left out, at most UH_NAME_MAX. Empty when nothing is connected, when the device
 * has no product string or when reading it failed (the connection does not depend on it). Main loop. */
#define UH_NAME_MAX 31u
static char uh_name[UH_NAME_MAX + 1u];
static const char *usb_host_name(void) { return uh.run ? uh_name : ""; }
#endif

/* ------------------------------------------------ main loop: control --- */
static void uh_wait(uint32_t ms)                        /* main loop only */
{
    uint32_t t = fm1_ms;
    while (fm1_ms - t < ms)
        fm1_wdt_feed();
}

/* CSR0 (host) until want_set bits are all set and want_clr are all clear: >= 0 the CSR0, < 0 a stall / error / timeout */
static int uh_csr0(uint32_t want_set, uint32_t want_clr)
{
    uint32_t t = fm1_ms, v;
    for (;;) {
        v = sie_rd(S_CSR0);
        if (v & 0x04u) {                                /* RxStall */
            sie_wr(S_CSR0, 0);
            return -2;
        }
        if (v & 0x10u) {                                /* Error: no answer */
            sie_wr(S_CSR0, 0);
            return -1;
        }
        if ((v & want_set) == want_set && !(v & want_clr))
            return (int)v;
        if (fm1_ms - t > 500u)
            return -3;
        fm1_wdt_feed();
    }
}

/* One control transfer to `addr`: SETUP, the IN data stage if any, the status stage. Bytes read, or < 0.
 * Only requests without an OUT data stage (every one used here). */
static int uh_ctl(uint8_t addr, uint8_t rt, uint8_t rq, uint16_t val, uint16_t idx, uint16_t len, uint8_t *out,
                  uint8_t mps)
{
    uint32_t got = 0, n, i;
    int r;
    sie_wr(S_FADDR, addr);
    sie_wr(S_INDEX, 0);
    ep0buf[0] = rt;
    ep0buf[1] = rq;
    ep0buf[2] = (uint8_t)val;
    ep0buf[3] = (uint8_t)(val >> 8);
    ep0buf[4] = (uint8_t)idx;
    ep0buf[5] = (uint8_t)(idx >> 8);
    ep0buf[6] = (uint8_t)len;
    ep0buf[7] = (uint8_t)(len >> 8);
    fm1_usb_ep0_send(ep0buf, 8);
    sie_wr(S_CSR0, 0x0Au);                              /* SetupPkt | TxPktRdy */
    r = uh_csr0(0, 0x02u);
    if (r < 0)
        return r;
    if (len && (rt & 0x80u)) {
        while (got < len) {
            sie_wr(S_CSR0, 0x20u);                      /* ReqPkt */
            r = uh_csr0(0x01u, 0);
            if (r < 0)
                return r;
            n = sie_rd(S_COUNT0);
            if (n > 64u)
                n = 64u;
            fm1_usb_rx_sync();
            for (i = 0; i < n && got + i < len; i++)
                out[got + i] = ep0buf[i];
            sie_wr(S_CSR0, 0);                          /* RxPktRdy done */
            got += n;
            if (n < mps)
                break;
        }
        if (got > len)
            got = len;
        sie_wr(S_CSR0, 0x42u);                          /* status: StatusPkt | TxPktRdy (zero-length OUT) */
        r = uh_csr0(0, 0x02u);
    } else {
        sie_wr(S_CSR0, 0x60u);                          /* status: StatusPkt | ReqPkt (zero-length IN) */
        r = uh_csr0(0x01u, 0);
        if (r >= 0)
            sie_wr(S_CSR0, 0);
    }
    return r < 0 ? r : (int)got;
}

#if FELUCCA_USB_HOST_NAME
static void uh_name_read(uint8_t addr, uint8_t mps)     /* main loop, after SET_CONFIGURATION */
{
    uint8_t b[2u + 2u * UH_NAME_MAX], dd[18];
    uint16_t lang = 0x0409u;
    uint32_t i, n = 0;
    int r;
    uh_name[0] = 0;
    if (uh_ctl(addr, 0x80, 6, 0x0100, 0, 18, dd, mps) < 16 || !dd[15])   /* the device descriptor: iProduct */
        return;
    if (uh_ctl(addr, 0x80, 6, 0x0300, 0, 4, b, mps) >= 4 && b[1] == 3u)   /* string 0: the languages, the first */
        lang = (uint16_t)(b[2] | b[3] << 8);
    r = uh_ctl(addr, 0x80, 6, (uint16_t)(0x0300u | dd[15]), lang, (uint16_t)sizeof b, b, mps);
    if (r < 2 || b[1] != 3u)
        return;
    if ((uint32_t)r > b[0])
        r = b[0];
    for (i = 2; i + 1u < (uint32_t)r && n < UH_NAME_MAX; i += 2) {   /* UTF-16LE */
        uint32_t c = (uint32_t)(b[i] | b[i + 1u] << 8);
        if (c >= 0x20u)
            uh_name[n++] = c < 0x7Fu ? (char)c : '?';
    }
    while (n && uh_name[n - 1u] == ' ')
        n--;
    uh_name[n] = 0;
}
#endif

/* ---------------------------------------------------- enumeration --- */
static int uh_hub_probe(uint8_t addr, uint8_t mps, uint8_t cfgval, uh_midi_t *m);

/* The device at address 0 (just reset): give it an address, read its configuration, and if it has a USB-MIDI
 * streaming interface select it. 1 = found, 0 = no (including a hub below depth 0 and a device that fails). */
static int uh_probe(uint8_t depth, uh_midi_t *m)
{
    uint8_t d8[8], mps, cls, addr = uh.next_addr++;
    uint32_t total;
    int r;
    r = uh_ctl(0, 0x80, 6, 0x0100, 0, 8, d8, 8);        /* GET_DESCRIPTOR(device), first 8 bytes */
    if (r < 8)
        return 0;
    mps = d8[7] == 16u || d8[7] == 32u || d8[7] == 64u ? d8[7] : 8u;
    cls = d8[4];
    if (uh_ctl(0, 0x00, 5, addr, 0, 0, 0, mps) < 0)     /* SET_ADDRESS */
        return 0;
    uh_wait(10);                                        /* the device settles to its new address */
    r = uh_ctl(addr, 0x80, 6, 0x0200, 0, 9, uh_cfg, mps);
    if (r < 9)
        return 0;
    total = (uint32_t)(uh_cfg[2] | uh_cfg[3] << 8);
    if (total > sizeof uh_cfg)
        total = sizeof uh_cfg;
    if (total > 9u) {
        r = uh_ctl(addr, 0x80, 6, 0x0200, 0, (uint16_t)total, uh_cfg, mps);
        if (r < 9)
            return 0;
        total = (uint32_t)r;
    }
    if (cls == 9u)                                      /* a hub */
        return depth == 0u ? uh_hub_probe(addr, mps, uh_cfg[5], m) : 0;
    if (!uh_parse_midi(uh_cfg, total, m))
        return 0;
    if (uh_ctl(addr, 0x00, 9, m->cfg, 0, 0, 0, mps) < 0)   /* SET_CONFIGURATION */
        return 0;
    if (m->alt && uh_ctl(addr, 0x01, 11, m->alt, m->iface, 0, 0, mps) < 0)   /* SET_INTERFACE */
        return 0;
#if FELUCCA_USB_HOST_NAME
    uh_name_read(addr, mps);
#endif
    uh.dev = addr;
    return 1;
}

/* Probe only this downstream port; keep the hub and the other devices configured. Each port reuses its
 * address on reconnect, so repeated hot-plugs cannot exhaust the USB address space. */
static int uh_hub_port_probe(uint8_t p, uint32_t st, uh_midi_t *m)
{
    uint8_t b[4], addr = uh.hub_addr, mps = uh.hub_mps;
    uint32_t t;
    if (!(st & 0x0001u) || (st & 0x0200u))              /* nothing there, or low speed */
        return 0;
    if (uh_ctl(addr, 0x23, 3, 4, p, 0, 0, mps) < 0)    /* SET_FEATURE(PORT_RESET) */
        return 0;
    t = fm1_ms;
    for (;;) {
        if (uh_ctl(addr, 0xA3, 0, 0, p, 4, b, mps) >= 4 && (b[2] & 0x10u))   /* C_PORT_RESET */
            break;
        if (fm1_ms - t > 500u)
            return 0;
        uh_wait(10);
    }
    uh_ctl(addr, 0x23, 1, 20, p, 0, 0, mps);            /* CLEAR_FEATURE(C_PORT_RESET) */
    if (uh_ctl(addr, 0xA3, 0, 0, p, 4, b, mps) < 4 || !(b[0] & 0x02u))   /* enabled? */
        return 0;
    uh_wait(20);                                        /* reset recovery */
    uh.next_addr = (uint8_t)(UH_FIRST_ADDR + p);
    return uh_probe(1, m);
}

/* Read and acknowledge connection changes, including disconnects and unsupported devices. An unresponsive
 * hub is left alone until root unplug/replug, rather than repeating a blocking control timeout forever. */
static int uh_hub_status(uint8_t p, uint8_t *b)
{
    if (uh_ctl(uh.hub_addr, 0xA3, 0, 0, p, 4, b, uh.hub_mps) < 4 ||
        ((b[2] & 1u) && uh_ctl(uh.hub_addr, 0x23, 1, 16, p, 0, 0, uh.hub_mps) < 0)) {
        uh.hub_addr = 0;
        return 0;
    }
    return 1;
}

/* Configure and power the root hub once. After the initial scan, idle polling uses connection-change bits. */
static int uh_hub_probe(uint8_t addr, uint8_t mps, uint8_t cfgval, uh_midi_t *m)
{
    uint8_t b[16], ports, p;                            /* (the hub descriptor is 9 bytes with <= 7 ports) */
    uint32_t good;
    if (uh_ctl(addr, 0x00, 9, cfgval, 0, 0, 0, mps) < 0)
        return 0;
    if (uh_ctl(addr, 0xA0, 6, 0x2900, 0, 9, b, mps) < 7)   /* hub descriptor */
        return 0;
    ports = b[2] > 7u ? 7u : b[2];
    good = (uint32_t)b[5] * 2u;                         /* bPwrOn2PwrGood, in 2 ms */
    for (p = 1; p <= ports; p++)
        uh_ctl(addr, 0x23, 3, 8, p, 0, 0, mps);         /* SET_FEATURE(PORT_POWER) */
    uh_wait((good < 100u ? 100u : good) + 100u);        /* power good, then the devices announce themselves */
    uh.hub_addr = addr;
    uh.hub_mps = mps;
    uh.hub_ports = ports;
    uh.hub_poll_port = 1;
    uh.hub_poll_ms = fm1_ms;
    for (p = 1; p <= ports; p++) {
        if (!uh_hub_status(p, b))
            return 0;
        if (uh_hub_port_probe(p, (uint32_t)(b[0] | b[1] << 8), m))
            return 1;
    }
    return 0;
}

/* Host EP1 has independent RX/TX DMA slots. Both target endpoints belong to this device and alternate setting. */
static void uh_start_ep(const uh_midi_t *m)
{
    sie_wr(S_FADDR, uh.dev);
    sie_wr(S_INDEX, 1);
    uh.in_ep = m->in_ep;
    uh.out_mps = (uint8_t)m->out_mps;
    uh.tx_count = uh.tx_errors = 0;
    uh.line_idle = 0;
    if (m->in_ep) {
        fm1_usb_ep_rxbuf(1, uh_rx);
        sie_wr(S_RXMAXP, 0xFF);
        sie_wr(S_RXCSR1, 0x90);                         /* clear data toggle, flush */
        sie_wr(S_RXCSR2, 0);
        sie_wr(S_RXTYPE, (uint32_t)(m->in_type << 4 | m->in_ep));
        sie_wr(S_RXINTERVAL, m->in_type == 3u ? m->in_interval : 0u);
        sie_wr(S_RXCSR1, 0x20u);                        /* ReqPkt */
    }
    if (m->out_ep) {
        fm1_usb_ep_txbuf(1, ep1tx);
        sie_wr(S_TXMAXP, 0xFF);                         /* AC79 USB0's DMA maximum, as in the device driver */
        sie_wr(S_TXCSR1, 0x48);                         /* ClrDataTog | FlushFIFO, only at endpoint start */
        sie_wr(S_TXCSR2, 0x20);                         /* MODE: TX half of a bidirectional endpoint */
        sie_wr(S_TXTYPE, (uint32_t)(m->out_type << 4 | m->out_ep));
        sie_wr(S_TXINTERVAL, m->out_type == 3u ? m->out_interval : 0u);
    }
    fm1_usb_ep_enable(1u << 1);
    uh.errors = 0;
    uh.fault = 0;
    midi_links++;
    RING_PUBLISH();
    uh.run = 1;
}

/* Stop admitting output before discarding queued notes. The app consumes midi_usb_lost to release USB
 * input owners and arrange output cleanup, including a packet with an uncertain ACK. */
static void uh_session_end(void)
{
    uh.run = 0;
    uh.out_mps = 0;
    uh.tx_count = 0;
    mo_r = mo_w;
    RING_PUBLISH();
    midi_usb_lost = 1;
}

/* the controller's port as a host with nothing attached yet */
static void uh_host_up(void)
{
    usb.timeouts = 0;
    fm1_usb_reset();
    uh_wait(25);
    fm1_usb_host_attach(ep0buf);
    uh_wait(25);
    sie_wr(S_INTRUSBE, 0);
    sie_wr(S_INTRTX1E, 0);
    sie_wr(S_INTRTX2E, 0);
    sie_wr(S_INTRRX1E, 0);
    sie_wr(S_INTRRX2E, 0);
    fm1_usb_ep_enable(0x1Fu);
    sie_wr(S_FADDR, 0);
    sie_wr(S_DEVCTL, 0x03u);                            /* session + host request */
    uh.seen = 0;
    uh.line_idle = 0;
    uh.hub_addr = 0;
}

/* a device is on the line: reset the bus and find the MIDI endpoint */
static void uh_connect(void)
{
    uh_midi_t m;
    if (sie_rd(S_DEVCTL) & 0x20u) {                     /* low speed (FSDev is bit 6, LSDev bit 5) */
        if (!uh.tried)
            uh.msg = UH_MSG_LOW;                        /* said once per attach, as NO MIDI is */
        uh.tried = 1;
        return;
    }
    sie_wr(S_POWER, 0x08u);                             /* bus reset */
    uh_wait(30);
    sie_wr(S_POWER, 0);
    uh_wait(30);
    uh.next_addr = UH_FIRST_ADDR;
    if (uh_probe(0, &m)) {
        uh_start_ep(&m);
        uh.msg = UH_MSG_MIDI;
        uh.tried = 0;
    } else {
        if (!uh.tried)
            uh.msg = UH_MSG_NOMIDI;                     /* said once per attach */
        uh.tried = 1;
    }
}

/* Main loop. usb_host_switch requests the mode; this finds and keeps a controller. */
static void usb_host_task(uint32_t now)
{
    if (usb.detached)
        return;
    if (uh.want != uh.on) {
        usb.up = 0;                                     /* TIMER5 leaves the SIE to this context */
        RING_PUBLISH();
        usb.config = 0;
        usb.suspended = 0;
        uh_session_end();
        uh.fault = 0;
        uh.tried = 0;
        if (uh.want) {
#if FELUCCA_UAC
            uac_stream(0);
#endif
#if FELUCCA_UAC_OUT
            uo_stream(0);
#endif
#if FELUCCA_CDC
            cdc.dtr = cdc.e0_rx = cdc.rx_pend = 0;
#endif
#if FELUCCA_OTA
            so_r = so_w;
            sx_collect = sx_busy = 0;
            sx_taken = sx_made;                         /* (the frames waiting: dropped) */
#endif
#if FELUCCA_MIRROR
            mr_r = mr_w;
            tx_mid = 0;
#endif
            usb.sx_on = 0;
            fm1_usb_off();
            uh.on = 1;
            RING_PUBLISH();
            uh_host_up();
            uh.retry_ms = now;
            uh.msg = UH_MSG_ON;
        } else {
            uh.on = 0;
            RING_PUBLISH();
            fm1_usb_off();
            usb_retry_ms = now - 1000u;                 /* usb_retry makes the port a device again at once */
            uh.msg = UH_MSG_OFF;
        }
        return;
    }
    if (!uh.on)
        return;
    if (uh.fault) {                                     /* stall, or the controller stopped answering (TIMER5 cleared run) */
        uh_session_end();
        uh.fault = 0;
        uh_host_up();
        uh.retry_ms = now + 500u;
        uh.msg = UH_MSG_LOST;
        return;
    }
    if (uh.run)
        return;
    if ((int32_t)(now - uh.t_ms) < 20 || (int32_t)(now - uh.retry_ms) < 0)
        return;
    uh.t_ms = now;
    if (!fm1_usb_line()) {
        uh.seen = 0;
        if (uh.line_idle < 5u) uh.line_idle++;
        if (uh.line_idle >= 5u) {                       /* debounce root disconnect while idle too */
            uh.tried = 0;
            uh.hub_addr = 0;
        }
        return;
    }
    uh.line_idle = 0;
    if (uh.tried) {
        if (uh.hub_addr && uh.hub_ports && (uint32_t)(now - uh.hub_poll_ms) >= 100u) {
            uint8_t b[4], p = uh.hub_poll_port;
            uh_midi_t m;
            uh.hub_poll_ms = now;
            uh.hub_poll_port = p == uh.hub_ports ? 1u : (uint8_t)(p + 1u);
            if (uh_hub_status(p, b) && (b[2] & 1u) && (b[0] & 1u) && !(b[1] & 2u)) {
                uh_wait(100);                          /* newly attached device settles before port reset */
                if (uh_hub_status(p, b) && uh_hub_port_probe(p, (uint32_t)(b[0] | b[1] << 8), &m)) {
                    uh_start_ep(&m);
                    uh.msg = UH_MSG_MIDI;
                    uh.tried = 0;
                }
            }
        }
        return;                                        /* direct failures wait for root unplug/replug */
    }
    if (uh.seen < 5u) {                                 /* 100 ms of a steady line before the bus reset */
        uh.seen++;
        return;
    }
    uh.seen = 0;
    uh_connect();
}

/* ------------------------------------------------------ TIMER5 ISR --- */
static void uh_fail(void)
{
    uh.run = 0;
    uh.fault = 1;
}

/* Retain ring slots and the DMA buffer until ACK. A NAK or transient error retries the same data toggle;
 * a stall, repeated errors or 500 ms without completion hands recovery to the main loop. Never wait here. */
static void uh_tx_poll(void)
{
    uint32_t csr = sie_rd(S_TXCSR1), n = 0;
    if (uh.tx_count) {
        if ((csr & 0x20u) || fm1_ms - uh.tx_ms >= 500u) {
            uh_fail();
            return;
        }
        if (csr & 0x84u) {                              /* Error / NAK timeout */
            if ((csr & 4u) && ++uh.tx_errors >= UH_MAX_ERRORS) {
                uh_fail();
                return;
            }
            sie_wr(S_TXCSR1, 0x01u);                    /* retry retained FIFO, preserving data toggle */
            return;
        }
        if (csr & 0x03u) return;                        /* TxPktRdy / FIFONotEmpty: no ACK yet */
        RING_PUBLISH();
        mo_r += uh.tx_count;
        uh.tx_count = uh.tx_errors = 0;
    }
    while (mo_r + n / 4u != mo_w && n + 4u <= uh.out_mps) {
        uint32_t p = midi_out_q[(mo_r + n / 4u) % MQ];
        ep1tx[n] = (uint8_t)p;
        ep1tx[n + 1] = (uint8_t)(p >> 8);
        ep1tx[n + 2] = (uint8_t)(p >> 16);
        ep1tx[n + 3] = (uint8_t)(p >> 24);
        n += 4u;
    }
    if (!n) return;
    uh.tx_count = (uint8_t)(n / 4u);
    uh.tx_ms = fm1_ms;
    fm1_usb_ep_send(1, ep1tx, n);
    sie_wr(S_TXCSR1, 0x01u);
}

static void uh_poll(void)
{
    uint32_t csr, n, i;
    if (!fm1_usb_line()) {
        /* EOP also drives SE0 briefly. Require 8 ms of idle samples, not one sample during a packet. */
        if (++uh.line_idle >= 16u) uh_fail();
        return;
    }
    uh.line_idle = 0;
    sie_wr(S_INDEX, 1);
    if (uh.out_mps) uh_tx_poll();
    if (!uh.run || !uh.in_ep) return;
    csr = sie_rd(S_RXCSR1);
    if (csr & 0x40u) {                                  /* RxStall: the endpoint is gone */
        uh_fail();
        return;
    }
    if (csr & 0x0Cu) {                                  /* Error / DataError: no usable answer */
        if (++uh.errors >= UH_MAX_ERRORS) {
            uh_fail();
            return;
        }
        sie_wr(S_RXCSR1, 0x20u);                        /* the flags clear (written 0) and the request goes again; the
                                                         * data toggle stays: it is reset when the endpoint starts only */
        return;
    }
    if (csr & 0x01u) {                                  /* a packet is in uh_rx */
        n = sie_rd(S_RXCOUNT1) | (sie_rd(S_RXCOUNT2) << 8);
        if (n > 64u)
            n = 64u;
        fm1_usb_rx_sync();
#ifndef FELUCCA_LOADER
        if (MQ - (mi_w - mi_r) < EP1_ROOM)
            return;                                     /* ring too full: the packet stays, retried next poll */
#endif
        for (i = 0; i + 3u < n; i += 4u) {
            uint32_t p = uh_midi_ok((uint32_t)uh_rx[i] | (uint32_t)uh_rx[i + 1] << 8 |
                                    (uint32_t)uh_rx[i + 2] << 16 | (uint32_t)uh_rx[i + 3] << 24);
            if (p) {
                midi_enqueue(p, 1u);
                uh.events++;
            }
        }
        uh.pkts++;
        uh.errors = 0;
        sie_wr(S_RXCSR1, 0x10u);                        /* release the packet */
        sie_wr(S_RXCSR1, 0x20u);                        /* and ask for the next */
        return;
    }
    if (!(csr & 0x20u))                                 /* nothing pending: ask */
        sie_wr(S_RXCSR1, 0x20u);
}
#endif /* FELUCCA_USB_HOST */

text.fm1-base/bsp/chip/usb_host_desc.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Kerem Kilic (Ellic Studio)
 * Copyright (C) 2026 Adrien Tibi (Recursive Field Instruments)
 * Ported from Melodee; source revisions and MPL permission: see NOTICE. */
/* USB host: what the host reads from an attached device, with no register access (usb_host.c uses it; the host
 * tests include it alone).
 *   uh_parse_midi   a configuration descriptor -> the first MIDI 1.0 streaming alternate setting with usable
 *                   IN and/or OUT endpoints (an output-only synth is usable too)
 *   uh_midi_ok      one USB-MIDI event packet -> 1 when it is a channel message or a clock / transport byte */
#pragma once
#include <stdint.h>

typedef struct {
    uint8_t found;               /* a usable endpoint of a MIDI streaming interface was found */
    uint8_t cfg;                 /* bConfigurationValue */
    uint8_t iface, alt;          /* its interface and alternate setting */
    uint8_t in_ep;               /* endpoint number (without the direction bit) */
    uint8_t in_type;             /* 2 bulk, 3 interrupt */
    uint8_t in_interval;         /* bInterval (interrupt only) */
    uint16_t in_mps;
    uint8_t out_ep;              /* the OUT endpoint of the same interface, 0 = none */
    uint8_t out_type, out_interval;
    uint16_t out_mps;
} uh_midi_t;

/* d / len: the configuration descriptor as read (possibly cut short: a descriptor that does not fit is ignored) */
static int uh_parse_midi(const uint8_t *d, uint32_t len, uh_midi_t *m)
{
    uint32_t i = 0;
    uint8_t cfg = 0, in_midi = 0;
    *m = (uh_midi_t){0};
    while (i + 2u <= len) {
        uint32_t l = d[i];
        if (l < 2u || i + l > len)
            break;
        if (d[i + 1] == 2u && l >= 9u) {
            cfg = d[i + 5];
        } else if (d[i + 1] == 4u && l >= 9u) {
            if (m->found) break;                        /* never combine interfaces or alternate settings */
            m->cfg = cfg;
            m->iface = d[i + 2];
            m->alt = d[i + 3];
            in_midi = d[i + 5] == 1u && d[i + 6] == 3u && d[i + 7] == 0u;
        } else if (d[i + 1] == 5u && l >= 7u && in_midi) {
            uint8_t ea = d[i + 2], type = d[i + 3] & 3u;
            uint16_t mps = (uint16_t)(d[i + 4] | d[i + 5] << 8);
            /* Full-speed USB-MIDI 1.0 events are four bytes. The buffers hold at most 64 bytes. */
            if ((ea & 15u) && !(ea & 0x70u) && mps >= 4u && mps <= 64u &&
                ((type == 2u && (mps == 8u || mps == 16u || mps == 32u || mps == 64u)) ||
                 (type == 3u && d[i + 6]))) {
                if ((ea & 0x80u) && !m->in_ep) {
                    m->found = 1;
                    m->in_ep = ea & 0x0Fu;
                    m->in_type = type;
                    m->in_interval = d[i + 6];
                    m->in_mps = mps;
                } else if (!(ea & 0x80u) && !m->out_ep) {
                    m->found = 1;
                    m->out_ep = ea & 0x0Fu;
                    m->out_type = type;
                    m->out_interval = d[i + 6];
                    m->out_mps = mps & ~3u;          /* send whole event packets only */
                }
            }
        }
        i += l;
    }
    return m->found;
}

/* A USB-MIDI event packet: cable / CIN, then the MIDI bytes. Channel messages (CIN 8..E whose status matches)
 * and the one-byte clock, start, continue and stop are passed on; SysEx and everything else is not: a
 * controller has no business with the SysEx commands (update, editor) that usb.c's own parser answers. The
 * cable number is dropped. Returns the packet to enqueue, or 0. */
static uint32_t uh_midi_ok(uint32_t pkt)
{
    uint32_t cin = pkt & 15u, st = (pkt >> 8) & 0xFFu;
    pkt &= ~0xF0u;
    if (cin == 0xFu)
        return st == 0xF8u || st == 0xFAu || st == 0xFBu || st == 0xFCu ? pkt : 0u;
    if (cin >= 8u && cin <= 0xEu && (st >> 4) == cin && !((pkt >> 16) & 0x80u) &&
        ((cin == 0xCu || cin == 0xDu) || !(pkt & 0x80000000u)))
        return pkt;
    return 0u;
}

text.fm1-base/device/announce.c:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal */
/* Announce: what the screen says, for a screen reader on the computer (fm1-reader: a page that speaks it,
 * or hands it to the computer's own screen reader). Shared by the FM-1 firmwares, one copy: fm1-base's
 * device/announce.c (tests/announce_test.c); fm1-reader's tools/sync_announce.sh copies it into the firmwares not on
 * fm1-base. Change it here, not in a copy. The app says what changed and when; this keeps the protocol.
 *
 * The firmware is in charge of the words, without spending flash on them: it sends the screen's own text,
 * and its HELLO gives the link to its words file (its words.tsv, built by gen_words.py into ANN_WORDS_URL),
 * which the reader fetches to say "BD TUNE 37" as "bass drum tune 37". The link names the exact words this
 * build was made with, so an old device and a new one each get their own.
 *
 * SysEx over USB-MIDI, F0 7D 53 52 cmd args.. F7 ("SR"; fm1-reader/PROTOCOL.md):
 *   reader -> device   1 HELLO ver      listen (again every ~2 s: a reader not heard for 5 s is gone)
 *                      2 BYE            stop
 *                      3 WHERE          say everything on the screen now
 *   device -> reader   1 HELLO ver, name, 0, words link   (the answer to each HELLO)
 *                      16 SAY flags, text  (7-bit ASCII to the F7; flags 1: cut off what is being said,
 *                                           2: a warning or an error: not cut off by what follows)
 * Nothing is built or sent while no reader listens: a DAW on the same port never sees a byte.
 *
 * The includer supplies:
 *   ann_wire_send(p, n)   one complete F0..F7 message to the host; 0 = sent, else not sent at all (no room)
 * and calls ann_frame() with each received SysEx (the bytes between F0 and F7) and ann_tick() from its main
 * loop. The app calls ann_on(), ann_say(), ann_later() and ann_where().
 * Options before the #include: ANN_NAME (the HELLO answer), ANN_WORDS_URL (gen_words.py's ann_words.h),
 * ANN_MAX (longest SAY; the SysEx send queue must hold ANN_MAX + 9 bytes, (ANN_MAX + 9) / 3 USB-MIDI
 * packets), ANN_DATA (a section for its RAM). */
#ifndef ANN_NAME
#define ANN_NAME "FM-1"
#endif
#ifndef ANN_WORDS_URL
#define ANN_WORDS_URL ""                      /* no words file: the reader says the screen's text as it is */
#endif
#ifndef ANN_DATA
#define ANN_DATA                              /* where its RAM goes (zeroed at start), e.g. a pool section */
#endif
#ifndef ANN_MAX
#define ANN_MAX 240u                          /* text in one SAY; longer is cut at a word */
#endif
#define ANN_VER 1u
#define ANN_H0 0x7Du
#define ANN_H1 0x53u
#define ANN_H2 0x52u
#define ANN_NOW 1u                            /* cut off what the reader is saying (a knob, a page) */
#define ANN_KEEP 2u                           /* a warning or an error: heard whole, not cut off by what follows */
#define ANN_GONE_MS 5000u
enum { ANN_HELLO = 1, ANN_BYE = 2, ANN_WHERE = 3, ANN_SAY = 16 };

static int ann_wire_send(const uint8_t *p, uint32_t n);

static struct {
    uint8_t on, where;
    uint32_t heard;                           /* the last HELLO */
    char later[ANN_MAX + 1];                  /* the newest of a run (a knob turning), said when it settles */
    uint8_t later_flags, later_set;
    uint32_t later_t, later_first, later_quiet;
} ann ANN_DATA;

static int ann_on(void) { return ann.on; }

/* a + b (b may be 0; a 0 byte between them for HELLO's name and link) */
static void ann_send(uint32_t cmd, uint32_t flags, const char *a, const char *b)
{
    char w[ANN_MAX + 2];
    uint8_t f[8 + ANN_MAX];
    uint32_t n = 0, k = 0, i, two = cmd == ANN_HELLO;
    for (; a; a = b, b = 0) {
        while (*a && k < ANN_MAX)
            w[k++] = *a++;
        if (*a) {                             /* too long: back to the last space */
            while (k && w[k - 1] != ' ')
                k--;
            while (k && w[k - 1] == ' ')
                k--;
            break;
        }
        if (two && b)
            w[k++] = 1;                       /* (the 0 between: put in as the frame is written) */
    }
    w[k] = 0;
    f[n++] = 0xF0;
    f[n++] = ANN_H0;
    f[n++] = ANN_H1;
    f[n++] = ANN_H2;
    f[n++] = (uint8_t)cmd;
    f[n++] = (uint8_t)(flags & 0x7Fu);
    for (i = 0; w[i]; i++)
        f[n++] = w[i] == 1 && two ? 0 : (uint8_t)w[i] & 0x7Fu;
    f[n++] = 0xF7;
    ann_wire_send(f, n);
}

/* say a + b (b may be 0) now, after anything still waiting in ann_later */
static void ann_say(const char *a, const char *b, uint32_t flags)
{
    if (!ann.on || !a || !*a)
        return;
    if (ann.later_set && !(flags & ANN_NOW))  /* in order: what was waiting first */
        ann_send(ANN_SAY, ann.later_flags, ann.later, 0);
    ann.later_set = 0;
    ann_send(ANN_SAY, flags, a, b);
}

/* say s once it has stayed the newest for quiet_ms (each call replaces what waits; a run that keeps
 * changing is said at least every 4 x quiet_ms, so a long turn is heard as it goes) */
static void ann_later(const char *s, uint32_t flags, uint32_t quiet_ms, uint32_t now)
{
    uint32_t i;
    if (!ann.on)
        return;
    for (i = 0; s[i] && i < ANN_MAX; i++)
        ann.later[i] = s[i];
    ann.later[i] = 0;
    if (!ann.later_set)
        ann.later_first = now;
    ann.later_set = 1;
    ann.later_flags = (uint8_t)flags;
    ann.later_t = now;
    ann.later_quiet = quiet_ms;
}

/* the reader asked for the whole screen: 1 once */
static int ann_where(void)
{
    int w = ann.where;
    ann.where = 0;
    return w && ann.on;
}

static void ann_tick(uint32_t now)
{
    if (ann.on && now - ann.heard > ANN_GONE_MS) {
        ann.on = 0;
        ann.later_set = 0;
    }
    if (ann.later_set && (now - ann.later_t >= ann.later_quiet || now - ann.later_first >= 4u * ann.later_quiet)) {
        ann.later_set = 0;
        ann_send(ANN_SAY, ann.later_flags, ann.later, 0);
    }
}

/* a received SysEx (between F0 and F7): 1 if it was the reader's */
static int ann_frame(const uint8_t *p, uint32_t n, uint32_t now)
{
    if (n < 4u || p[0] != ANN_H0 || p[1] != ANN_H1 || p[2] != ANN_H2)
        return 0;
    switch (p[3]) {
    case ANN_HELLO:
        if (!ann.on)
            ann.where = 1;                    /* a new reader: what is on the screen first */
        ann.on = 1;
        ann.heard = now;
        ann_send(ANN_HELLO, ANN_VER, ANN_NAME, ANN_WORDS_URL);
        break;
    case ANN_BYE:
        ann.on = 0;
        ann.later_set = 0;
        break;
    case ANN_WHERE:
        ann.where = 1;
        break;
    default:
        break;
    }
    return 1;
}

text.fm1-base/device/audio_commit.c:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Henri David */
/* The half rendered aside (FM1B_AUDIO_ASIDE 1, main_fm1.c fm1_alnk0_irq): the render goes into a buffer of its own
 * and is copied into the DMA's free half only while that half is still free (no new half pending, the DMA on the same
 * side), with the interrupts off for the copy: a render that runs late leaves the half the DMA now plays as it was
 * (the audio of two halves before, whole) instead of writing into it while it plays, which tore the output mid-half (a
 * click at every late half). 2 KiB of RAM. Part of main_fm1.c (after abuf and HALF_WORDS); on its own for
 * tests/audio_commit_test.c, which gives it the DMA's state and the interrupt enable over a simulated chip. */
static int32_t aside[HALF_WORDS] __attribute__((aligned(4)));   /* (in SRAM: in the cache RAM the audio came out with
                                                     * tones at 1/4 and 1/8 of the rate, a cache line's pattern) */
static uint32_t audio_commit(uint32_t half)        /* 1 copied, 0 late (nothing written) */
{
    volatile int32_t *dst = &abuf[half * HALF_WORDS];
    uint32_t ie = fm1_icfg() & 0x200u, ok = 0, i;   /* (icfg bit 9: the global enable) */
    fm1_irq_off();
    if (fm1_audio_free_half() == half && !(fm1_audio_pending() & FM1_AUDIO_HALF)) {
        for (i = 0; i < HALF_WORDS; i++)
            dst[i] = aside[i];
        ok = fm1_audio_free_half() == half && !(fm1_audio_pending() & FM1_AUDIO_HALF);
    }
    if (ie)
        fm1_irq_on();
    return ok;
}

text.fm1-base/device/backup.c:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal */
/* Backup and restore over USB (fm1.toml backup = true: FM1B_BACKUP; tools/fm1_backup.py): the app's saved objects
 * (app.h APP_BACKUP_OBJS, in order; never the panel's calibration, which belongs to the unit), over the update's
 * SysEx framing (felucca-bsp ota.c: F0 pack7(00 59 cmd len24 body ~sum(body)) F7). (From Polly's.)
 *
 * The image (the backup file, little-endian):
 *   head  the app's magic (APP_BACKUP_MAGIC), u16 its version (APP_BACKUP_VERSION), u16 the count of objects,
 *         u32 flags (bit 0: taken while playing, changes not yet saved left out), u32 CRC-32 of the 12 bytes before
 *   the records, in APP_BACKUP_OBJS's order: u16 object id, u16 length, u32 CRC-32 of the payload, the payload
 *         (length 0: the object absent; a restore makes it absent)
 *   tail  u32 CRC-32 of everything before
 * (CRC-32: zlib's, as storage.c's st_crc32)
 *
 * Backup (cmd 0x42 from the host, body the app's magic): the device streams the image from its main loop, one frame
 * at a time (cmd 0x42, body: u32 offset + up to BU_CHUNK bytes; 161 wire bytes, 54 packets: it fits the SysEx TX
 * ring whole, so a frame never waits and the notes between frames go out as ever), then cmd 0x43 (u32 length, u32
 * CRC-32 of the whole image, u8 status, u8 flags). It plays on meanwhile. Stopped, what is not saved yet is saved
 * first (app_backup_flush); the app does not save until the stream ends (app_backup_hold). Each object is read from
 * the flash at its turn (one in RAM at a time).
 *
 * Restore (cmd 0x41, body: u32 the image's length, u32 its CRC-32): refused while playing (app_backup_playing: STOP
 * FIRST). Else, as an update does, the device pulls the image with read requests (ota_read; addresses are the image's
 * offsets) and
 *   1. checks the head, then each record: its id, its length, its payload's CRC-32, the image's CRC-32 (the tail and
 *      the host's), the length;
 *   2. stages each object as it comes into the copy storage.c would save it to next (the other of its A/B pair:
 *      erased, the payload programmed, read back and checked) WITHOUT its header: storage.c's header is the commit
 *      record of a copy, so a copy without one does not exist for st_load: the current set stays in charge;
 *   3. everything received and verified (a cut cable, a changed byte, a refused write: stops here, nothing changed):
 *      asks on the screen, RESTORE FROM USB? SEL yes / HOME no (60 s: no), stopped only;
 *   4. yes: commits. A journal record (RS_REC, in the update's staging area, unused but by an update) lists the
 *      headers to write; written and read back first, then the headers, then the record erased. A power loss after
 *      the record is valid is finished at the next boot (rs_boot: the headers written again, idempotent on NOR);
 *      before it, nothing happened. So the set changes whole or not at all.
 *   5. everything reloaded as at power-on (app_backup_restored); the result to the host: a read of RS_OK_ADDR, or
 *      RS_FAIL_ADDR | code. RS_ASK_ADDR is read just before the question (the host says so).
 * RAM: one object's buffer for a restore (bu_buf, 3840 B, the pool; or the app's, APP_BACKUP_BUF), the staging list;
 * the flash does the rest. A backup sends each object from its current copy on the flash, a chunk a frame (saving is
 * held meanwhile; a copy written over anyway fails its record's CRC on a restore, which then changes nothing).
 * An app with a pooled store (APP_STORE_POOL, storage.c) has no second copy of everything to stage into: 2. stages
 * nothing (every record still received and checked, so a wrong or cut backup changes nothing), and 4. erases the
 * pooled objects the backup holds (one it does not, OBJ_BLE's keys say, is kept), then fetches the image again and
 * saves each object (rs_rewrite; the backup is the user's own: a
 * cable pulled in between leaves a partly restored set, and restoring again finishes it). An older backup's
 * placeholders (APP_STORE_POOL_EMPTY) are not written.
 *
 * Hooks (the platform's, unity.c; the app's are app_backup_*, plat.h):
 *   rs_fetch(addr, p, n)  the image's bytes from the host (ota_read)                 0 = ok
 *   rs_note(addr)         a read of a reply address (ota_read of 8 bytes)           0 = the host answered
 *   rs_playing()          the app plays (app_backup_playing)
 *   rs_begin()            a backup to restore: the screen is ours (then rs_show(pct))
 *   rs_show(pct)          progress 0..100
 *   rs_ask()              the question on the screen: 1 yes, 0 no (HOME, 60 s, playing)
 *   rs_reload()           everything from the flash again (app_backup_restored)
 *   rs_rec_erase() rs_rec_prog(off, p, n) rs_rec_read(off, p, n)   the journal record's sector (RS_REC)
 *   bu_room()             a frame fits the TX ring now (it is empty): 1; not yet: 0; USB gone (unplugged,
 *                         suspended, not configured): -1, the backup given up
 *   bu_send(p, n)         one F0..F7 message to the host
 *   bu_flush()            stopped: what is unsaved saved (app_backup_flush)
 *   bu_hold(on)           the app's saving held (1) / free again (0) (app_backup_hold)
 * and storage.c's st_read / st_erase / st_prog, st_current, st_sector; ota.c's ota_now_ms for the stall limit
 * (BU_STALL_MS without a frame going out: the backup given up, the app's saving free again). */
#define RS_REQ 0x41u                                  /* the host's requests (ota.c framing) */
#define BU_REQ 0x42u
#define BU_END 0x43u
#define RS_OK_ADDR 0xC0000000u
#define RS_ASK_ADDR 0xC1000000u
#define RS_FAIL_ADDR 0xCF000000u
#define BU_MAGIC APP_BACKUP_MAGIC
#define BU_VERSION APP_BACKUP_VERSION
#ifndef APP_BACKUP_WHAT
#define APP_BACKUP_WHAT "replaces what is saved"
#endif
static const uint16_t bu_objs[] = APP_BACKUP_OBJS;
#define BU_NOBJ ((uint32_t)(sizeof bu_objs / sizeof bu_objs[0]))
#define BU_HEAD 16u
#define BU_REC 8u
#define BU_CHUNK 128u                                 /* a backup frame's data */
#define BU_STALL_MS 2000u                             /* no frame out for this long: the backup given up */
#define BU_MAXIMG (BU_HEAD + BU_NOBJ * (BU_REC + ST_PAYLOAD_MAX) + 4u)
#define RS_REC 0x000E1000u                            /* the journal record: the update's staging area's 2nd sector */
#define RS_REC_MAGIC 0x31534C50u                      /* "PLS1" */
enum { RS_E_SIZE = 1, RS_E_FETCH, RS_E_HEAD, RS_E_OBJ, RS_E_CRC, RS_E_TOTAL, RS_E_ERASE, RS_E_PROG, RS_E_VERIFY,
       RS_E_PLAYING, RS_E_NO, RS_E_COMMIT };

static int rs_fetch(uint32_t addr, uint8_t *dst, uint32_t n);
static int rs_note(uint32_t addr);
static int rs_playing(void);
static void rs_begin(void);
static void rs_show(uint32_t pct);
static int rs_ask(void);
static void rs_reload(void);
static int rs_rec_erase(void);
static int rs_rec_prog(uint32_t off, const void *src, uint32_t n);
static int rs_rec_read(uint32_t off, void *dst, uint32_t n);
static int bu_room(void);
static int bu_send(const uint8_t *p, uint32_t n);
static void bu_flush(void);
static void bu_hold(int on);

#ifdef APP_BACKUP_BUF                                /* the app's scratch buffer, lent to a restore (plat.h) */
extern uint8_t APP_BACKUP_BUF[];
#define bu_buf APP_BACKUP_BUF
#else
static uint8_t bu_buf[ST_PAYLOAD_MAX] __attribute__((aligned(4))) PLAT_POOL;   /* an object being restored */
#endif

static uint32_t bu_rd16(const uint8_t *p) { return (uint32_t)p[0] | (uint32_t)p[1] << 8; }
static uint32_t bu_rd32(const uint8_t *p) { return bu_rd16(p) | bu_rd16(p + 2) << 16; }
static void bu_wr16(uint8_t *p, uint32_t v) { p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8); }
static void bu_wr32(uint8_t *p, uint32_t v) { bu_wr16(p, v); bu_wr16(p + 2, v >> 16); }
static uint32_t bu_obj(uint32_t i) { return bu_objs[i]; }

static uint32_t bu_crc(uint32_t c, const uint8_t *p, uint32_t n)   /* zlib's crc32(c, p, n): chains */
{
    static const uint32_t T[16] = {
        0x00000000u, 0x1DB71064u, 0x3B6E20C8u, 0x26D930ACu, 0x76DC4190u, 0x6B6B51F4u, 0x4DB26158u, 0x5005713Cu,
        0xEDB88320u, 0xF00F9344u, 0xD6D6A3E8u, 0xCB61B38Cu, 0x9B64C2B0u, 0x86D3D2D4u, 0xA00AE278u, 0xBDBDF21Cu};
    c = ~c;
    while (n--) {
        c ^= *p++;
        c = (c >> 4) ^ T[c & 15u];
        c = (c >> 4) ^ T[c & 15u];
    }
    return ~c;
}

/* ------------------------------------------------------------- backup --- */
enum { BU_S_HEAD, BU_S_REC, BU_S_BODY, BU_S_TAIL, BU_S_END };
static struct {
    uint8_t on, state, i, flags;
    uint32_t off, crc;                                /* bytes sent, their CRC-32 */
    uint32_t last;                                    /* ota_now_ms() of the start / the last frame out */
    const uint8_t *p;                                 /* the segment being sent; 0: an object's body, from the flash */
    uint32_t n, len, at;                              /* (at: the body's next byte on the flash) */
    uint8_t seg[BU_HEAD];
} bu;

static uint8_t bu_msg[6 + 4 + BU_CHUNK + 1], bu_wire[2 + ((6 + 4 + BU_CHUNK + 1) * 8 + 6) / 7];

static int bu_frame(uint32_t cmd, const uint8_t *body, uint32_t n)   /* ota.c's framing, any body to BU_CHUNK + 4 */
{
    uint32_t i, s = 0, w;
    bu_msg[0] = 0;
    bu_msg[1] = 0x59;
    bu_msg[2] = (uint8_t)cmd;
    bu_msg[3] = (uint8_t)n;
    bu_msg[4] = (uint8_t)(n >> 8);
    bu_msg[5] = 0;
    for (i = 0; i < n; i++) {
        bu_msg[6 + i] = body[i];
        s += body[i];
    }
    bu_msg[6 + n] = (uint8_t)~s;
    bu_wire[0] = 0xF0;
    w = 1u + ota_pack7(bu_msg, 7u + n, bu_wire + 1);
    bu_wire[w++] = 0xF7;
    return bu_send(bu_wire, w);
}

/* the next segment of the image into bu.p / bu.n; 0 at the end */
static int bu_next(void)
{
    st_hdr_t h;
    switch (bu.state) {
    case BU_S_HEAD:
        bu_wr32(bu.seg, BU_MAGIC);
        bu_wr16(bu.seg + 4, BU_VERSION);
        bu_wr16(bu.seg + 6, BU_NOBJ);
        bu_wr32(bu.seg + 8, bu.flags);
        bu_wr32(bu.seg + 12, bu_crc(0, bu.seg, 12));
        bu.p = bu.seg;
        bu.n = BU_HEAD;
        bu.state = BU_S_REC;
        bu.i = 0;
        return 1;
    case BU_S_REC:
        if (bu.i == BU_NOBJ) {                        /* the tail: the CRC of everything before (all sent) */
            bu_wr32(bu.seg, bu.crc);
            bu.p = bu.seg;
            bu.n = 4;
            bu.state = BU_S_TAIL;
            return 1;
        }
        bu.len = 0;                                   /* the object as st_load sees it (none, or damaged: absent) */
        {
            int c = st_current(bu_obj(bu.i), &h);     /* (its payload checked against h.crc) */
            if (c >= 0 && h.len <= ST_PAYLOAD_MAX) {
                bu.len = h.len;
                bu.at = st_sector(bu_obj(bu.i), (uint32_t)c) + ST_PAYLOAD_OFF;
            } else
                h.crc = 0;
        }
        bu_wr16(bu.seg, bu_obj(bu.i));
        bu_wr16(bu.seg + 2, bu.len);
        bu_wr32(bu.seg + 4, h.crc);
        bu.p = bu.seg;
        bu.n = BU_REC;
        bu.state = BU_S_BODY;
        return 1;
    case BU_S_BODY:
        bu.p = 0;
        bu.n = bu.len;
        bu.state = BU_S_REC;
        bu.i++;
        return 1;
    default:
        bu.state = BU_S_END;
        return 0;
    }
}

/* the host asked for a backup (again: from the start) */
static void bu_start(int playing)
{
    if (!playing)
        bu_flush();
    bu.on = 1;
    bu.state = BU_S_HEAD;
    bu.flags = (uint8_t)(playing != 0);
    bu.off = bu.crc = 0;
    bu.n = 0;
    bu.last = ota_now_ms();
    bu_hold(1);
}

static void bu_stop(void)
{
    bu.on = 0;
    bu_hold(0);
}

/* the main loop: the next frame when the ring has room for it (one frame a pass) */
static void bu_step(void)
{
    uint8_t b[4 + BU_CHUNK];
    uint32_t n = 0;
    int r;
    if (!bu.on)
        return;
    r = bu_room();
    if (r <= 0) {                                     /* a cut cable: the ring never drains; USB gone: at once */
        if (r < 0 || ota_now_ms() - bu.last > BU_STALL_MS)
            bu_stop();
        return;
    }
    while (n < BU_CHUNK) {
        uint32_t k;
        if (!bu.n) {
            if (!bu_next())
                break;
            continue;
        }
        k = bu.n < BU_CHUNK - n ? bu.n : BU_CHUNK - n;
        if (!bu.p) {                                  /* an object's body, from its copy */
            if (st_read(bu.at, b + 4 + n, k)) {
                bu_stop();                            /* (the host sees no end: the backup failed) */
                return;
            }
            bu.at += k;
        } else {
            for (uint32_t j = 0; j < k; j++)
                b[4 + n + j] = bu.p[j];
            bu.p += k;
        }
        bu.crc = bu_crc(bu.crc, b + 4 + n, k);
        bu.n -= k;
        n += k;
    }
    if (n) {
        bu_wr32(b, bu.off);
        bu_frame(BU_REQ, b, 4u + n);                  /* (a frame lost on a cable cut: the host sees the gap) */
        bu.off += n;
        bu.last = ota_now_ms();
        return;
    }
    bu_wr32(b, bu.off);                               /* the end: the length and the whole image's CRC-32 */
    bu_wr32(b + 4, bu.crc);
    b[8] = 0;
    b[9] = bu.flags;
    bu_frame(BU_END, b, 10);
    bu_stop();
}

/* ------------------------------------------------------------ restore --- */
typedef struct {
    uint16_t obj, copy;
    uint32_t seq, len, crc;
} rs_ent_t;
static struct {
    uint32_t magic, n;
    rs_ent_t e[BU_NOBJ];
    uint32_t crc;
} rs_rec __attribute__((aligned(4)));
_Static_assert(sizeof rs_rec <= 4096u, "the journal record fits its sector: fewer objects (APP_BACKUP_OBJS)");

static void rs_head(const rs_ent_t *e, st_hdr_t *h)   /* the header storage.c would write: the copy's commit */
{
    h->magic = ST_MAGIC;
    h->type = e->obj;
    h->slot = e->copy;
    h->seq = e->seq;
    h->len = e->len;
    h->crc = e->crc;
    h->rsv[0] = h->rsv[1] = 0xFFFFFFFFu;
    h->hcrc = st_crc32(h, sizeof *h - 4u);
}

/* object e->obj's payload (bu_buf, e->len bytes) into the copy its next save would take, without its header (so
 * not there yet for st_load); the seq that will make it current */
static int rs_stage(rs_ent_t *e)
{
    st_hdr_t h;
    int cur = st_current(e->obj, &h);
    uint32_t base, off;
    e->copy = (uint16_t)(cur == 0 ? 1u : 0u);
    e->seq = cur < 0 ? 1u : h.seq + 1u;
    base = st_sector(e->obj, e->copy);
    if (st_erase(base))
        return RS_E_ERASE;
    for (off = 0; off < e->len; off += 256u) {
        uint32_t n = e->len - off > 256u ? 256u : e->len - off;
        if (st_prog(base + ST_PAYLOAD_OFF + off, bu_buf + off, n))
            return RS_E_PROG;
    }
    if (st_read(base, &h, sizeof h) || st_read(base + ST_PAYLOAD_OFF, st_buf, e->len) ||
        bu_crc(0, st_buf, e->len) != e->crc)
        return RS_E_VERIFY;
    for (off = 0; off < sizeof h; off++)              /* its header still erased: the copy not there */
        if (((const uint8_t *)&h)[off] != 0xFFu)
            return RS_E_VERIFY;
    return 0;
}

static int rs_rec_valid(void)
{
    return rs_rec.magic == RS_REC_MAGIC && rs_rec.n == BU_NOBJ &&
           rs_rec.crc == bu_crc(0, (const uint8_t *)&rs_rec, sizeof rs_rec - 4u);
}

/* the staged copies' headers (the record's), each written unless already there; 0 = all there */
static int rs_heads(void)
{
    int rc = 0;
    for (uint32_t i = 0; i < BU_NOBJ; i++) {
        st_hdr_t h, f;
        const rs_ent_t *e = &rs_rec.e[i];
        uint32_t base = st_sector(e->obj, e->copy);
        rs_head(e, &h);
        if (st_read(base, &f, sizeof f))
            rc = -1;
        else if (memcmp(&f, &h, sizeof h) && st_prog(base, &h, sizeof h))
            rc = -1;
    }
    for (uint32_t i = 0; i < BU_NOBJ; i++) {          /* each the current copy now */
        st_hdr_t h;
        const rs_ent_t *e = &rs_rec.e[i];
        if (st_current(e->obj, &h) != (int)e->copy || h.seq != e->seq || h.crc != e->crc || h.len != e->len)
            rc = -1;
    }
    return rc;
}

/* boot: a commit cut short (a power loss after its record was written) finished: 1; 0 none; -1 failed */
static int rs_boot(void)
{
    uint8_t b[4];
    uint32_t i;
    int rc;
    if (rs_rec_read(0, &rs_rec, sizeof rs_rec))
        return -1;
    if (!rs_rec_valid()) {
        for (i = 0; i < 4u; i++)                     /* a record half written or half erased: nothing to do; gone */
            b[i] = ((const uint8_t *)&rs_rec)[i];
        if (bu_rd32(b) != 0xFFFFFFFFu)
            rs_rec_erase();
        return 0;
    }
    for (i = 0; i < BU_NOBJ; i++)                     /* (a record of objects storage.c does not have: ignored) */
        if (rs_rec.e[i].obj != bu_obj(i) || rs_rec.e[i].copy > 1u || rs_rec.e[i].len > ST_PAYLOAD_MAX) {
            rs_rec_erase();
            return 0;
        }
    rc = rs_heads();
    if (rc == 0)
        rs_rec_erase();
    return rc ? -1 : 1;
}

/* every object staged: the record, the headers, the record gone. 0 = the new set is current */
static int rs_commit(void)
{
    uint32_t off;
    rs_rec.magic = RS_REC_MAGIC;
    rs_rec.n = BU_NOBJ;
    rs_rec.crc = bu_crc(0, (const uint8_t *)&rs_rec, sizeof rs_rec - 4u);
    if (rs_rec_erase())
        return RS_E_ERASE;
    for (off = 0; off < sizeof rs_rec; off += 256u) {
        uint32_t n = sizeof rs_rec - off > 256u ? 256u : sizeof rs_rec - off;
        if (rs_rec_prog(off, (const uint8_t *)&rs_rec + off, n))
            return RS_E_PROG;
    }
    {   /* read back: a record that is not whole commits nothing (the old set stays) */
        uint32_t want = rs_rec.crc;
        if (rs_rec_read(0, &rs_rec, sizeof rs_rec) || !rs_rec_valid() || rs_rec.crc != want) {
            rs_rec_erase();
            return RS_E_VERIFY;
        }
    }
    if (rs_heads())                                   /* (the record stays: the next boot tries again) */
        return RS_E_COMMIT;
    rs_rec_erase();
    return 0;
}

#ifdef APP_STORE_POOL
/* the pool's restore, after the question: the copies of every pooled object the backup holds erased (a pooled object
 * it does not, the radio's keys say, kept), then each object of the image (fetched again, each record's CRC checked
 * again) saved; 0 = done */
static int rs_rewrite(void)
{
    uint32_t pos = BU_HEAD, i, k;
    (void)rs_stage;                                   /* (the A/B pairs' staging and commit: not a pool's) */
    (void)rs_commit;
    for (i = 0; i < BU_NOBJ; i++)
        if (st_pooled(bu_obj(i)) && st_pool_drop(bu_obj(i)))
            return RS_E_ERASE;
    for (i = 0; i < BU_NOBJ; i++) {
        uint8_t r[BU_REC];
        uint32_t len, crc;
        if (rs_fetch(pos, r, BU_REC))
            return RS_E_FETCH;
        pos += BU_REC;
        len = bu_rd16(r + 2);
        crc = bu_rd32(r + 4);
        if (bu_rd16(r) != bu_obj(i) || len > ST_PAYLOAD_MAX)
            return RS_E_OBJ;
        for (k = 0; k < len; k += 512u) {
            uint32_t n = len - k > 512u ? 512u : len - k;
            if (rs_fetch(pos + k, bu_buf + k, n))
                return RS_E_FETCH;
        }
        pos += len;
        if (bu_crc(0, bu_buf, len) != crc)
            return RS_E_CRC;
#ifdef APP_STORE_POOL_EMPTY
        if (st_pooled(bu_obj(i)) && APP_STORE_POOL_EMPTY(bu_obj(i), bu_buf, len))
            len = 0;                                  /* (an older backup's placeholder: no sector, storage.c) */
#endif
        if (st_save(bu_obj(i), bu_buf, len))
            return RS_E_PROG;
        rs_show(95u + (i + 1u) * 5u / BU_NOBJ);
    }
    return 0;
}
#endif

/* the host's restore request: the image of len bytes, CRC-32 crc. Returns 0 (restored) or RS_E_*; the host is told
 * either way (rs_note); *begun: the screen was taken (a backup was coming) */
static int restore_rx(uint32_t len, uint32_t crc, int *begun_out)
{
    uint8_t hd[BU_HEAD];
    uint32_t c, pos, i, k;
    int rc = 0, begun = 0;
    if (rs_playing()) {
        rc = RS_E_PLAYING;
        goto out;
    }
    if (len < BU_HEAD + BU_NOBJ * BU_REC + 4u || len > BU_MAXIMG) {
        rc = RS_E_SIZE;
        goto out;
    }
    if (rs_fetch(0, hd, BU_HEAD)) {
        rc = RS_E_FETCH;
        goto out;
    }
    if (bu_rd32(hd) != BU_MAGIC || bu_rd16(hd + 4) != BU_VERSION || bu_rd16(hd + 6) != BU_NOBJ ||
        bu_rd32(hd + 12) != bu_crc(0, hd, 12)) {
        rc = RS_E_HEAD;
        goto out;
    }
    rs_begin();
    begun = 1;
    rs_show(0);
    c = bu_crc(0, hd, BU_HEAD);
    pos = BU_HEAD;
    for (i = 0; i < BU_NOBJ; i++) {
        rs_ent_t *e = &rs_rec.e[i];
        uint8_t r[BU_REC];
        if (rs_fetch(pos, r, BU_REC)) {
            rc = RS_E_FETCH;
            goto out;
        }
        c = bu_crc(c, r, BU_REC);
        pos += BU_REC;
        e->obj = (uint16_t)bu_rd16(r);
        e->len = bu_rd16(r + 2);
        e->crc = bu_rd32(r + 4);
        if (e->obj != bu_obj(i) || e->len > ST_PAYLOAD_MAX || pos + e->len + 4u > len) {
            rc = RS_E_OBJ;
            goto out;
        }
        for (k = 0; k < e->len; k += 512u) {
            uint32_t n = e->len - k > 512u ? 512u : e->len - k;
            if (rs_fetch(pos + k, bu_buf + k, n)) {
                rc = RS_E_FETCH;
                goto out;
            }
        }
        c = bu_crc(c, bu_buf, e->len);
        pos += e->len;
        if (bu_crc(0, bu_buf, e->len) != e->crc) {
            rc = RS_E_CRC;
            goto out;
        }
#ifndef APP_STORE_POOL
        if ((rc = rs_stage(e)) != 0)
            goto out;
#endif
        rs_show((i + 1u) * 90u / BU_NOBJ);
    }
    {
        uint8_t t[4];
        if (rs_fetch(pos, t, 4)) {
            rc = RS_E_FETCH;
            goto out;
        }
        if (bu_rd32(t) != c || pos + 4u != len || bu_crc(c, t, 4) != crc) {
            rc = RS_E_TOTAL;
            goto out;
        }
    }
    if (rs_playing()) {                               /* (started meanwhile: MIDI start) */
        rc = RS_E_PLAYING;
        goto out;
    }
    rs_note(RS_ASK_ADDR);                             /* the host: "confirm on the FM-1" */
    if (!rs_ask()) {
        rc = RS_E_NO;
        goto out;
    }
    if (rs_playing()) {
        rc = RS_E_PLAYING;
        goto out;
    }
    rs_show(95);
#ifdef APP_STORE_POOL
    if ((rc = rs_rewrite()) != 0) {
        rs_reload();                                  /* (part written: what the flash holds now) */
        goto out;
    }
    if (0) {
#else
    if ((rc = rs_commit()) != 0) {
#endif
        if (rc == RS_E_COMMIT)
            rs_reload();                              /* (headers part written: what the flash holds now) */
        goto out;
    }
    rs_reload();
    rs_show(100);
out:
    rs_note(rc ? RS_FAIL_ADDR | (uint32_t)rc : RS_OK_ADDR);
    if (begun_out)
        *begun_out = begun;
    return rc;
}

