/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* ST7789-class 240x240 panel on SPI1: PC9 CLK, PC10 DO, PC7 CS, PC8 D/C,
 * backlight PA2 active low. Polled DMA transfers; every source buffer must be
 * in RAM. A pixel transfer is left running (lcd_busy): the next LCD access, or
 * a write to its source buffer (lcd_sync), waits for it, so the main loop works
 * while the last strip of a frame goes out. */
/* pins and SPI1: hal/fm1_lcd_hw.h */
#ifndef LCD_BAUD
#define LCD_BAUD 0u                /* lsb/(BAUD+1): 0 = 60 MHz (~44 MHz effective, measured). Felucca's
                                    * 4 (12 MHz) took 23 ms for a 240x72 strip, longer than the panel's
                                    * 16.7 ms refresh: tearing. ST7789: <= ~62 MHz. The FM-1 has no TE
                                    * line; the panel's scanline can be read (RDSCL on the data wire), but
                                    * timing writes to it did not stop the tearing on hardware. */
#endif

static uint8_t lcd_small[64];
static uint8_t lcd_busy;           /* a lcd_data DMA may still run; CS is low */
#if FM1B_MIRROR
/* screen mirroring over USB (mirror.c): every blit and fill copied while a host watches */
static uint8_t mirror_on;
static void mirror_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const uint16_t *px);
static void mirror_fill(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t c);
#endif

static void lcd_spin(uint32_t n)
{
    for (volatile uint32_t i = 0; i < n; i++)
        ;
}

static void lcd_sync(void)          /* finish the running transfer (before touching its buffer) */
{
    if (!lcd_busy)
        return;
    fm1_lcd_wait();
    fm1_lcd_deselect();
    lcd_busy = 0;
}

static void lcd_cmd(uint8_t c)
{
    lcd_sync();
    fm1_lcd_send_cmd(c);
    fm1_lcd_wait();
    fm1_lcd_deselect();
}

static void lcd_data(const void *p, uint32_t n)
{
    if (!n)
        return;                    /* SPI_CNT = 0 never completes */
    lcd_sync();
    fm1_lcd_send_data(p, n);
    lcd_busy = 1;                  /* completed by lcd_sync */
}

static void lcd_window(uint32_t x0, uint32_t y0, uint32_t x1, uint32_t y1)
{
    lcd_sync();
    lcd_small[0] = (uint8_t)(x0 >> 8);
    lcd_small[1] = (uint8_t)x0;
    lcd_small[2] = (uint8_t)(x1 >> 8);
    lcd_small[3] = (uint8_t)x1;
    lcd_cmd(0x2A);
    lcd_data(lcd_small, 4);
    lcd_small[4] = (uint8_t)(y0 >> 8);       /* own bytes: the x transfer may still read [0..3] */
    lcd_small[5] = (uint8_t)y0;
    lcd_small[6] = (uint8_t)(y1 >> 8);
    lcd_small[7] = (uint8_t)y1;
    lcd_cmd(0x2B);
    lcd_data(lcd_small + 4, 4);
    lcd_cmd(0x2C);
}

static uint16_t lcd_fillbuf[240];

static void lcd_fill(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t c)
{
    uint32_t i, n, k, sw = (uint16_t)((c >> 8) | (c << 8));
    if (!w || !h || x >= 240u || y >= 240u)
        return;
    if (x + w > 240u)
        w = 240u - x;
    if (y + h > 240u)
        h = 240u - y;
#if FM1B_MIRROR
    if (mirror_on)
        mirror_fill(x, y, w, h, c);
#endif
    lcd_sync();
    k = 240u / w * w;                       /* whole rows per transfer (narrow fills: one DMA) */
    for (i = 0; i < k; i++)
        lcd_fillbuf[i] = (uint16_t)sw;
    lcd_window(x, y, x + w - 1u, y + h - 1u);
    for (n = w * h; n; n -= k) {
        if (k > n)
            k = n;
        lcd_data(lcd_fillbuf, k * 2u);
    }
}

static void lcd_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const uint16_t *px)
{
    if (!w || !h)
        return;
    lcd_window(x, y, x + w - 1u, y + h - 1u);
    lcd_data(px, w * h * 2u);
#if FM1B_MIRROR
    if (mirror_on)
        mirror_blit(x, y, w, h, px);              /* (while the DMA sends it: both only read px) */
#endif
}

/* ST7789V init: reset, then 16-bit colour, scan direction and IPS inversion;
 * voltage and gamma stay at the defaults. Format: cmd, n, n data bytes;
 * cmd 0x00 = wait (data byte: ~ms). */
static const uint8_t LCD_SEQ[] = {
    0x01, 0,                     /* SWRESET */
    0x00, 1, 150,
    0x11, 0,                     /* SLPOUT */
    0x00, 1, 120,
    0x3A, 1, 0x55,               /* COLMOD: RGB565 */
    0x36, 1, 0x00,               /* MADCTL: top-left origin, RGB order */
    0x21, 0,                     /* INVON: IPS panel */
    0x13, 0,                     /* NORON */
#if FM1B_LCD_PANEL
    /* The M-VAVE FM-1 panel's own setup (fm1.toml lcd_panel = true), the ST7789V datasheet's registers at the values the
     * panel is driven with: without them VCOMS stays at the reset value 0x20 (the panel wants 0x18), GCTRL 0x35 (0x56),
     * VRHS 0x0B (0x1F) and the gamma at its default (a VCOM off the panel's value shows as flicker). */
    0xB2, 5, 0x0C, 0x0C, 0x0C, 0x00, 0x33,   /* PORCTRL: porch */
    0xB7, 1, 0x56,                           /* GCTRL: VGH / VGL */
    0xBB, 1, 0x18,                           /* VCOMS */
    0xC0, 1, 0x2C,                           /* LCMCTRL */
    0xC2, 1, 0x01,                           /* VDVVRHEN */
    0xC3, 1, 0x1F,                           /* VRHS */
    0xC4, 1, 0x20,                           /* VDVS */
    0xC6, 1, 0x0F,                           /* FRCTRL2: 60 Hz */
    0xD0, 2, 0xA6, 0xA1,                     /* PWCTRL1 */
    0xE0, 14, 0xD0, 0x0D, 0x14, 0x0B, 0x0B, 0x07, 0x3A, 0x44, 0x50, 0x08, 0x13, 0x13, 0x2D, 0x32,   /* PVGAMCTRL */
    0xE1, 14, 0xD0, 0x0D, 0x14, 0x0B, 0x0B, 0x07, 0x3A, 0x44, 0x50, 0x08, 0x13, 0x13, 0x2D, 0x32,   /* NVGAMCTRL */
#endif
};

static void lcd_init(void)
{
    uint32_t r, x;
    fm1_lcd_hw_init();
    lcd_spin(2000000u);
    for (r = 0; r < sizeof LCD_SEQ; r += 2u + LCD_SEQ[r + 1u]) {
        if (LCD_SEQ[r] == 0x00u) {                       /* pseudo command: wait */
            lcd_spin(LCD_SEQ[r + 2u] * 25000u);          /* ~1 ms per unit (lcd_spin(3000000) ~ 120 ms) */
            continue;
        }
        lcd_cmd(LCD_SEQ[r]);
        for (x = 0; x < LCD_SEQ[r + 1u]; x++)
            lcd_small[x] = LCD_SEQ[r + 2u + x];
        if (LCD_SEQ[r + 1u])
            lcd_data(lcd_small, LCD_SEQ[r + 1u]);
    }
    fm1_lcd_baud(LCD_BAUD);
    lcd_fill(0, 0, 240, 240, 0);
    lcd_cmd(0x29);
}

text.fm1-base/device/main_fm1.c:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal
 * Boot, audio ISR and main loop adapted from Felucca's main.c / audio.c, Copyright (C) 2026
 * Leo Kuroshita (@kurogedelic), Hugelton Instruments. */
/* The platform's boot and main loop (from X0X's, by way of FoMni-1): boot (WDT first, boot-loop guard, guards), LCD, input (TIMER5
 * 10 kHz), audio (ALNK0), USB; then the main loop: UI at ~60 frames/s, input polled in between. */
extern uint32_t _data_start[], _data_end[], _data_load[], _bss_start[], _bss_end[];
extern uint32_t _pool_start[], _pool_end[], _rt_start[], _rt_end[], _rt_load[];
extern uint8_t _app_xip_end[];
#include "boot_lzma.h"

/* --------------------------------------------------------------- audio --- */
/* HALF_FRAMES (unity.c, from APP_BLOCK): the I2S half buffer, 256 frames = 5.8 ms at 44.1 kHz by default */
#define HALF_WORDS (HALF_FRAMES * 2u)
#define FS 44100u
#define REND_FRAMES HALF_FRAMES             /* app_render's frames per call */
static int32_t abuf[2u * HALF_WORDS] __attribute__((aligned(4)));

#define DBG_MAGIC 0x44424731u                       /* "DBG1": read with `fm1t memr` */
struct fm1b_dbg {
    uint32_t magic, halves, max_us, nested, in_audio, late, timer_irqs, ui_frames;
    uint32_t last_us, cpu_q12, boots, stage;
    uint32_t crash_seen;                            /* the crash count already reported at a boot */
#if FM1B_CRASHLOG
    uint32_t crash_kept, crash_saving;              /* the crash count already in the flash history; a boot's save of it
                                                     * under way (crashlog.c cl_boot: one cut short is not tried again) */
#endif
} fm1b_dbg __attribute__((section(".noinit")));
static uint8_t safe_mode;                           /* two failed boots: no audio, USB on (safe_main) */
int8_t clock_fix;                                   /* fm1_clock_stock() at the start: 0 stock already, 1 set, -1 failed */
static uint8_t power_boot[4];                       /* ANA_CON0, CON5, CON7, WLDO12_AUTO as the start found them */
static int8_t power_fix;                            /* fm1_power_stock(): 1 the DC-DC turned on, 0 it was on */
static uint32_t clock_boot[6];                      /* the clock's registers as the boot loader left them (fm1_clock_read) */
static uint8_t rails_boot[2], rails_tries;          /* VDC14's and SYSVDD's registers as the boot loader left them, and
                                                     * the raises it took to read back M-VAVE's levels (the log) */
static uint32_t wdt_stage __attribute__((section(".noinit")));   /* the main loop's step when the watchdog fired:
                                                                  * 2 Bluetooth, 3 the app's loop, 4 USB, 5 a frame,
                                                                  * 6 input, 7 the debug stats (fm1b_dbg.stage) */

#if FM1B_BT_AUDIO
static int own_bta_feed(const int32_t *o, uint32_t n);   /* bt_own_audio.c */
static int bta_frame(const uint8_t *p, uint32_t n);
#endif
#if FM1B_BLE_OWN && FM1B_BLE_CENTRAL
static int dev_frame(const uint8_t *p, uint32_t n);   /* bt_own_central.c */
#endif
#include "uac_mix.h"                                /* the USB recording, the computer's audio, in that order */
#include "fm1_flash_ok.h"                          /* the flash parts the storage may use (FM1B_FLASH_JEDEC_OK) */
#if FM1B_BT_AUDIO
static volatile uint8_t bta_streamed;               /* the last render went to Bluetooth (plat_bta_streams) */
int plat_bta_streams(void) { return bta_streamed; }
#else
int plat_bta_streams(void) { return 0; }
#endif
static void render_block(int32_t *o)                /* ALNK0: one half, measured */
{
    uint32_t t0 = fm1_ticks(), us, budget = HALF_FRAMES * 1000000u / FS;
    fm1b_dbg.in_audio = 1;
#if FELUCCA_UAC
    if (!radio_quiet)                                 /* (USB audio's code is in the flash too: none while the radio
                                                     * calibrates, when a fetch can come back corrupted; a CTL-1 crashed
                                                     * so, returning to a garbled address, 0.6 s into each start) */
        uac_render_start();
#endif
    {
        uint32_t k, gain = APP_GAIN(master_pos);
#if FELUCCA_UAC
        const int full = uac_full != 0;             /* USB audio full: the render at full level for the USB audio
                                                     * input, MASTER for the speaker after it (plat_usb_audio_full) */
#else
        const int full = 0;
#endif
        for (k = 0; k < HALF_FRAMES; k += REND_FRAMES) {
            if (radio_quiet) {                        /* the radio calibrating: no flash reads (radio.c) */
#ifdef APP_QUIET
                app_quiet(o + 2u * k, REND_FRAMES);
#else
                uint32_t i;
                for (i = 0; i < 2u * REND_FRAMES; i++)
                    o[2u * k + i] = 0;
#endif
            } else {
                app_render(o + 2u * k, REND_FRAMES, full ? 4096u : gain);
            }
            if (radio_quiet)
                continue;
            uac_mix(o + 2u * k, REND_FRAMES, gain, master_pos, full, usb_play_q12);   /* the USB
                                                     * recording, then the computer's audio, then MASTER if full */
#if FM1B_BT_AUDIO
#ifdef APP_BT_FRAMES
            bta_streamed = (uint8_t)own_bta_feed(app_bt_frames(o + 2u * k, REND_FRAMES), REND_FRAMES);   /* (the app's
                                                     * frames for Bluetooth: 0 silence) */
#else
            bta_streamed = (uint8_t)own_bta_feed(o + 2u * k, REND_FRAMES);
#endif
            if (bta_streamed) {                     /* Bluetooth audio streams: the FM-1's own output muted */
                uint32_t i;
                for (i = 0; i < 2u * REND_FRAMES; i++)
                    o[2u * k + i] = 0;
            }
#endif
        }
    }
    us = (fm1_ticks() - t0) / FM1_TICKS_PER_US;
#ifdef APP_OVERLOAD
    if (us > budget * 9u / 10u)
        app_overload();                             /* over 90 % of its time: the app sheds what it can */
#endif
    /* cpu_q12 is the load smoothed over about 16 blocks, in 1/4096 of the budget. The +8 rounds the division, so
     * a steady load settles within half a percent of its true value from either side. us * 4096 wraps above about
     * 1 s in one block, which only an interrupt stuck that long reaches: the reading is then wrong until it decays. */
    fm1b_dbg.cpu_q12 = (fm1b_dbg.cpu_q12 * 15u + us * 4096u / budget + 8u) / 16u;
    audio_cpu_pct = (fm1b_dbg.cpu_q12 * 100u + 2048u) >> 12;   /* whole percent, rounded to nearest */
    fm1b_dbg.halves++;
    fm1b_dbg.last_us = us;
    if (us > fm1b_dbg.max_us)
        fm1b_dbg.max_us = us;
    fm1b_dbg.in_audio = 0;
}

#ifndef FM1B_AUDIO_ASIDE
#define FM1B_AUDIO_ASIDE 0                          /* fm1.toml audio_aside = true: 1 */
#endif
#ifndef FM1B_AUDIO_AHEAD
#define FM1B_AUDIO_AHEAD 0                          /* fm1.toml audio_ahead = true: 1 (with FM1B_AUDIO_ASIDE) */
#endif
#if FM1B_AUDIO_ASIDE
#include "audio_commit.c"                           /* the half rendered aside, copied in while its half is free;
                                                     * FM1B_AUDIO_ASIDE 0 (the default): straight into the DMA's half */
#endif

void fm1_alnk0_irq(void)                            /* via isr_alnk0 (hal/fm1_isr.S) */
{
    uint8_t p = fm1_audio_pending();
    fm1_audio_ack_aux(p);
    if (p & FM1_AUDIO_HALF) {
        uint32_t half = fm1_audio_free_half();
#if FM1B_AUDIO_ASIDE && FM1B_AUDIO_AHEAD
        uint32_t ok;
        static uint8_t behind;                      /* (renders in a row that ran past their half) */
        fm1_audio_ack_half();
        ok = audio_commit(half);                    /* the block rendered last time */
        render_block(aside);                        /* the next: one running past its half leaves the next half
                                                     * pending, served as soon as this returns (a block's worth of
                                                     * latency for a render up to two halves long) */
        if (fm1_audio_pending() & FM1_AUDIO_HALF) {
            if (++behind >= 2u) {                   /* (two in a row: that half dropped, as without the lookahead,
                                                     * so the main loop gets its time; without this it starved) */
                fm1_audio_ack_half();
                behind = 0;
                fm1b_dbg.late++;
                audio_xruns++;
            }
        } else
            behind = 0;
        if (!ok) {
#elif FM1B_AUDIO_ASIDE
        uint32_t ok;
        fm1_audio_ack_half();                       /* (now: a new pending after the render = the DMA moved on) */
        render_block(aside);
        ok = audio_commit(half);
        if (fm1_audio_pending() & FM1_AUDIO_HALF)
            fm1_audio_ack_half();                   /* (the half missed: not rendered again) */
        if (!ok) {
#else
        render_block(&abuf[half * HALF_WORDS]);
        fm1_audio_ack_half();
        if (fm1_audio_free_half() != half) {
#endif
            fm1b_dbg.late++;                         /* the DMA moved on while we rendered */
            audio_xruns++;
        }
    }
}
extern void isr_alnk0(void);

static void audio_init(void)
{
    uint32_t i;
    for (i = 0; i < 2u * HALF_WORDS; i++)
        abuf[i] = 0;
    fm1_audio_init(abuf, HALF_WORDS, isr_alnk0, 3);
}

static void audio_silence(void)                     /* IRQs off (flash erase): the DMA would loop stale audio */
{
    uint32_t i;
    for (i = 0; i < sizeof abuf / sizeof abuf[0]; i++)
        abuf[i] = 0;
}

/* ------------------------------------------------------------ timer --- */
static uint8_t usb_due;
static uint32_t t5_gap_max, t5_late, t5_run_max;                /* the longest gap between ticks (us), and gaps over 3 ticks
                                                     * (300 us at 10 kHz): the key and light scan held up (the log reads and clears) */
void fm1_timer5_irq(void)
{
    static uint32_t sub, t5_prev;
    fm1_timer5_ack();
    {
        uint32_t now = fm1_ticks(), gap = (now - t5_prev) / FM1_TICKS_PER_US;
        if (t5_prev) {
            if (gap > t5_gap_max)
                t5_gap_max = gap;
            if (gap > FM1B_T5_LATE_US)
                t5_late++;
        }
#if FM1B_MIDI_STAMP
        /* what came in since the last tick came in, on the average, half way since: within 0.05 ms at 10 kHz (half a
         * tick: 0.1 ms at 5 kHz, 0.25 at 2; a tick
         * held up by a lock: half the gap). Every tick, the render's too: the poll below waits for the render, the
         * stamps do not. One SIE read and a look at the jack's ring */
        {
            uint32_t t = t5_prev ? now - (now - t5_prev) / 2u : now;
            usb_midi_peek(t);
#if FM1B_TRS
            uart_midi_peek(t);
#endif
        }
#endif
        t5_prev = now;
    }
    fm1b_dbg.timer_irqs++;
    if (fm1b_dbg.in_audio)
        fm1b_dbg.nested++;
#if FM1B_T5_SCAN_DIV > 1
    if (sub % FM1B_T5_SCAN_DIV == FM1B_T5_SCAN_DIV - 1u)   /* (a slower input_hz: not on the app's tick) */
#endif
        fm1_input_tick();
    /* 2 kHz (2.5 at input_hz 5000): all USB SIE traffic lives here. This ISR now nests into the audio render (so the key
     * matrix keeps its rhythm, below); USB shares the MIDI queues with the audio ISR, so a poll that
     * falls inside the render waits for the first tick outside it, as it did before the nesting. */
    if (sub % FM1B_T5_USB_DIV == 0u) {
        usb_due = 1;
#if FELUCCA_UAC && FELUCCA_UAC_CH == 2
        /* the USB audio stream cannot wait for the render (one packet per 1 ms frame, a render takes
         * up to ~11.6 ms): it runs nested too. It touches only EP4 (INDEX is set on every access) and
         * the consumer side of its ring, and usb_poll never runs nested, so the two never interleave */
        if (fm1b_dbg.in_audio)
            uac_service();
#endif
    }
#if FELUCCA_UAC && FELUCCA_UAC_CH > 2
    /* usb_audio_channels: every tick (0.1 ms: TIMER5 stays at 10 kHz whatever input_hz), nested in the render or not
     * (outside it, but for the ticks usb_poll runs: it services the stream itself). A packet of 10 channels takes ~0.6 ms on the bus: polled at 2 kHz, the next
     * was often queued after the next frame's IN, which then found none (on an FM-1: 38,400 frames/s instead of
     * 44,100, the ring overflowing, halves dropped: crackles and a lower pitch). The stall count: FELUCCA_UAC_STALL_POLLS */
    if (fm1b_dbg.in_audio || !usb_due)
        uac_service();
#endif
    if (usb_due && !fm1b_dbg.in_audio) {
        usb_due = 0;
        usb_poll();
#if FM1B_TRS
        uart_midi_poll();                           /* the TRS jack: same context, same queue */
#endif
    }
#ifdef APP_TICK
#if FM1B_T5_APP_DIV == FM1B_T5_WRAP
    if (sub == 0u) {                                /* 1 kHz: the app's tick (a clock, a sequencer) */
#else
    if (sub % FM1B_T5_APP_DIV == 0u) {
#endif
        in_tick = 1;
        app_tick();
        in_tick = 0;
    }
#endif
    if (++sub == FM1B_T5_WRAP)
        sub = 0;
    {
        uint32_t run = (fm1_ticks() - t5_prev) / FM1_TICKS_PER_US;
        if (run > t5_run_max)
            t5_run_max = run;
    }
    {
        static uint32_t last, acc;
        uint32_t now = fm1_ticks();
        acc += now - last;
        last = now;
        while (acc >= 1000u * FM1_TICKS_PER_US) {
            acc -= 1000u * FM1_TICKS_PER_US;
            fm1_ms++;
        }
    }
}
extern void isr_timer5(void);

