static char *log_dec(char *b, uint32_t v)            /* v in decimal at b; the end */
{
    char t[10];
    int n = 0;
    do {
        t[n++] = (char)('0' + v % 10u);
        v /= 10u;
    } while (v);
    while (n)
        *b++ = t[--n];
    return b;
}
