/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal */
/* The platform's own screens (boot, crash, safe mode, update, restore, calibration, the splash) write with these:
 * three faces, SYS_S (the body), SYS_B (a heading), SYS_BIG (APP_BIG_FONT: the splash's name, the panel's screens).
 * fm1-base's FONT_S, FONT_B and APP_BIG_FONT by default; an app with its own fonts sets APP_SYS_TEXT in app.h and
 * defines app_sys_h, app_sys_w and app_sys_text (static, anywhere in the app), and fm1-base's faces are not linked
 * (LOOM-8 saves 18 KB). Their text is in capitals, apart from the splash's tagline and APP_BACKUP_WHAT. */
enum { SYS_S, SYS_B, SYS_BIG };
#ifdef APP_SYS_TEXT
static int32_t app_sys_h(int face);                                 /* the face's line height */
static int32_t app_sys_w(int face, const char *s);                  /* the text's advance */
static void app_sys_text(int32_t x, int32_t y, int face, const char *s, uint16_t c);   /* on the canvas (cv_begin) */
#define sys_h app_sys_h
#define sys_w app_sys_w
#define sys_text app_sys_text
#else
static const felucca_font_t *sys_face(int face) { return face == SYS_BIG ? &APP_BIG_FONT : face == SYS_B ? &FONT_B : &FONT_S; }
static int32_t sys_h(int face) { return sys_face(face)->h; }
static int32_t sys_w(int face, const char *s) { return text_w(sys_face(face), s); }
static void sys_text(int32_t x, int32_t y, int face, const char *s, uint16_t c) { cv_text(x, y, sys_face(face), s, c); }
#endif

/* one-shot: text in a box, cleared to black, blitted (draw_text_box with a face) */
static void sys_box(uint32_t x, uint32_t y, uint32_t w, int face, const char *s, uint16_t c, int align)
{
    int32_t tw = sys_w(face, s), tx = 0;
    cv_begin(w, (uint32_t)sys_h(face), C_BLACK);
    if (align == 1)
        tx = ((int32_t)w - tw) / 2;
    else if (align == 2)
        tx = (int32_t)w - tw;
    sys_text(tx, 0, face, s, c);
    cv_blit(x, y);
    lcd_sync();
}

text.fm1-base/device/uac_mix.h:
/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 Charles Vestal */
/* USB audio around one render block (main_fm1.c render_block; tests/uac_mix_test.c), in this order:
 *   1. the USB recording (usb_audio_in: uac_tap) takes the app's render alone, so recording the FM-1 never records
 *      the computer's own playback;
 *   2. the computer's audio (usb_audio_out: uac_play) is added for the speaker and headphones, at plat_usb_play_gain's
 *      level times MASTER's (the square of its position). uac_play runs at level 0 too: it still reads the ring, so its
 *      rate tracking stays locked and turning it up again starts in step;
 *   3. with USB AUDIO full (plat_usb_audio_full; the render came at 4096), MASTER for the speaker after the tap, over
 *      both: the computer's audio was added at plat_usb_play_gain's level alone, MASTER here.
 * The includer has uac_tap and uac_play (bsp/chip/usb.c) when FELUCCA_UAC / FELUCCA_UAC_OUT are on. */
#ifndef FM1B_UAC_MIX_H
#define FM1B_UAC_MIX_H
#include <stdint.h>

/* o: n stereo frames of the render (24-bit, as the I2S takes them; at 4096 when full, else at gain); gain: MASTER's gain
 * (APP_GAIN), put on after the tap when full; master: MASTER's position 0..4096; play_q12: the computer's audio's level,
 * 0 muted .. 4096 as sent */
static inline void uac_mix(int32_t *o, uint32_t n, uint32_t gain, uint32_t master, int full, uint32_t play_q12)
{
#if FELUCCA_UAC
    uac_tap(o, n);                                  /* the USB audio input: the app's output, before the computer's */
#endif
#if FELUCCA_UAC_OUT
    uac_play(o, n, full ? play_q12 : (master * master >> 12) * play_q12 >> 12);   /* the computer's audio, at MASTER */
#else
    (void)master, (void)play_q12;
#endif
    if (full) {                                     /* the speaker and headphones: MASTER after the tap */
        const float g = (float)gain * (1.0f / 4096.0f);
        uint32_t i;
        for (i = 0; i < 2u * n; i++)
            o[i] = (int32_t)((float)o[i] * g);
    }
}
#endif

