    sys_box(0, 92, 240, SYS_S, a, C_WHITE, 1);
    if (b)
        sys_box(0, 124, 240, SYS_S, b, C_HI, 1);
}
static void rs_begin(void)                          /* a backup is coming: patient now (5 s a read, 2 min in all) */
{
    app_panic();
    ota_try_ms = 5000u;
    ota_deadline = ota_now_ms() + 120000u;
}
